import type { ЯзыкиРегиона } from "../core";

/** Названия и описания мест на zh, ko, de, fr, ja, tr, ar. */
export const ЯЗЫКИ_ТАШКЕНТА: ЯзыкиРегиона = {
  "tk-hazratimam": {
    zh: { name: "哈兹拉提·伊玛目建筑群", desc: "塔什干老城的精神中心，围绕着城市第一位伊玛目、10世纪学者兼诗人阿布·伯克尔·卡法尔·沙希的陵墓发展而成。传说他精通锁匠手艺——“卡法尔”意为“锁匠”——并通晓多种语言。陵墓周围有16世纪的巴拉克汗经学院、提拉谢赫清真寺、曾长期珍藏著名的奥斯曼《古兰经》的穆伊·穆巴拉克经学院，以及一座带双宣礼塔的新聚礼清真寺。这里是正在使用的宗教场所：请穿着得体，礼拜时不要进入清真寺。" },
    ko: { name: "하즈라티 이맘 단지", desc: "타슈켄트 구시가지의 정신적 중심지로, 도시 최초의 이맘이자 10세기 학자·시인인 아부 바크르 알카팔 알샤시의 묘를 중심으로 형성되었습니다. 전설에 따르면 그는 자물쇠와 열쇠의 장인이었고(‘카팔’은 ‘자물쇠공’이라는 뜻) 여러 언어에 능통했습니다. 영묘 주위에는 16세기 바라크 칸 마드라사, 틸라 셰이흐 모스크, 유명한 우스만 쿠란을 오랫동안 보관했던 무이 무바라크 마드라사, 그리고 두 개의 미나렛이 있는 새 금요 모스크가 있습니다. 현재 예배가 이루어지는 곳이니 단정한 복장을 하고 예배 시간에는 모스크에 들어가지 마세요." },
    de: { name: "Hazrati-Imam-Komplex", desc: "Das geistliche Herz der Taschkenter Altstadt, entstanden um das Grab von Abu Bakr al-Qaffal asch-Schaschi, dem ersten Imam der Stadt, Gelehrter und Dichter des 10. Jahrhunderts. Der Legende nach war er ein Meister der Schlösser und Schlüssel – daher „Qaffal“, „der Schlosser“ – und sprach viele Sprachen. Um das Mausoleum stehen die Barak-Khan-Medrese aus dem 16. Jahrhundert, die Tilla-Scheich-Moschee, die Muyi-Mubarak-Medrese, deren Bibliothek lange den berühmten Osman-Koran bewahrte, und eine neue Freitagsmoschee mit zwei Minaretten. Ein aktiver Gebetsort: Kleiden Sie sich zurückhaltend und betreten Sie die Moschee nicht während des Gebets." },
    fr: { name: "Complexe Hazrati Imam", desc: "Le cœur spirituel du vieux Tachkent, né autour du tombeau d'Abou Bakr al-Qaffal ach-Chachi, premier imam de la ville, savant et poète du Xe siècle. La légende en fait un maître des serrures et des clés – d'où « Qaffal », « le serrurier » – parlant de nombreuses langues. Autour du mausolée se dressent la médersa Barak Khan du XVIe siècle, la mosquée Tilla Cheikh, la médersa Muyi Mubarak dont la bibliothèque a longtemps conservé le célèbre Coran d'Othman, et une nouvelle mosquée du vendredi aux deux minarets. C'est un lieu de culte actif : tenue correcte exigée, et n'entrez pas dans la mosquée pendant la prière." },
    ja: { name: "ハズラティ・イマーム建築群", desc: "タシケント旧市街の精神的な中心で、10世紀の学者・詩人で町の初代イマームであるアブー・バクル・カッファール・シャーシーの墓を中心に形づくられました。伝説では彼は錠前と鍵の名人で（「カッファール」は「錠前師」の意）、多くの言語を話したといいます。霊廟の周りには16世紀のバラク・ハン・メドレセ、ティラ・シェイフ・モスク、かつて有名なウスマーン写本のコーランを所蔵したムイ・ムバラク・メドレセ、2本のミナレットをもつ新しい金曜モスクが並びます。現役の礼拝の場なので、肌を覆う服装で、礼拝中はモスクに入らないでください。" },
    tr: { name: "Hazreti İmam Külliyesi", desc: "Eski Taşkent'in manevi kalbi; şehrin ilk imamı, 10. yüzyıl âlimi ve şairi Ebu Bekir el-Kaffal eş-Şaşi'nin türbesi etrafında gelişmiştir. Rivayete göre kilit ve anahtar ustasıydı – “Kaffal” yani “çilingir” adı buradan gelir – ve birçok dil bilirdi. Türbenin çevresinde 16. yüzyıldan Barak Han Medresesi, Tilla Şeyh Camii, kütüphanesinde ünlü Hz. Osman Mushafı'nı uzun süre saklayan Muyi Mübarek Medresesi ve iki minareli yeni bir Cuma camii bulunur. Faal bir ibadet yeridir: kapalı giyinin ve namaz sırasında camiye girmeyin." },
    ar: { name: "مجمع حضرتي إمام", desc: "القلب الروحي لطشقند القديمة، نشأ حول ضريح أبي بكر القفّال الشاشي، أول إمام للمدينة، وهو عالم وشاعر من القرن العاشر. تقول الأسطورة إنه كان بارعًا في صناعة الأقفال والمفاتيح – ومن هنا لقب «القفّال» – وكان يتقن لغات كثيرة. حول الضريح تقوم مدرسة براق خان من القرن السادس عشر، ومسجد تلا شيخ، ومدرسة مويي مبارك التي احتفظت مكتبتها طويلًا بمصحف عثمان الشهير، ومسجد جمعة جديد بمئذنتين. إنه مكان عبادة قائم: ارتدِ ملابس محتشمة ولا تدخل المسجد أثناء الصلاة." },
  },
  "tk-kukeldash": {
    zh: { name: "库克尔达什经学院", desc: "塔什干老城二十多座经学院中最大的一座，约1570年由昔班尼王朝一位绰号“库克尔达什”的大臣修建。高大的门楼和角塔矗立在古城区的山冈上，正好俯瞰乔尔苏巴扎。院内是被两层学生宿舍环绕的庭院。建筑经受住了1866、1868和1966年的地震，曾多次修复；如今它重新成为一所学校，请保持安静、穿着得体。" },
    ko: { name: "쿠켈다시 마드라사", desc: "타슈켄트 구시가지의 스무 개가 넘는 마드라사 가운데 가장 큰 곳으로, 1570년경 ‘쿠켈다시’라는 별명을 가진 샤이반 왕조의 재상이 세웠습니다. 모서리 탑이 있는 높은 정문은 옛 샤흐리스탄 언덕 위, 초르수 바자르 바로 위에 서 있습니다. 안에는 2층 학생 방(후즈라)으로 둘러싸인 안뜰이 있습니다. 1866년, 1868년, 1966년 지진을 견뎌 냈고 여러 차례 복원되었으며, 지금은 다시 학교로 쓰이니 조용히 하고 단정하게 입으세요." },
    de: { name: "Kukeldasch-Medrese", desc: "Die größte der mehr als zwanzig Medresen des alten Taschkent, um 1570 von einem Wesir der Schaibaniden mit dem Beinamen Kukeldasch erbaut. Ihr hohes Portal mit Ecktürmchen steht auf dem Hügel des alten Schahristans, direkt über dem Chorsu-Basar. Im Inneren liegt ein Hof, umgeben von zweistöckigen Studentenzellen (Hudschras). Das Gebäude überstand die Erdbeben von 1866, 1868 und 1966 und wurde mehrfach restauriert; heute ist es wieder eine Schule – bitte ruhig sein und zurückhaltend kleiden." },
    fr: { name: "Médersa Koukeldach", desc: "La plus grande des plus de vingt médersas du vieux Tachkent, bâtie vers 1570 par un vizir des Chaybanides surnommé Koukeldach. Son haut portail flanqué de tourelles domine, sur la colline de l'ancien chahristan, le bazar Tchorsou. À l'intérieur, une cour entourée de cellules d'étudiants (hujras) sur deux niveaux. L'édifice a survécu aux séismes de 1866, 1868 et 1966 et a été restauré à plusieurs reprises ; c'est de nouveau une école, alors restez discret et habillez-vous correctement." },
    ja: { name: "クケルダシュ・メドレセ", desc: "旧タシケントに20以上あったメドレセのうち最大のもので、1570年頃、シャイバーン朝の宰相で「クケルダシュ」と呼ばれた人物が建てました。角塔をもつ高い門は旧シャフリスタンの丘の上、チョルスー・バザールの真上に建っています。中には2階建ての学生房（フジュラ）に囲まれた中庭があります。1866年、1868年、1966年の地震を耐え抜き、何度も修復されました。現在は再び学校として使われているので、静かに、控えめな服装で。" },
    tr: { name: "Kökeldaş Medresesi", desc: "Eski Taşkent'in yirmiden fazla medresesinin en büyüğü; 1570 civarında Şeybaniler'in Kökeldaş lakaplı bir veziri tarafından yaptırıldı. Köşe kuleli yüksek taç kapısı eski şehristan tepesinde, tam Çorsu Pazarı'nın üstünde yükselir. İçeride iki katlı öğrenci hücreleriyle çevrili bir avlu vardır. Bina 1866, 1868 ve 1966 depremlerini atlattı ve defalarca restore edildi; bugün yine bir okul olarak kullanılıyor, bu yüzden sessiz olun ve kapalı giyinin." },
    ar: { name: "مدرسة كوكلداش", desc: "أكبر مدارس طشقند القديمة التي تجاوز عددها العشرين، بناها نحو عام 1570 وزير لحكام الشيبانيين يُلقَّب بكوكلداش. تقف بوابتها العالية ذات الأبراج الركنية على تلة الشهرستان القديم، فوق بازار تشورسو مباشرة. وفي الداخل فناء تحيط به غرف الطلاب (الحجرات) على طابقين. صمد المبنى أمام زلازل 1866 و1868 و1966 ورُمِّم أكثر من مرة، وهو اليوم مدرسة من جديد، فالتزم الهدوء والاحتشام." },
  },
  "tk-chorsu": {
    zh: { name: "乔尔苏巴扎", desc: "塔什干最主要的巴扎，自丝绸之路时代起就在此交易，名字意为“四路交汇处”。巨大的绿松石色穹顶由弗拉基米尔·阿济莫夫和萨比尔·阿迪洛夫于1980年设计，是塔什干现代主义的晚期作品——2026年，这座巴扎与同时代的其他建筑一起被列入联合国教科文组织世界遗产名录。穹顶下有肉类、香料、干果和坚果，周围是馕饼、香草、餐具和花帽的摊位。早上来，微笑着讲价，别人请你尝什么就尝一尝。" },
    ko: { name: "초르수 바자르", desc: "실크로드 시대부터 거래가 이어져 온 타슈켄트의 대표 시장으로, 이름은 ‘네 길이 만나는 곳’이라는 뜻입니다. 거대한 청록색 돔은 1980년 블라디미르 아지모프와 사비르 아딜로프가 설계한 타슈켄트 모더니즘의 후기 작품으로, 2026년 같은 시대의 다른 건물들과 함께 유네스코 세계유산에 등재되었습니다. 돔 아래에는 고기, 향신료, 말린 과일과 견과류가, 주변에는 빵, 허브, 그릇, 전통 모자 가게가 늘어서 있습니다. 아침에 가서 웃으며 흥정하고, 권하는 것은 맛보세요." },
    de: { name: "Chorsu-Basar", desc: "Taschkents wichtigster Basar, auf dem seit Seidenstraßenzeiten gehandelt wird; der Name bedeutet „Kreuzung von vier Wegen“. Die riesige türkisfarbene Kuppel entwarfen Wladimir Asimow und Sabir Adylow 1980 – ein spätes Beispiel der Taschkenter Moderne; 2026 wurden der Basar und andere Bauten dieser Epoche in die UNESCO-Welterbeliste aufgenommen. Unter der Kuppel gibt es Fleisch, Gewürze, Trockenobst und Nüsse, ringsum Reihen mit Brot, Kräutern, Geschirr und Käppchen. Kommen Sie morgens, handeln Sie mit einem Lächeln und probieren Sie, was man Ihnen anbietet." },
    fr: { name: "Bazar Tchorsou", desc: "Le grand bazar de Tachkent, où l'on commerce depuis l'époque de la route de la soie ; son nom signifie « croisement de quatre routes ». L'immense coupole turquoise, conçue en 1980 par Vladimir Azimov et Sabir Adylov, est un exemple tardif du modernisme de Tachkent – en 2026, le bazar et d'autres édifices de cette époque ont été inscrits au patrimoine mondial de l'UNESCO. Sous la coupole : viande, épices, fruits secs et noix ; autour, des rangées de pains, d'herbes, de vaisselle et de calottes. Venez le matin, marchandez avec le sourire et goûtez ce qu'on vous propose." },
    ja: { name: "チョルスー・バザール", desc: "シルクロードの時代から商いが続くタシケント最大のバザールで、名前は「四つの道の交差点」を意味します。巨大なターコイズ色のドームは1980年にウラジーミル・アジモフとサビル・アディロフが設計したタシケント・モダニズム後期の作品で、2026年に同時代の他の建物とともにユネスコ世界遺産に登録されました。ドームの下には肉、香辛料、ドライフルーツ、ナッツ、周りにはナン、ハーブ、食器、帽子の売り場が並びます。朝に訪れ、笑顔で値切り、勧められたものは味見してみましょう。" },
    tr: { name: "Çorsu Pazarı", desc: "İpek Yolu döneminden beri ticaret yapılan Taşkent'in ana pazarı; adı “dört yolun kavşağı” demektir. Dev turkuaz kubbe 1980'de Vladimir Azimov ve Sabir Adılov tarafından tasarlandı ve Taşkent modernizminin geç bir örneğidir – 2026'da pazar ve aynı dönemin diğer yapıları UNESCO Dünya Mirası Listesi'ne alındı. Kubbenin altında et, baharat, kuru meyve ve kuruyemiş, çevresinde ekmek, yeşillik, tabak çanak ve takke tezgâhları bulunur. Sabah gelin, gülümseyerek pazarlık edin ve size ikram edileni tadın." },
    ar: { name: "بازار تشورسو", desc: "السوق الرئيسية في طشقند، حيث تجري التجارة منذ زمن طريق الحرير، ويعني اسمها «ملتقى الطرق الأربعة». صمّم القبة الفيروزية الضخمة فلاديمير أزيموف وصابر أديلوف عام 1980، وهي مثال متأخر على حداثة طشقند المعمارية، وفي عام 2026 أُدرجت السوق مع مبانٍ أخرى من تلك الحقبة في قائمة التراث العالمي لليونسكو. تحت القبة اللحوم والتوابل والفواكه المجففة والمكسرات، وحولها صفوف الخبز والأعشاب والأواني والقلانس. تعال صباحًا، وساوِم بابتسامة، وتذوّق ما يُقدَّم لك." },
  },
  "tk-sheikhantaur": {
    zh: { name: "谢赫汉陶尔建筑群", desc: "位于塔什干市中心的纪念建筑群，围绕13至14世纪苏菲、哈里发欧麦尔后裔谢赫·霍文迪·塔胡尔的陵墓而建，他被尊为城市的守护圣人之一。附近有15世纪哈萨克统治者卡尔德尔加奇比的陵墓，其金字塔形穹顶十分独特，还有同时代的尤努斯汗陵墓。建筑群位于纳沃伊大街一处林荫广场中，是从阿米尔·帖木儿广场前往老城途中的好去处。" },
    ko: { name: "셰이한타우르 단지", desc: "타슈켄트 한복판에 있는 기념 단지로, 13~14세기의 수피이자 칼리프 우마르의 후손으로 도시의 수호 성인 중 한 명으로 추앙받는 셰이흐 호벤디 앗타후르의 영묘를 중심으로 합니다. 근처에는 독특한 피라미드형 돔을 가진 15세기 카자흐 통치자 칼디르가치 비의 영묘와 같은 시대의 유누스 칸 영묘가 있습니다. 나보이 거리의 그늘진 광장에 있어 아미르 티무르 광장과 구시가지 사이에 들르기 좋습니다." },
    de: { name: "Scheichantaur-Ensemble", desc: "Ein Gedenkkomplex im Zentrum Taschkents um das Mausoleum von Scheich Howendi at-Tahur, einem Sufi des 13.–14. Jahrhunderts und Nachfahren des Kalifen Umar, der als einer der Schutzheiligen der Stadt verehrt wird. Daneben stehen das Mausoleum des kasachischen Herrschers Kaldirgatsch Bi aus dem 15. Jahrhundert mit ungewöhnlicher Pyramidenkuppel und das Yunus-Khan-Mausoleum aus derselben Zeit. Das Ensemble liegt in einem schattigen Park an der Navoi-Straße – ein guter Halt zwischen dem Amir-Temur-Platz und der Altstadt." },
    fr: { name: "Ensemble Cheikhantaour", desc: "Un complexe mémorial en plein centre de Tachkent autour du mausolée du cheikh Hovendi at-Tahour, soufi des XIIIe–XIVe siècles et descendant du calife Omar, vénéré comme l'un des saints patrons de la ville. À côté se trouvent le mausolée de Kaldirgatch Biy, souverain kazakh du XVe siècle, à l'insolite coupole pyramidale, et le mausolée de Younous Khan de la même époque. L'ensemble occupe un square ombragé de la rue Navoï – une bonne étape entre la place Amir Timour et la vieille ville." },
    ja: { name: "シェイハンタウル建築群", desc: "タシケント中心部にある記念建築群で、13～14世紀のスーフィーでカリフ・ウマルの子孫とされ、町の守護聖者の一人として崇敬されるシェイフ・ホヴェンディ・アッタフルの霊廟を中心としています。近くには珍しいピラミッド型ドームをもつ15世紀のカザフの君主カルディルガチ・ビーの霊廟や、同時代のユヌス・ハン廟があります。ナヴォイ通りの木陰の広場にあり、アミール・ティムール広場と旧市街の間に立ち寄るのに便利です。" },
    tr: { name: "Şeyhantavur Külliyesi", desc: "Taşkent'in tam merkezinde, 13.–14. yüzyıl sufisi, Hz. Ömer'in soyundan gelen ve şehrin koruyucu velilerinden sayılan Şeyh Hovendi et-Tahur'un türbesi etrafındaki anıt külliye. Yakınında alışılmadık piramit kubbeli, 15. yüzyıl Kazak hükümdarı Kaldırgaç Bey'in türbesi ve aynı döneme ait Yunus Han Türbesi bulunur. Külliye Nevai Caddesi'ndeki gölgeli bir parkta yer alır – Emir Timur Meydanı ile eski şehir arasında güzel bir durak." },
    ar: { name: "مجمع شيخانتاور", desc: "مجمع تذكاري في قلب طشقند حول ضريح الشيخ خاوندي الطهور، الصوفي من القرنين الثالث عشر والرابع عشر ومن نسل الخليفة عمر، والمبجَّل بوصفه أحد أولياء المدينة الحامين. وبالقرب منه ضريح الحاكم الكازاخي قالديرغاتش بي من القرن الخامس عشر بقبته الهرمية غير المألوفة، وضريح يونس خان من الحقبة نفسها. يقع المجمع في ساحة ظليلة بشارع نوائي، وهو محطة مناسبة بين ساحة أمير تيمور والمدينة القديمة." },
  },
  "tk-zangiota": {
    zh: { name: "赞吉阿塔纪念建筑群", desc: "塔什干州最受尊崇的朝圣地之一，位于首都中心西南15公里处。这里安葬着被称为赞吉阿塔的苏菲长老阿伊·霍贾，他是塔什干一系列圣人的精神先祖；墓上的陵墓建于帖木儿时代。附近有他妻子安巴尔·比比的陵墓，妇女们来此祈求子嗣，此外还有清真寺、经学院和林荫花园。这里是正在使用的宗教场所：请保持安静并遵守着装要求。" },
    ko: { name: "잔기 오타 기념 단지", desc: "수도 중심에서 남서쪽으로 15km 떨어진, 타슈켄트주에서 가장 존경받는 순례지 중 하나입니다. 타슈켄트 성인 계보의 영적 시조로 ‘잔기 오타’라 불린 수피 셰이흐 아이호자가 묻힌 곳으로, 묘 위의 영묘는 아미르 티무르 시대에 세워졌습니다. 근처에는 여성들이 아이를 기원하러 찾는 그의 아내 암바르 비비의 영묘와 모스크, 마드라사, 그늘진 정원이 있습니다. 현재 예배가 이루어지는 곳이니 조용히 하고 복장 규정을 지키세요." },
    de: { name: "Gedenkkomplex Zangi Ota", desc: "Eine der meistverehrten Pilgerstätten der Region Taschkent, 15 km südwestlich des Zentrums der Hauptstadt. Hier ruht der Sufi-Scheich Ay-Khoja, genannt Zangi Ota, geistiger Stammvater einer ganzen Reihe Taschkenter Heiliger; das Mausoleum über seinem Grab entstand zur Zeit Amir Temurs. Daneben liegen das Mausoleum seiner Frau Ambar Bibi, wo Frauen um Kinder beten, eine Moschee, eine Medrese und ein schattiger Garten. Ein aktiver Gebetsort: Bitte ruhig sein und die Kleiderordnung beachten." },
    fr: { name: "Complexe mémorial de Zangui Ota", desc: "L'un des lieux de pèlerinage les plus vénérés de la région de Tachkent, à 15 km au sud-ouest du centre de la capitale. Ici repose le cheikh soufi Aï-Khodja, dit Zangui Ota, ancêtre spirituel de toute une lignée de saints de Tachkent ; le mausolée sur sa tombe date de l'époque d'Amir Timour. À côté se trouvent le mausolée de son épouse Ambar Bibi, où les femmes viennent prier pour avoir des enfants, une mosquée, une médersa et un jardin ombragé. Lieu de culte actif : restez discret et respectez la tenue exigée." },
    ja: { name: "ザンギ・オタ記念建築群", desc: "首都の中心から南西へ15km、タシケント州で最も崇敬される巡礼地の一つです。タシケントの聖者たちの精神的な祖とされ「ザンギ・オタ」と呼ばれたスーフィーのシェイフ、アイ・ホジャが眠り、墓の上の霊廟はアミール・ティムールの時代に建てられました。近くには女性たちが子宝を祈りに訪れる妻アンバル・ビビの霊廟、モスク、メドレセ、木陰の庭園があります。現役の礼拝の場なので、静かにし、服装の決まりを守ってください。" },
    tr: { name: "Zengi Ata Anıt Külliyesi", desc: "Başkentin merkezinin 15 km güneybatısında, Taşkent bölgesinin en saygın ziyaret yerlerinden biri. Taşkent velilerinin manevi atası sayılan ve Zengi Ata diye anılan sufi şeyh Ay-Hoca burada yatar; mezarının üzerindeki türbe Emir Timur döneminde yapıldı. Yakınında kadınların çocuk dilemek için geldiği eşi Anber Bibi'nin türbesi, bir cami, bir medrese ve gölgeli bir bahçe bulunur. Faal bir ibadet yeridir: sessiz olun ve kıyafet kurallarına uyun." },
    ar: { name: "مجمع زنكي آتا التذكاري", desc: "من أكثر أماكن الزيارة تبجيلًا في ولاية طشقند، على بعد 15 كم جنوب غرب مركز العاصمة. هنا يرقد الشيخ الصوفي آي خواجه المعروف بزنكي آتا، الجد الروحي لسلسلة كاملة من أولياء طشقند، وقد بُني الضريح فوق قبره في عهد أمير تيمور. وبالقرب منه ضريح زوجته عنبر بيبي، حيث تأتي النساء للدعاء بالذرية، ومسجد ومدرسة وحديقة ظليلة. إنه مكان عبادة قائم: التزم الهدوء وقواعد اللباس." },
  },
  "tk-suzukota": {
    zh: { name: "苏祖克阿塔建筑群", desc: "位于塔什干老城一处马哈拉中的纪念建筑群，围绕着受人尊敬的长老苏祖克阿塔的陵墓，当地人几个世纪以来一直来此拜谒。近年来建筑群经过修复：一座带木柱雕花廊台的清真寺、铺着图案瓷砖的宽敞庭院和四周的回廊。这里安静而充满生活气息，几乎没有游客——可以看到这座城市日常的宗教生活。请穿着得体。" },
    ko: { name: "수주크 오타 단지", desc: "타슈켄트 구시가지 마할라에 있는 기념 단지로, 현지 사람들이 수백 년 동안 찾아온 존경받는 셰이흐 수주크 오타의 영묘를 중심으로 합니다. 최근 복원되어 나무 기둥에 조각된 아이반이 있는 모스크, 무늬 타일이 깔린 넓은 안뜰, 사방의 회랑을 갖추고 있습니다. 관광객이 거의 없는 조용하고 살아 있는 예배 장소로, 도시의 일상적인 신앙생활을 볼 수 있습니다. 단정하게 입으세요." },
    de: { name: "Suzuk-Ota-Komplex", desc: "Ein Gedenkkomplex in einer Mahalla der Taschkenter Altstadt um das Mausoleum von Suzuk Ota, einem verehrten Scheich, dessen Grab die Einheimischen seit Jahrhunderten besuchen. In den letzten Jahren wurde das Ensemble restauriert: eine Moschee mit geschnitztem Aiwan auf Holzsäulen, ein weiter Hof mit gemusterten Fliesen und Galerien ringsum. Ein ruhiger, lebendiger Gebetsort fast ohne Touristen – ein Einblick in das alltägliche religiöse Leben der Stadt. Bitte zurückhaltend kleiden." },
    fr: { name: "Complexe Souzouk Ota", desc: "Un complexe mémorial dans une mahalla de la vieille ville de Tachkent autour du mausolée de Souzouk Ota, cheikh vénéré dont les habitants visitent la tombe depuis des siècles. L'ensemble a été restauré ces dernières années : une mosquée avec un aïvan sculpté sur colonnes de bois, une vaste cour pavée de carreaux à motifs et des galeries tout autour. Un lieu de culte calme et vivant, presque sans touristes – l'occasion de voir la vie religieuse quotidienne de la ville. Tenue correcte exigée." },
    ja: { name: "スズク・オタ建築群", desc: "タシケント旧市街のマハッラにある記念建築群で、地元の人々が何世紀にもわたって参拝してきた尊いシェイフ、スズク・オタの霊廟を中心としています。近年修復され、木の柱に彫刻を施したアイヴァンのあるモスク、模様タイルを敷いた広い中庭、周囲の回廊が整いました。観光客のほとんどいない静かで生きた礼拝の場で、町の日常の信仰生活を垣間見られます。控えめな服装で。" },
    tr: { name: "Suzuk Ata Külliyesi", desc: "Eski Taşkent'in bir mahallesinde, yerlilerin yüzyıllardır ziyaret ettiği saygın şeyh Suzuk Ata'nın türbesi etrafındaki anıt külliye. Son yıllarda restore edildi: ahşap sütunlar üzerinde oymalı eyvanı olan bir cami, desenli çinilerle döşeli geniş bir avlu ve çevresinde revaklar. Neredeyse hiç turistin olmadığı sakin ve canlı bir ibadet yeri – şehrin gündelik dini yaşamını görme fırsatı. Kapalı giyinin." },
    ar: { name: "مجمع سوزوك آتا", desc: "مجمع تذكاري في محلة من محلات طشقند القديمة حول ضريح سوزوك آتا، الشيخ المبجَّل الذي يزور السكان قبره منذ قرون. رُمِّم المجمع في السنوات الأخيرة: مسجد بإيوان منحوت على أعمدة خشبية، وفناء فسيح مرصوف ببلاط مزخرف، وأروقة من حوله. مكان عبادة هادئ وحيّ يكاد يخلو من السياح – فرصة لرؤية الحياة الدينية اليومية في المدينة. ارتدِ ملابس محتشمة." },
  },
  "tk-zayniddin": {
    zh: { name: "谢赫·扎伊尼丁·博博陵墓", desc: "老城库克恰街区一处安静的角落，这里有苏赫拉瓦尔迪苏菲教团传教者谢赫·扎伊尼丁·博博的陵墓，传说他是该教团创始人之子。带穹顶的陵墓建于16世纪，旁边保存着一间地下“奇拉哈纳”静修室，相传长老曾在此进行四十天的闭关祈祷。周围有古老的墓地、清真寺和绿树成荫的院落。这是正在使用的圣地：请穿着得体。" },
    ko: { name: "셰이흐 자이니딘 보보 영묘", desc: "구시가지 쿠크차 지구의 조용한 구석에 있는 영묘로, 수흐라와르디 수피 교단의 설교자이자 전승에 따르면 교단 창시자의 아들인 셰이흐 자이니딘 보보가 잠들어 있습니다. 돔 영묘는 16세기에 지어졌고, 옆에는 셰이흐가 40일 동안 기도하며 은거했다고 전하는 지하 칠라하나가 남아 있습니다. 주변에는 오래된 묘지와 모스크, 나무가 우거진 마당이 있습니다. 현재도 참배가 이어지는 곳이니 단정하게 입으세요." },
    de: { name: "Mausoleum Scheich Zayniddin Bobo", desc: "Eine stille Ecke des alten Viertels Kuktscha mit dem Mausoleum von Scheich Zayniddin Bobo, einem Prediger des Suhrawardiyya-Sufiordens, den die Überlieferung den Sohn des Ordensgründers nennt. Das Kuppelmausoleum stammt aus dem 16. Jahrhundert; daneben ist eine unterirdische Tschillachana erhalten, in der der Scheich der Legende nach vierzigtägige Gebetsklausuren hielt. Ringsum liegen ein alter Friedhof, eine Moschee und ein baumbestandener Hof. Ein aktives Heiligtum: bitte zurückhaltend kleiden." },
    fr: { name: "Mausolée du cheikh Zaïniddin Bobo", desc: "Un coin paisible du vieux quartier de Koukcha avec le mausolée du cheikh Zaïniddin Bobo, prédicateur de l'ordre soufi Suhrawardiyya que la tradition dit fils de son fondateur. Le mausolée à coupole date du XVIe siècle ; à côté subsiste une tchillakhana souterraine où, selon la légende, le cheikh passait des retraites de prière de quarante jours. Autour : un vieux cimetière, une mosquée et une cour arborée. Sanctuaire actif : tenue correcte exigée." },
    ja: { name: "シェイフ・ザイニッディン・ボボ廟", desc: "旧市街ククチャ地区の静かな一角にあり、スフラワルディー教団の説教師で、伝承では教団創始者の息子とされるシェイフ・ザイニッディン・ボボが眠ります。ドームのある霊廟は16世紀のもので、隣にはシェイフが40日間の祈りの籠もりを行ったと伝わる地下のチッラハナが残ります。周囲には古い墓地、モスク、木立の中庭があります。現役の聖地なので控えめな服装で。" },
    tr: { name: "Şeyh Zeyneddin Baba Türbesi", desc: "Eski Kökçe mahallesinin sakin bir köşesinde, Sühreverdiyye tarikatının vaizi ve rivayete göre tarikat kurucusunun oğlu olan Şeyh Zeyneddin Baba'nın türbesi. Kubbeli türbe 16. yüzyıldan kalmadır; yanında, şeyhin kırk günlük halvetlere girdiği rivayet edilen yer altı çilehanesi korunmuştur. Çevresinde eski bir mezarlık, bir cami ve ağaçlı bir avlu vardır. Faal bir ziyaretgâh: kapalı giyinin." },
    ar: { name: "ضريح الشيخ زين الدين بابا", desc: "ركن هادئ في حي كوكتشا القديم يضم ضريح الشيخ زين الدين بابا، الداعية في الطريقة السهروردية الصوفية الذي تجعله الرواية ابنًا لمؤسسها. يعود الضريح ذو القبة إلى القرن السادس عشر، وبجانبه خلوة «جلّه خانه» تحت الأرض يُروى أن الشيخ كان يعتكف فيها أربعين يومًا للصلاة. وحوله مقبرة قديمة ومسجد وفناء تظلله الأشجار. مزار قائم: ارتدِ ملابس محتشمة." },
  },
  "tk-mingurik": {
    zh: { name: "明乌里克考古遗址", desc: "位于现代塔什干市中心的一座土丘，下面埋藏着一座中世纪早期城镇的遗迹——塔什干的前身、古代石国（恰奇）的中心之一。考古学家发掘出城区街坊、要塞城墙和跨越许多世纪的文化层。如今这里被辟为考古公园，有步道和遮盖发掘区的顶棚，可以看看这座城市脚下的“根基”。请提前确认开放时间。" },
    ko: { name: "밍우리크 유적", desc: "현대 타슈켄트 한가운데 있는 언덕으로, 타슈켄트의 전신인 고대 차치의 중심지 중 하나였던 중세 초기 도시의 유적이 묻혀 있습니다. 고고학자들은 샤흐리스탄 구역과 성채 성벽, 수백 년에 걸친 문화층을 발굴했습니다. 지금은 산책로와 발굴지 위 차양을 갖춘 고고학 공원으로 꾸며져, 도시가 딛고 선 ‘토대’를 볼 수 있습니다. 개방 시간은 미리 확인하세요." },
    de: { name: "Ausgrabungsstätte Ming Urik", desc: "Ein Hügel mitten im modernen Taschkent, der die Reste einer frühmittelalterlichen Stadt birgt – eines der Zentren des alten Tschatsch, des Vorläufers von Taschkent. Archäologen legten Viertel des Schahristans, Zitadellenmauern und Kulturschichten über viele Jahrhunderte frei. Heute ist die Stätte als archäologischer Park mit Wegen und Schutzdächern über den Grabungen gestaltet – ein Blick auf die „Fundamente“, auf denen die Stadt steht. Öffnungszeiten vorher prüfen." },
    fr: { name: "Site archéologique de Ming Ourik", desc: "Une butte au cœur du Tachkent moderne qui cache les restes d'une ville du haut Moyen Âge – l'un des centres de l'ancien Tchatch, ancêtre de Tachkent. Les archéologues ont dégagé des quartiers du chahristan, des murs de citadelle et des couches couvrant de nombreux siècles. Le site est aujourd'hui aménagé en parc archéologique, avec allées et auvents au-dessus des fouilles – un regard sur les « fondations » de la ville. Vérifiez les horaires à l'avance." },
    ja: { name: "ミング・ウリク遺跡", desc: "現代のタシケントの真ん中にある丘で、タシケントの前身である古代チャーチの中心の一つだった中世初期の町の遺構が眠っています。考古学者たちはシャフリスタンの街区、城塞の壁、何世紀にもわたる文化層を発掘しました。現在は遊歩道と発掘区の屋根を備えた考古学公園として整備され、町が立つ「土台」を見ることができます。開館時間は事前に確認を。" },
    tr: { name: "Ming Ürik Arkeolojik Alanı", desc: "Modern Taşkent'in ortasında, Taşkent'in öncüsü olan eski Çaç'ın merkezlerinden biri olan erken Orta Çağ kasabasının kalıntılarını saklayan bir höyük. Arkeologlar şehristan mahallelerini, iç kale surlarını ve yüzyıllara uzanan kültür katmanlarını ortaya çıkardı. Bugün alan, yürüyüş yolları ve kazıların üzerinde gölgeliklerle bir arkeoloji parkı olarak düzenlenmiştir – şehrin üzerinde durduğu “temellere” bir bakış. Açılış saatlerini önceden kontrol edin." },
    ar: { name: "موقع مينغ أوريك الأثري", desc: "تلّ في وسط طشقند الحديثة يخفي بقايا بلدة من أوائل العصور الوسطى – أحد مراكز «تشاش» القديمة، سلف طشقند. كشف علماء الآثار عن أحياء الشهرستان وأسوار القلعة وطبقات ثقافية تمتد عبر قرون عديدة. والموقع اليوم حديقة أثرية بممرات ومظلات فوق الحفريات – نظرة إلى «الأساسات» التي تقوم عليها المدينة. تحقّق من مواعيد الفتح مسبقًا." },
  },
  "tk-amirtemur": {
    zh: { name: "阿米尔·帖木儿广场", desc: "现代塔什干的心脏：一座建于1882年的圆形广场，原名康斯坦丁诺夫广场，中央矗立着阿米尔·帖木儿骑马像。主要街道从这里向四周延伸，周围是城市地标——乌兹别克斯坦酒店、塔什干钟楼、论坛宫和帖木儿王朝历史博物馆的蓝色穹顶。傍晚灯光和喷泉亮起，市民纷纷出来散步——这里是开始游览首都的好地方。" },
    ko: { name: "아미르 티무르 광장", desc: "현대 타슈켄트의 심장부로, 1882년 콘스탄티노프스키 광장으로 조성된 원형 광장 한가운데에 아미르 티무르 기마상이 서 있습니다. 주요 거리가 이곳에서 사방으로 뻗어 나가고, 주변에는 호텔 우즈베키스탄, 타슈켄트 시계탑, 국제포럼궁전, 티무르 왕조 역사박물관의 파란 돔 같은 명소가 있습니다. 저녁이면 조명과 분수가 켜지고 시민들이 산책을 나옵니다. 수도 여행을 시작하기 좋은 곳입니다." },
    de: { name: "Amir-Temur-Platz", desc: "Das Herz des modernen Taschkent: ein runder Platz, 1882 als Konstantinowski-Platz angelegt, mit einem Reiterstandbild Amir Temurs in der Mitte. Von hier strahlen die Hauptstraßen aus, ringsum stehen die Wahrzeichen der Stadt – das Hotel Usbekistan, das Taschkenter Glockenspiel, der Palast der Foren und die blaue Kuppel des Museums der Timuridengeschichte. Abends gehen Lichter und Springbrunnen an und die Einheimischen flanieren – ein guter Ausgangspunkt für die Hauptstadt." },
    fr: { name: "Place Amir Timour", desc: "Le cœur du Tachkent moderne : une place ronde aménagée en 1882 sous le nom de place Konstantinovski, avec en son centre la statue équestre d'Amir Timour. Les grandes rues en rayonnent, et tout autour se dressent les repères de la ville – l'hôtel Ouzbékistan, le carillon de Tachkent, le palais des Forums et la coupole bleue du musée de l'Histoire des Timourides. Le soir, lumières et fontaines s'allument et les habitants sortent se promener – un bon point de départ pour découvrir la capitale." },
    ja: { name: "アミール・ティムール広場", desc: "現代タシケントの中心。1882年にコンスタンチノフスキー広場として造られた円形の広場で、中央にアミール・ティムールの騎馬像が立ちます。大通りがここから放射状に延び、周りにはホテル・ウズベキスタン、タシケントの時計塔、国際フォーラム宮殿、ティムール朝歴史博物館の青いドームといった名所が並びます。夕方には照明と噴水が灯り、市民が散歩に出てきます。首都観光の起点にぴったりです。" },
    tr: { name: "Emir Timur Meydanı", desc: "Modern Taşkent'in kalbi: 1882'de Konstantinovski Meydanı olarak düzenlenen ve ortasında Emir Timur'un atlı heykeli bulunan yuvarlak bir meydan. Ana caddeler buradan yayılır; çevresinde Özbekistan Oteli, Taşkent Çan Kulesi, Forumlar Sarayı ve Timurlular Tarihi Müzesi'nin mavi kubbesi gibi şehrin simgeleri yer alır. Akşamları ışıklar ve fıskiyeler yanar, halk yürüyüşe çıkar – başkenti keşfetmeye başlamak için harika bir yer." },
    ar: { name: "ساحة أمير تيمور", desc: "قلب طشقند الحديثة: ساحة دائرية خُطّطت عام 1882 باسم ساحة كونستانتينوفسكي، يتوسطها تمثال فروسي لأمير تيمور. تتفرع منها الشوارع الرئيسية، وحولها معالم المدينة – فندق أوزبكستان، وساعة طشقند الدقّاقة، وقصر المنتديات، والقبة الزرقاء لمتحف تاريخ التيموريين. في المساء تُضاء الأنوار والنوافير ويخرج السكان للتنزه – مكان رائع لبدء استكشاف العاصمة." },
  },
  "tk-mustaqillik": {
    zh: { name: "独立广场", desc: "国家的主广场，更像一座有喷泉、花坛和林荫道的巨大公园。中央是独立纪念碑：一个勾勒出乌兹别克斯坦轮廓的金色地球仪，以及怀抱婴儿的幸福母亲雕像。入口处是顶上立着鹳鸟的“善良”拱门，再往里是“哀悼的母亲”纪念碑，两侧长廊上刻着第二次世界大战中牺牲者的名字。这里会举行阅兵和庆典；政府大楼附近的部分区域可能不开放。" },
    ko: { name: "독립 광장", desc: "나라의 중심 광장으로, 분수와 화단, 가로수길이 있는 거대한 공원에 가깝습니다. 중앙에는 우즈베키스탄 윤곽이 새겨진 황금 지구본과 아기를 안은 행복한 어머니상으로 이루어진 독립 기념비가 있습니다. 입구에는 황새가 올라앉은 ‘에즈굴리크(선)’ 아치가 있고, 더 안쪽에는 제2차 세계대전 전사자의 이름이 새겨진 회랑과 ‘슬퍼하는 어머니’ 기념비가 있습니다. 퍼레이드와 축제가 열리며, 정부 청사 근처 일부 구역은 출입이 제한될 수 있습니다." },
    de: { name: "Unabhängigkeitsplatz", desc: "Der Hauptplatz des Landes, eher ein riesiger Park mit Springbrunnen, Blumenbeeten und Alleen. In der Mitte steht das Unabhängigkeitsdenkmal: ein goldener Globus mit den Umrissen Usbekistans und die Figur einer glücklichen Mutter mit ihrem Kind. Den Eingang krönt der Ezgulik-Bogen („Güte“) mit Störchen, weiter innen liegt das Denkmal der trauernden Mutter mit Galerien, in denen die Namen der im Zweiten Weltkrieg Gefallenen stehen. Hier finden Paraden und Feste statt; Bereiche nahe Regierungsgebäuden können gesperrt sein." },
    fr: { name: "Place de l'Indépendance", desc: "La grande place du pays, plutôt un immense parc avec fontaines, parterres et allées. Au centre, le monument de l'Indépendance : un globe doré portant le contour de l'Ouzbékistan et la statue d'une mère heureuse avec son bébé. L'entrée est couronnée par l'arc Ezgulik (« Bonté ») surmonté de cigognes, et plus loin se trouve le mémorial de la Mère en deuil, avec des galeries portant les noms des morts de la Seconde Guerre mondiale. Défilés et fêtes s'y tiennent ; certaines zones proches des bâtiments gouvernementaux peuvent être fermées." },
    ja: { name: "独立広場", desc: "国の中心となる広場で、噴水や花壇、並木道のある巨大な公園のようです。中央には独立記念碑があり、ウズベキスタンの輪郭を描いた金色の地球儀と、赤ん坊を抱く幸福な母の像が立ちます。入口にはコウノトリが乗る「エズグリク（善）」のアーチ、奥には第二次世界大戦の戦没者の名を刻んだ回廊と「嘆きの母」の記念碑があります。パレードや祝典が行われ、政府庁舎近くの一部は立ち入りが制限されることがあります。" },
    tr: { name: "Bağımsızlık Meydanı", desc: "Ülkenin ana meydanı; daha çok fıskiyeli, çiçek tarhlı ve ağaçlı yollu dev bir parka benzer. Ortasında Bağımsızlık Anıtı vardır: Özbekistan'ın haritası işlenmiş altın bir küre ve bebeğini kucaklayan mutlu bir anne heykeli. Girişi leylekli Ezgülük (“İyilik”) Kemeri taçlandırır; daha içeride, İkinci Dünya Savaşı'nda ölenlerin adlarının yazılı olduğu galerilerle Yaslı Anne anıtı bulunur. Burada geçit törenleri ve kutlamalar yapılır; hükümet binalarına yakın bazı alanlar kapalı olabilir." },
    ar: { name: "ساحة الاستقلال", desc: "الساحة الرئيسية في البلاد، وهي أشبه بحديقة ضخمة بالنوافير وأحواض الزهور والممرات. في وسطها نصب الاستقلال: كرة ذهبية تحمل خريطة أوزبكستان وتمثال أمّ سعيدة تحتضن رضيعها. يتوّج المدخلَ قوسُ «إزغوليك» (الخير) تعلوه طيور اللقلق، وفي الداخل نصب «الأم الحزينة» مع أروقة تحمل أسماء من سقطوا في الحرب العالمية الثانية. تُقام هنا العروض والاحتفالات، وقد تُغلق بعض المناطق القريبة من المباني الحكومية." },
  },
  "tk-tvtower": {
    zh: { name: "塔什干电视塔", desc: "中亚最高的、设有公众观景台的建筑：这座375米高的塔从1978年开始建造，1985年1月15日开始播出。设计最初是为巴格达制作的，伊拉克政变后转给了塔什干。高速电梯带你到97米高的观景台，全城和远处的群山尽收眼底；再往上是一家旋转餐厅，饰有苏联太空主题的马赛克。入场需携带护照。" },
    ko: { name: "타슈켄트 TV 타워", desc: "일반인 전망대를 갖춘 중앙아시아에서 가장 높은 구조물입니다. 높이 375m의 탑은 1978년에 착공해 1985년 1월 15일 방송을 시작했습니다. 원래 바그다드를 위해 만든 설계였지만 이라크 쿠데타 이후 타슈켄트로 넘어왔습니다. 고속 엘리베이터로 97m 전망대에 오르면 도시 전체와 지평선의 산들이 보이고, 더 위에는 소련 우주 테마 모자이크로 꾸민 회전 레스토랑이 있습니다. 입장하려면 여권을 지참하세요." },
    de: { name: "Fernsehturm Taschkent", desc: "Das höchste Bauwerk Zentralasiens mit öffentlicher Aussichtsplattform: Der 375 Meter hohe Turm wurde ab 1978 gebaut und ging am 15. Januar 1985 auf Sendung. Der Entwurf war ursprünglich für Bagdad gedacht, ging aber nach dem Putsch im Irak an Taschkent. Ein schneller Aufzug bringt Sie auf die Plattform in 97 Metern Höhe mit Blick über die ganze Stadt und die Berge am Horizont; weiter oben liegt ein Drehrestaurant mit sowjetischen Raumfahrtmosaiken. Für den Eintritt den Reisepass mitbringen." },
    fr: { name: "Tour de télévision de Tachkent", desc: "La plus haute construction d'Asie centrale dotée d'un belvédère public : la tour de 375 mètres a été construite à partir de 1978 et a commencé à émettre le 15 janvier 1985. Le projet était d'abord destiné à Bagdad, mais après le coup d'État en Irak il revint à Tachkent. Un ascenseur rapide mène à la plateforme à 97 mètres, d'où l'on voit toute la ville et les montagnes à l'horizon ; plus haut se trouve un restaurant tournant orné de mosaïques soviétiques sur le thème de l'espace. Munissez-vous de votre passeport pour entrer." },
    ja: { name: "タシケント・テレビ塔", desc: "一般向け展望台をもつ中央アジアで最も高い建造物です。高さ375mの塔は1978年に着工し、1985年1月15日に放送を開始しました。設計はもともとバグダッド用でしたが、イラクのクーデター後にタシケントに回されました。高速エレベーターで地上97mの展望台へ上がると、町全体と地平線の山々が見渡せます。さらに上にはソ連の宇宙をテーマにしたモザイクのある回転レストランがあります。入場にはパスポートが必要です。" },
    tr: { name: "Taşkent Televizyon Kulesi", desc: "Orta Asya'nın halka açık seyir terası olan en yüksek yapısı: 375 metrelik kulenin inşaatı 1978'de başladı ve 15 Ocak 1985'te yayına geçti. Proje aslında Bağdat için hazırlanmıştı, ancak Irak'taki darbeden sonra Taşkent'e verildi. Hızlı bir asansör sizi 97 metredeki seyir terasına çıkarır; bütün şehir ve ufuktaki dağlar görünür. Daha yukarıda Sovyet uzay temalı mozaiklerle süslü dönen bir restoran vardır. Giriş için pasaportunuzu getirin." },
    ar: { name: "برج تلفزيون طشقند", desc: "أعلى منشأة في آسيا الوسطى ذات منصة مشاهدة عامة: بدأ بناء البرج البالغ ارتفاعه 375 مترًا عام 1978 وبدأ البث في 15 يناير 1985. وُضع التصميم أصلًا لبغداد، لكنه آل إلى طشقند بعد الانقلاب في العراق. ينقلك مصعد سريع إلى منصة المشاهدة على ارتفاع 97 مترًا، حيث تبدو المدينة كلها والجبال في الأفق، وفي الأعلى مطعم دوّار مزيّن بفسيفساء سوفيتية عن الفضاء. أحضر جواز سفرك للدخول." },
  },
  "tk-navoitheatre": {
    zh: { name: "阿利舍尔·纳沃伊歌剧芭蕾舞剧院", desc: "国家的主舞台，也是塔什干最美的建筑之一——纳沃伊大剧院，1947年按建筑师阿列克谢·舒舍夫的设计落成。日本战俘也参与了建设，外墙上的纪念牌记述了这一点。各个休息厅由来自不同地区的工匠装饰，每个大厅风格各异——布哈拉、希瓦、撒马尔罕、费尔干纳、塔什干和铁尔梅兹——有雕刻的石膏装饰和彩绘天花板。想看内部装饰，就买一张歌剧或芭蕾舞的票——价格不贵，非常值得。" },
    ko: { name: "알리셰르 나보이 오페라 발레 극장", desc: "나라의 대표 무대이자 타슈켄트에서 가장 아름다운 건물 중 하나인 나보이 대극장으로, 건축가 알렉세이 슈세프의 설계로 1947년에 문을 열었습니다. 건설에는 일본인 전쟁 포로들도 참여했으며 정면의 기념판이 이를 전합니다. 로비는 여러 지역의 장인들이 꾸며 홀마다 부하라, 히바, 사마르칸트, 페르가나, 타슈켄트, 테르메즈 양식의 간치 조각과 채색 천장을 갖추고 있습니다. 내부를 보려면 오페라나 발레 표를 사세요. 저렴하고 충분히 가치가 있습니다." },
    de: { name: "Alischer-Navoi-Oper und -Ballett", desc: "Die wichtigste Bühne des Landes und eines der schönsten Gebäude Taschkents – das Bolschoi-Theater Navoi, 1947 nach einem Entwurf des Architekten Alexei Schtschussew eröffnet. Am Bau arbeiteten auch japanische Kriegsgefangene, woran eine Tafel an der Fassade erinnert. Die Foyers schmückten Meister aus verschiedenen Regionen, jeder Saal in eigenem Stil – buchar, chiwesisch, samarkandisch, ferghanisch, taschkentisch und termesisch – mit geschnitztem Gantsch und bemalten Decken. Um die Innenräume zu sehen, kaufen Sie eine Karte für Oper oder Ballett – günstig und lohnend." },
    fr: { name: "Théâtre d'opéra et de ballet Alicher Navoï", desc: "La grande scène du pays et l'un des plus beaux bâtiments de Tachkent – le Bolchoï Navoï, inauguré en 1947 sur des plans de l'architecte Alexeï Chtchoussev. Des prisonniers de guerre japonais ont aussi participé à sa construction, comme le rappelle une plaque sur la façade. Les foyers ont été décorés par des maîtres de différentes régions, chaque salle dans son style – boukhariote, khivien, samarcandais, de Ferghana, de Tachkent et de Termez – avec ganch sculpté et plafonds peints. Pour voir les intérieurs, prenez un billet pour un opéra ou un ballet – bon marché et vraiment à voir." },
    ja: { name: "アリシェル・ナヴォイ記念オペラ・バレエ劇場", desc: "国の主要な舞台で、タシケントで最も美しい建物の一つであるナヴォイ・ボリショイ劇場。建築家アレクセイ・シチューセフの設計で1947年に開場しました。建設には日本人捕虜も携わり、正面の記念プレートがそれを伝えています。ロビーは各地の職人が装飾し、ホールごとにブハラ、ヒヴァ、サマルカンド、フェルガナ、タシケント、テルメズの様式でガンチ彫刻と彩色天井が施されています。内部を見るならオペラかバレエのチケットを。安くて十分に価値があります。" },
    tr: { name: "Alişer Nevai Opera ve Bale Tiyatrosu", desc: "Ülkenin ana sahnesi ve Taşkent'in en güzel binalarından biri – mimar Aleksey Şçusev'in tasarımıyla 1947'de açılan Nevai Bolşoy Tiyatrosu. İnşaatında Japon savaş esirleri de çalıştı; cephedeki bir levha bunu hatırlatır. Fuayeleri farklı bölgelerden ustalar süsledi, her salon kendi üslubunda – Buhara, Hive, Semerkant, Fergana, Taşkent ve Tirmiz – oymalı alçı ve boyalı tavanlarla. İç mekânları görmek için bir opera ya da bale bileti alın – ucuz ve kesinlikle değer." },
    ar: { name: "مسرح عليشير نوائي للأوبرا والباليه", desc: "المسرح الأول في البلاد ومن أجمل مباني طشقند – مسرح نوائي الكبير، افتُتح عام 1947 وفق تصميم المعماري أليكسي شتشوسيف. شارك في بنائه أسرى حرب يابانيون أيضًا، كما تذكّر لوحة على الواجهة. زيّن الردهاتِ حرفيون من مناطق مختلفة، فلكل قاعة طرازها – البخاري والخيوي والسمرقندي والفرغاني والطشقندي والترمذي – بالجص المنحوت والأسقف المرسومة. لرؤية الداخل اشترِ تذكرة لأوبرا أو باليه – رخيصة وتستحق العناء." },
  },
  "tk-chimes": {
    zh: { name: "塔什干钟楼", desc: "阿米尔·帖木儿广场旁的钟楼，1947年为纪念第二次世界大战的胜利而建，如今是城市的象征之一。钟的机芯由塔什干钟表匠伊萨克·艾森施泰因带来，取自东普鲁士阿伦施泰因的市政厅。钟楼采用民族风格装饰，后来旁边又建了一座对称的钟楼。钟声每小时敲响——是方便的会合地点和拍照点。" },
    ko: { name: "타슈켄트 시계탑", desc: "아미르 티무르 광장 옆에 있는 시계탑으로, 1947년 제2차 세계대전 승리를 기념해 세워졌으며 지금은 도시의 상징 중 하나입니다. 시계 장치는 타슈켄트의 시계공 이사크 아이젠슈타인이 동프로이센 알렌슈타인 시청에서 가져왔습니다. 탑은 민족 양식으로 꾸며졌고, 나중에 그 옆에 대칭을 이루는 두 번째 탑이 세워졌습니다. 매시 정각 종이 울리며, 약속 장소나 사진 명소로 좋습니다." },
    de: { name: "Taschkenter Glockenspiel", desc: "Ein Uhrturm am Amir-Temur-Platz, 1947 zum Sieg im Zweiten Weltkrieg errichtet und heute eines der Wahrzeichen der Stadt. Das Uhrwerk brachte der Taschkenter Uhrmacher Isaak Eisenstein mit, der es vom Rathaus in Allenstein in Ostpreußen geholt hatte. Der Turm ist im nationalen Stil verziert, später entstand daneben ein zweiter, symmetrischer Turm. Die Glocken schlagen jede Stunde – ein praktischer Treffpunkt und Fotospot." },
    fr: { name: "Carillon de Tachkent", desc: "Une tour d'horloge près de la place Amir Timour, construite en 1947 pour célébrer la victoire de la Seconde Guerre mondiale et devenue l'un des symboles de la ville. Le mécanisme fut apporté par l'horloger de Tachkent Isaac Aizenstein, qui l'avait récupéré à l'hôtel de ville d'Allenstein, en Prusse-Orientale. La tour est décorée dans le style national, et une seconde tour symétrique fut construite plus tard à côté. Le carillon sonne chaque heure – un point de rendez-vous et de photo pratique." },
    ja: { name: "タシケントの時計塔", desc: "アミール・ティムール広場のそばにある時計塔で、1947年に第二次世界大戦の勝利を記念して建てられ、今では町の象徴の一つです。時計の機械はタシケントの時計職人イサーク・アイゼンシュタインが東プロイセン・アレンシュタインの市庁舎から運んできたものです。塔は民族様式で装飾され、のちに隣に対称形の2本目の塔が建てられました。毎正時に鐘が鳴り、待ち合わせや写真撮影に便利な場所です。" },
    tr: { name: "Taşkent Saat Kulesi", desc: "Emir Timur Meydanı'nın yanında, 1947'de İkinci Dünya Savaşı zaferi anısına yapılan ve bugün şehrin simgelerinden biri olan saat kulesi. Saat mekanizmasını Taşkentli saatçi İsaak Ayzenştayn getirdi; mekanizma Doğu Prusya'daki Allenstein belediye binasından alınmıştı. Kule ulusal üslupta süslendi, sonradan yanına simetrik ikinci bir kule yapıldı. Saat her saat başı çalar – kullanışlı bir buluşma ve fotoğraf noktası." },
    ar: { name: "ساعة طشقند الدقّاقة", desc: "برج ساعة بجوار ساحة أمير تيمور، بُني عام 1947 احتفالًا بالنصر في الحرب العالمية الثانية، وصار اليوم أحد رموز المدينة. جلب آليةَ الساعة صانعُ الساعات الطشقندي إسحاق آيزنشتاين، وقد أخذها من دار بلدية ألنشتاين في بروسيا الشرقية. زُيّن البرج بالطراز الوطني، وبُني بجانبه لاحقًا برج ثانٍ متماثل. تدق الساعة كل ساعة – نقطة لقاء وتصوير مناسبة." },
  },
  "tk-forums": {
    zh: { name: "国际论坛宫", desc: "阿米尔·帖木儿广场上一座宏伟的白色建筑，带柱廊和蓝色穹顶，2009年为塔什干建城2200周年而建。这里举办国际峰会、音乐会和国家典礼，市中心许多地方都能望见它的穹顶。只有参加活动才能进入内部，但傍晚灯光亮起时外立面格外美丽。" },
    ko: { name: "국제포럼궁전", desc: "아미르 티무르 광장에 있는 열주와 파란 돔의 웅장한 흰색 건물로, 2009년 타슈켄트 2200주년을 맞아 지어졌습니다. 국제 정상회의, 콘서트, 국가 행사가 열리며, 시내 곳곳에서 돔이 보입니다. 내부는 행사 때만 들어갈 수 있지만, 조명이 켜지는 저녁의 정면은 특히 아름답습니다." },
    de: { name: "Palast der Internationalen Foren", desc: "Ein monumentales weißes Gebäude mit Kolonnade und blauer Kuppel am Amir-Temur-Platz, 2009 zum 2200-jährigen Jubiläum Taschkents erbaut. Hier finden internationale Gipfel, Konzerte und Staatszeremonien statt, und die Kuppel ist von vielen Punkten im Zentrum zu sehen. Hinein kommt man nur zu Veranstaltungen, doch die Fassade ist abends im Licht besonders schön." },
    fr: { name: "Palais des Forums internationaux", desc: "Un monumental édifice blanc à colonnade et coupole bleue sur la place Amir Timour, construit en 2009 pour le 2 200e anniversaire de Tachkent. Il accueille sommets internationaux, concerts et cérémonies officielles, et sa coupole se voit de nombreux points du centre. On n'y entre que lors d'événements, mais la façade est particulièrement belle le soir, illuminée." },
    ja: { name: "国際フォーラム宮殿", desc: "アミール・ティムール広場に建つ列柱と青いドームの壮大な白い建物で、2009年にタシケント建都2200年を記念して建てられました。国際サミットやコンサート、国家儀式が行われ、ドームは中心部の多くの場所から見えます。内部に入れるのは催しのときだけですが、ライトアップされた夕方のファサードは特に美しいです。" },
    tr: { name: "Uluslararası Forumlar Sarayı", desc: "Emir Timur Meydanı'nda, Taşkent'in 2200. kuruluş yıldönümü için 2009'da yapılan sütunlu ve mavi kubbeli anıtsal beyaz bina. Uluslararası zirvelere, konserlere ve devlet törenlerine ev sahipliği yapar; kubbesi merkezin birçok noktasından görünür. İçine yalnızca etkinliklerde girilebilir, ama cephesi akşam ışıklandırıldığında özellikle güzeldir." },
    ar: { name: "قصر المنتديات الدولية", desc: "مبنى أبيض ضخم ذو أعمدة وقبة زرقاء في ساحة أمير تيمور، بُني عام 2009 بمناسبة مرور 2200 عام على تأسيس طشقند. يستضيف القمم الدولية والحفلات والمراسم الرسمية، وتُرى قبته من نقاط كثيرة في المركز. لا يمكن الدخول إلا في المناسبات، لكن واجهته جميلة بشكل خاص مساءً حين تُضاء." },
  },
  "tk-courage": {
    zh: { name: "勇气纪念碑", desc: "1966年4月26日塔什干地震震中处的纪念碑，于1976年揭幕。一道裂开花岗岩的裂缝，将刻着停摆时钟的石块与护卫着自己抵御灾难的男人、女人和孩子的青铜像分开。四周的浮雕讲述了全国各地的人们如何前来重建这座城市。安霍尔运河从旁边流过。" },
    ko: { name: "용기 기념비", desc: "1966년 4월 26일 타슈켄트 지진의 진앙지에 1976년 세워진 기념비입니다. 화강암을 가르는 균열이 멈춘 시계가 새겨진 돌 큐브와, 재난으로부터 몸을 지키는 남자·여자·아이의 청동상을 갈라놓고 있습니다. 주변 부조는 전국에서 온 사람들이 도시를 다시 세운 이야기를 들려줍니다. 근처로 안호르 운하가 흐릅니다." },
    de: { name: "Denkmal des Mutes", desc: "Ein Mahnmal am Epizentrum des Taschkenter Erdbebens vom 26. April 1966, enthüllt 1976. Ein Riss im Granit trennt einen Steinwürfel mit einer stehengebliebenen Uhr von Bronzefiguren eines Mannes, einer Frau und eines Kindes, die sich gegen die Katastrophe stemmen. Reliefs ringsum erzählen, wie Menschen aus dem ganzen Land kamen, um die Stadt wiederaufzubauen. Nebenan fließt der Ankhor-Kanal." },
    fr: { name: "Monument du Courage", desc: "Un mémorial à l'épicentre du séisme de Tachkent du 26 avril 1966, inauguré en 1976. Une fissure fend le granit et sépare un cube de pierre portant une horloge arrêtée des figures de bronze d'un homme, d'une femme et d'un enfant qui font face au désastre. Des reliefs tout autour racontent comment des gens de tout le pays vinrent reconstruire la ville. Le canal Ankhor coule à côté." },
    ja: { name: "勇気の記念碑", desc: "1966年4月26日のタシケント地震の震源地に1976年に建てられた記念碑です。花崗岩を割る亀裂が、止まった時計を刻んだ石の立方体と、災害から身を守る男性・女性・子どものブロンズ像を隔てています。周囲のレリーフは、国中から人々が集まって町を再建した様子を物語ります。そばをアンホル運河が流れています。" },
    tr: { name: "Cesaret Anıtı", desc: "26 Nisan 1966 Taşkent depreminin merkez üssünde, 1976'da açılan anıt. Graniti yaran bir çatlak, durmuş bir saatin işlendiği taş küpü, felakete karşı korunan bir adam, bir kadın ve bir çocuğun bronz figürlerinden ayırır. Çevresindeki kabartmalar, ülkenin her yerinden insanların şehri yeniden inşa etmeye nasıl geldiğini anlatır. Yanından Ankhor kanalı akar." },
    ar: { name: "نصب الشجاعة", desc: "نصب تذكاري في بؤرة زلزال طشقند في 26 أبريل 1966، أُزيح عنه الستار عام 1976. يشق صدعٌ الغرانيتَ فيفصل مكعبًا حجريًا عليه ساعة متوقفة عن تماثيل برونزية لرجل وامرأة وطفل يتّقون الكارثة. وتروي النقوش البارزة حوله كيف جاء الناس من كل أنحاء البلاد لإعادة بناء المدينة. وتجري قناة أنخور بجانبه." },
  },
  "tk-japanesegarden": {
    zh: { name: "日本庭园", desc: "电视塔附近的一座日式庭园：有锦鲤池、拱桥、石灯笼、樱花树和修剪整齐的松树。春天樱花盛开、秋天枫叶变红时尤其美丽。这是城里最安静的角落之一，很受拍照者欢迎，也是躲开喧嚣的好去处。需要购票入园，开放时间随季节变化。" },
    ko: { name: "일본 정원", desc: "TV 타워 근처의 일본식 정원으로, 잉어가 사는 연못, 아치형 다리, 석등, 벚나무, 단정하게 다듬은 소나무가 있습니다. 벚꽃이 피는 봄과 단풍이 붉게 물드는 가을에 특히 아름답습니다. 도시에서 가장 조용한 곳 중 하나로, 사진 촬영 장소이자 소음에서 벗어나 쉬기 좋은 곳입니다. 입장료가 있으며 운영 시간은 계절에 따라 바뀝니다." },
    de: { name: "Japanischer Garten", desc: "Ein Garten im japanischen Stil nahe dem Fernsehturm: ein Teich mit Karpfen, Bogenbrücken, Steinlaternen, Kirschbäume und sorgfältig geschnittene Kiefern. Besonders schön im Frühling, wenn die Bäume blühen, und im Herbst, wenn sich der Ahorn rot färbt. Einer der ruhigsten Orte der Stadt, beliebt für Fotoshootings und eine Pause vom Lärm. Eintritt kostenpflichtig; die Öffnungszeiten wechseln mit der Saison." },
    fr: { name: "Jardin japonais", desc: "Un jardin de style japonais près de la tour de télévision : étang aux carpes, ponts en arc, lanternes de pierre, cerisiers et pins soigneusement taillés. Il est particulièrement beau au printemps, quand les arbres fleurissent, et à l'automne, quand les érables rougissent. L'un des coins les plus calmes de la ville, apprécié pour les séances photo et pour échapper au bruit. Entrée payante ; horaires variables selon la saison." },
    ja: { name: "日本庭園", desc: "テレビ塔の近くにある日本式の庭園で、鯉の泳ぐ池、太鼓橋、石灯籠、桜、きれいに刈り込まれた松があります。桜の咲く春と紅葉の秋は特に美しいです。町で最も静かな場所の一つで、写真撮影や喧騒からひと休みするのに人気です。入園は有料で、開園時間は季節によって変わります。" },
    tr: { name: "Japon Bahçesi", desc: "Televizyon kulesinin yakınında Japon tarzı bir bahçe: sazan balıklı bir gölet, kemerli köprüler, taş fenerler, kiraz ağaçları ve özenle budanmış çamlar. Ağaçların çiçek açtığı ilkbaharda ve akçaağaçların kızardığı sonbaharda özellikle güzeldir. Şehrin en sakin köşelerinden biri; fotoğraf çekimleri ve gürültüden kaçmak için popüler. Giriş ücretlidir; çalışma saatleri mevsime göre değişir." },
    ar: { name: "الحديقة اليابانية", desc: "حديقة على الطراز الياباني قرب برج التلفزيون: بركة فيها أسماك الشبوط، وجسور مقوّسة، وفوانيس حجرية، وأشجار كرز، وصنوبر مشذّب بعناية. تكون جميلة بشكل خاص في الربيع حين تزهر الأشجار وفي الخريف حين يحمرّ القيقب. من أهدأ أركان المدينة، ومقصد لجلسات التصوير والهروب من الضجيج. الدخول برسوم، ومواعيد الفتح تتغير بحسب الموسم." },
  },
  "tk-navoipark": {
    zh: { name: "阿利舍尔·纳沃伊国家公园", desc: "塔什干最大的公园之一，有池塘、喷泉和宽阔的林荫道。山丘上有一座圆亭，里面是15世纪伟大诗人阿利舍尔·纳沃伊的纪念碑；作家小道上汇集了乌兹别克和世界文学经典作家的雕像。附近有最高会议大楼、婚礼宫和“魔法城”娱乐综合体。傍晚散步的好去处；游乐设施和租赁另行收费。" },
    ko: { name: "알리셰르 나보이 국립공원", desc: "연못과 분수, 넓은 가로수길이 있는 타슈켄트에서 가장 큰 공원 중 하나입니다. 언덕 위 원형 정자에는 15세기 위대한 시인 알리셰르 나보이의 기념비가 있고, ‘작가의 길’에는 우즈베크 및 세계 문학 거장들의 동상이 모여 있습니다. 근처에 국회 건물, 결혼궁전, 매직 시티 엔터테인먼트 단지가 있습니다. 저녁 산책하기 좋으며, 놀이기구와 대여는 별도 요금입니다." },
    de: { name: "Alischer-Navoi-Nationalpark", desc: "Einer der größten Parks Taschkents mit Teich, Springbrunnen und breiten Alleen. Auf einem Hügel steht eine Rotunde mit einem Denkmal für Alischer Navoi, den großen Dichter des 15. Jahrhunderts, und in der Allee der Schriftsteller versammeln sich Statuen von Klassikern der usbekischen und der Weltliteratur. In der Nähe liegen das Gebäude des Oliy Majlis, der Hochzeitspalast und der Vergnügungskomplex Magic City. Ideal für einen Abendspaziergang; Fahrgeschäfte und Verleih kosten extra." },
    fr: { name: "Parc national Alicher Navoï", desc: "L'un des plus grands parcs de Tachkent, avec un étang, des fontaines et de larges allées. Sur une colline, une rotonde abrite le monument à Alicher Navoï, grand poète du XVe siècle, et l'allée des Écrivains réunit les statues de classiques de la littérature ouzbèke et mondiale. À proximité : le bâtiment de l'Oliy Majlis, le palais des Mariages et le complexe de loisirs Magic City. Idéal pour une promenade du soir ; manèges et locations payants." },
    ja: { name: "アリシェル・ナヴォイ国立公園", desc: "池や噴水、広い並木道のあるタシケント最大級の公園です。丘の上の円形の東屋には15世紀の大詩人アリシェル・ナヴォイの記念碑があり、「作家の小道」にはウズベク文学と世界文学の古典作家の像が並びます。近くには国会議事堂、結婚宮殿、娯楽施設マジック・シティがあります。夕方の散歩に最適で、乗り物やレンタルは別料金です。" },
    tr: { name: "Alişer Nevai Milli Parkı", desc: "Göleti, fıskiyeleri ve geniş yollarıyla Taşkent'in en büyük parklarından biri. Bir tepedeki rotondada 15. yüzyılın büyük şairi Alişer Nevai'nin anıtı bulunur; Yazarlar Yolu'nda Özbek ve dünya edebiyatı klasiklerinin heykelleri toplanmıştır. Yakınında Olii Meclis binası, Nikâh Sarayı ve Magic City eğlence kompleksi vardır. Akşam yürüyüşü için harika; oyuncaklar ve kiralamalar ayrıca ücretlidir." },
    ar: { name: "حديقة عليشير نوائي الوطنية", desc: "من أكبر حدائق طشقند، فيها بركة ونوافير وممرات واسعة. على تلّة تقوم قبة دائرية تضم نصبًا للشاعر الكبير عليشير نوائي من القرن الخامس عشر، ويجمع «ممر الكتّاب» تماثيل لأعلام الأدب الأوزبكي والعالمي. وبالقرب منها مبنى المجلس الأعلى وقصر الأعراس ومجمع «ماجيك سيتي» الترفيهي. مكان رائع للتنزه مساءً، والألعاب والتأجير برسوم منفصلة." },
  },
  "tk-newuzbekistan": {
    zh: { name: "新乌兹别克斯坦公园", desc: "全国最大的公园之一，占地100多公顷，于2021年8月31日独立30周年之际开放。中央耸立着高大的独立纪念碑，林荫道、喷泉和绿色草坪从这里向四周展开；园内种植了一万多棵树木和灌木。公园位于城市东部边缘，乘出租车前往最方便；傍晚灯火通明，游人众多。" },
    ko: { name: "새 우즈베키스탄 공원", desc: "100헥타르가 넘는 나라에서 가장 큰 공원 중 하나로, 독립 30주년을 맞아 2021년 8월 31일 문을 열었습니다. 중앙에 높은 독립 기념탑이 솟아 있고, 그 주위로 가로수길과 분수, 푸른 잔디밭이 펼쳐지며 나무와 관목이 만 그루 넘게 심어졌습니다. 도시 동쪽 끝에 있어 택시로 가는 것이 가장 편하며, 저녁에는 조명이 밝고 사람이 많습니다." },
    de: { name: "Park Neues Usbekistan", desc: "Einer der größten Parks des Landes, über 100 Hektar, eröffnet am 31. August 2021 zum 30. Jahrestag der Unabhängigkeit. In der Mitte ragt das hohe Unabhängigkeitsdenkmal empor, von dem Alleen, Springbrunnen und grüne Rasenflächen ausgehen; mehr als zehntausend Bäume und Sträucher wurden gepflanzt. Der Park liegt am östlichen Stadtrand, am einfachsten erreicht man ihn mit dem Taxi; abends ist er gut beleuchtet und belebt." },
    fr: { name: "Parc Nouvel Ouzbékistan", desc: "L'un des plus grands parcs du pays, plus de 100 hectares, ouvert le 31 août 2021 pour les 30 ans de l'indépendance. En son centre s'élève le haut monument de l'Indépendance, d'où partent allées, fontaines et pelouses ; plus de dix mille arbres et arbustes y ont été plantés. Le parc est à la lisière est de la ville, le taxi est donc le plus simple ; le soir, il est bien éclairé et animé." },
    ja: { name: "新ウズベキスタン公園", desc: "100ヘクタールを超える国内最大級の公園で、独立30周年の2021年8月31日に開園しました。中央に高い独立記念塔がそびえ、そこから並木道、噴水、緑の芝生が広がり、1万本以上の木や低木が植えられています。町の東端にあるのでタクシーで行くのが便利です。夜は明るくライトアップされ、にぎわいます。" },
    tr: { name: "Yeni Özbekistan Parkı", desc: "Ülkenin en büyük parklarından biri; 100 hektarı aşan park, bağımsızlığın 30. yıldönümü için 31 Ağustos 2021'de açıldı. Ortasında yüksek Bağımsızlık Anıtı yükselir; ondan yollar, fıskiyeler ve yeşil çimenler yayılır; on binden fazla ağaç ve çalı dikilmiştir. Park şehrin doğu ucundadır, en kolay taksiyle gidilir; akşamları iyi aydınlatılır ve kalabalıktır." },
    ar: { name: "حديقة أوزبكستان الجديدة", desc: "من أكبر حدائق البلاد، تتجاوز مساحتها 100 هكتار، افتُتحت في 31 أغسطس 2021 بمناسبة الذكرى الثلاثين للاستقلال. في وسطها يرتفع نصب الاستقلال الشاهق، وتنطلق منه الممرات والنوافير والمروج الخضراء، وقد زُرع فيها أكثر من عشرة آلاف شجرة وشجيرة. تقع الحديقة على الطرف الشرقي للمدينة، والوصول إليها أسهل بسيارة أجرة، وهي مضاءة جيدًا ومزدحمة مساءً." },
  },
  "tk-magiccity": {
    zh: { name: "魔法城", desc: "国家公园旁的一座主题公园式小城：童话城堡、欧式街道、商店、咖啡馆、电影院和带音乐喷泉的湖。最佳时间是傍晚，届时一切灯火通明，湖上还有喷泉表演。进入园区免费，里面的游乐设施、景点和表演另行收费；周末人很多。" },
    ko: { name: "매직 시티", desc: "국립공원 옆에 있는 테마파크형 거리로, 동화 같은 성, 유럽풍 거리, 상점, 카페, 영화관, 노래하는 분수가 있는 호수가 있습니다. 모든 것이 불을 밝히고 물 위에서 분수 쇼가 열리는 저녁이 가장 좋습니다. 입장은 무료이고 내부 놀이기구와 공연은 별도 요금이며, 주말에는 붐빕니다." },
    de: { name: "Magic City", desc: "Eine Themenpark-Stadt neben dem Nationalpark: ein Märchenschloss, Straßen im europäischen Stil, Geschäfte, Cafés, ein Kino und ein See mit singenden Fontänen. Am schönsten ist es abends, wenn alles beleuchtet ist und auf dem Wasser eine Fontänenshow läuft. Der Eintritt aufs Gelände ist frei; Fahrgeschäfte, Attraktionen und Shows kosten extra; am Wochenende ist es voll." },
    fr: { name: "Magic City", desc: "Une ville-parc à thème à côté du parc national : un château de conte de fées, des rues de style européen, des boutiques, des cafés, un cinéma et un lac aux fontaines chantantes. Le meilleur moment est le soir, quand tout s'illumine et qu'un spectacle de fontaines anime l'eau. L'entrée est gratuite ; manèges, attractions et spectacles sont payants ; foule le week-end." },
    ja: { name: "マジック・シティ", desc: "国立公園の隣にあるテーマパーク風の町で、おとぎ話の城、ヨーロッパ風の通り、店、カフェ、映画館、歌う噴水のある湖があります。いちばん良いのは夕方で、すべてがライトアップされ、水上で噴水ショーが行われます。敷地への入場は無料で、乗り物やアトラクション、ショーは別料金。週末は混雑します。" },
    tr: { name: "Magic City", desc: "Milli Park'ın yanında temalı bir park-kasaba: masal şatosu, Avrupa tarzı sokaklar, mağazalar, kafeler, bir sinema ve şarkı söyleyen fıskiyeli bir göl. En güzel zamanı her yerin ışıklandığı ve suda fıskiye gösterisinin yapıldığı akşamdır. Alana giriş ücretsizdir; oyuncaklar, eğlenceler ve gösteriler ayrıca ücretlidir; hafta sonları kalabalıktır." },
    ar: { name: "ماجيك سيتي", desc: "مدينة-حديقة ذات طابع خاص بجوار الحديقة الوطنية: قلعة خيالية، وشوارع على الطراز الأوروبي، ومتاجر، ومقاهٍ، وسينما، وبحيرة بنوافير راقصة. أفضل وقت هو المساء حين يُضاء كل شيء ويُقام عرض النوافير على الماء. الدخول إلى المكان مجاني، أما الألعاب والعروض في الداخل فبرسوم منفصلة، ويزدحم في عطلة نهاية الأسبوع." },
  },
  "tk-citypark": {
    zh: { name: "塔什干城市公园", desc: "乌兹别克斯坦最大的现代公园区，位于塔什干城商务区，2019年10月13日开放。这里有带喷泉的湖、自行车道、草坪、儿童游乐场、咖啡馆，还能看到首都新建的摩天大楼。傍晚有灯光和音乐，夏天是城里年轻人最喜欢的聚会地点。可以顺便沿安霍尔河散步并参观胡莫体育馆。" },
    ko: { name: "타슈켄트 시티 파크", desc: "타슈켄트 시티 비즈니스 지구에 있는 우즈베키스탄 최대의 현대식 공원으로, 2019년 10월 13일 문을 열었습니다. 분수가 있는 호수, 자전거 도로, 잔디밭, 놀이터, 카페가 있고 수도의 새 고층 빌딩들이 보입니다. 저녁에는 조명과 음악이 흐르고, 여름이면 도시 젊은이들이 가장 좋아하는 만남의 장소가 됩니다. 안호르 강변 산책이나 후모 아레나 방문과 함께하기 좋습니다." },
    de: { name: "Tashkent City Park", desc: "Usbekistans größte moderne Parkanlage im Geschäftsviertel Tashkent City, eröffnet am 13. Oktober 2019. Ein See mit Springbrunnen, Radwege, Rasenflächen, Spielplätze, Cafés und Blick auf die neuen Wolkenkratzer der Hauptstadt. Abends gibt es Licht und Musik, im Sommer ist er der beliebteste Treffpunkt der Jugend. Gut kombinierbar mit einem Spaziergang am Ankhor und der Humo Arena." },
    fr: { name: "Tashkent City Park", desc: "Le plus grand espace de parc moderne d'Ouzbékistan, dans le quartier d'affaires Tashkent City, ouvert le 13 octobre 2019. Un lac à fontaines, des pistes cyclables, des pelouses, des aires de jeux, des cafés et la vue sur les nouveaux gratte-ciel de la capitale. Le soir, lumières et musique ; l'été, c'est le lieu de rendez-vous préféré des jeunes. À combiner avec une balade le long de l'Ankhor et la Humo Arena." },
    ja: { name: "タシケント・シティ・パーク", desc: "ビジネス地区タシケント・シティにあるウズベキスタン最大の近代的な公園で、2019年10月13日に開園しました。噴水のある湖、自転車道、芝生、遊び場、カフェがあり、首都の新しい高層ビル群が見えます。夕方は照明と音楽、夏は若者たちのいちばん人気の待ち合わせ場所です。アンホル運河沿いの散歩やフモ・アリーナとあわせて訪れるのに便利です。" },
    tr: { name: "Tashkent City Park", desc: "Tashkent City iş bölgesinde, 13 Ekim 2019'da açılan Özbekistan'ın en büyük modern park alanı. Fıskiyeli bir göl, bisiklet yolları, çimenler, oyun alanları, kafeler ve başkentin yeni gökdelenlerinin manzarası. Akşamları ışıklar ve müzik vardır; yazın gençlerin en sevdiği buluşma yeridir. Ankhor boyunca bir yürüyüş ve Humo Arena ile birleştirmek kolaydır." },
    ar: { name: "حديقة طشقند سيتي", desc: "أكبر حديقة حديثة في أوزبكستان، في حي الأعمال «طشقند سيتي»، افتُتحت في 13 أكتوبر 2019. بحيرة بنوافير، ومسارات للدراجات، ومروج، وملاعب للأطفال، ومقاهٍ، وإطلالة على ناطحات السحاب الجديدة في العاصمة. في المساء أضواء وموسيقى، وفي الصيف هي ملتقى الشباب المفضل. يسهل الجمع بينها وبين نزهة على ضفاف أنخور وزيارة «هومو أرينا»." },
  },
  "tk-anhor": {
    zh: { name: "安霍尔火车头公园", desc: "安霍尔运河岸边的游乐园，安霍尔是塔什干最古老的水道，曾把老城和新城分开。这里有适合儿童和成人的游乐设施和摩天轮、咖啡馆以及水边的林荫小道。入园免费，游乐设施另行收费；夏日炎炎时，水边的傍晚是城里最凉爽的。" },
    ko: { name: "안호르 로코모티브 공원", desc: "한때 구시가지와 신시가지를 나누던 타슈켄트에서 가장 오래된 수로, 안호르 운하 강변의 놀이공원입니다. 어린이와 어른을 위한 놀이기구와 대관람차, 카페, 물가의 그늘진 산책로가 있습니다. 입장은 무료이고 놀이기구는 별도 요금이며, 한여름에는 물가의 저녁이 도시에서 가장 시원합니다." },
    de: { name: "Ankhor-Lokomotiv-Park", desc: "Ein Vergnügungspark am Ufer des Ankhor-Kanals, des ältesten Wasserlaufs Taschkents, der einst Alt- und Neustadt trennte. Fahrgeschäfte und ein Riesenrad für Kinder und Erwachsene, Cafés und schattige Wege am Wasser. Der Eintritt ist frei, die Fahrgeschäfte kosten extra; in der Sommerhitze sind die Abende am Wasser die kühlsten der Stadt." },
    fr: { name: "Parc Ankhor Lokomotiv", desc: "Un parc d'attractions au bord du canal Ankhor, la plus ancienne voie d'eau de Tachkent, qui séparait autrefois la vieille ville et la ville nouvelle. Manèges et grande roue pour enfants et adultes, cafés et allées ombragées au bord de l'eau. Entrée libre, manèges payants ; par la chaleur estivale, les soirées au bord de l'eau sont les plus fraîches de la ville." },
    ja: { name: "アンホル・ロコモティフ公園", desc: "かつて旧市街と新市街を隔てたタシケント最古の水路、アンホル運河のほとりにある遊園地です。子どもも大人も楽しめる乗り物や観覧車、カフェ、水辺の木陰の小道があります。入場は無料で乗り物は別料金。夏の暑さの中では、水辺の夕方が町でいちばん涼しく過ごせます。" },
    tr: { name: "Ankhor Lokomotiv Parkı", desc: "Bir zamanlar eski ve yeni şehri ayıran, Taşkent'in en eski su yolu Ankhor kanalının kıyısında bir eğlence parkı. Çocuklar ve yetişkinler için oyuncaklar ve dönme dolap, kafeler ve su kenarında gölgeli yollar. Giriş ücretsiz, oyuncaklar ayrıca ücretlidir; yaz sıcağında su kenarındaki akşamlar şehrin en serin vakitleridir." },
    ar: { name: "حديقة أنخور لوكوموتيف", desc: "مدينة ملاهٍ على ضفة قناة أنخور، أقدم مجرى مائي في طشقند، الذي كان يفصل يومًا بين المدينة القديمة والجديدة. ألعاب ودولاب هوائي للأطفال والكبار، ومقاهٍ، وممرات ظليلة على الماء. الدخول مجاني والألعاب برسوم منفصلة، وفي حر الصيف تكون الأمسيات على الماء الأبرد في المدينة." },
  },
  "tk-zoo": {
    zh: { name: "塔什干动物园", desc: "动物园的历史可追溯到1924年；如今这座占地22公顷、按自然景观布置的动物园于1997年在植物园部分土地上开放。园内有约600种、三千多只动物和鸟类——从老虎、北极熊到稀有的中亚野生动物。园内有小火车环游，还有爬行动物馆和水族馆。留出几个小时，最好上午来，那时动物比较活跃。" },
    ko: { name: "타슈켄트 동물원", desc: "동물원의 역사는 1924년으로 거슬러 올라가며, 22헥타르에 자연 경관 우리를 갖춘 지금의 동물원은 1997년 식물원 부지 일부에 문을 열었습니다. 호랑이와 북극곰부터 희귀한 중앙아시아 야생동물까지 약 600종, 3천 마리가 넘는 동물과 새가 있습니다. 작은 관람 열차가 다니며 파충류관과 수족관도 있습니다. 두어 시간을 잡고, 동물들이 활발한 오전에 오세요." },
    de: { name: "Zoo Taschkent", desc: "Der Zoo geht auf das Jahr 1924 zurück; der heutige Zoo mit naturnahen Gehegen auf 22 Hektar wurde 1997 auf einem Teil des Botanischen Gartens eröffnet. Er beherbergt über dreitausend Tiere und Vögel aus rund 600 Arten – von Tigern und Eisbären bis zu seltenen Tieren Zentralasiens. Ein kleiner Bummelzug fährt über das Gelände, es gibt ein Terrarium und ein Aquarium. Planen Sie ein paar Stunden ein und kommen Sie morgens, wenn die Tiere aktiv sind." },
    fr: { name: "Zoo de Tachkent", desc: "Le zoo remonte à 1924 ; le zoo actuel, aux enclos paysagers sur 22 hectares, a ouvert en 1997 sur une partie du Jardin botanique. Il abrite plus de trois mille animaux et oiseaux d'environ 600 espèces – des tigres et ours polaires aux animaux rares d'Asie centrale. Un petit train fait le tour du site, et il y a un vivarium et un aquarium. Prévoyez quelques heures et venez le matin, quand les animaux sont actifs." },
    ja: { name: "タシケント動物園", desc: "動物園の歴史は1924年にさかのぼり、22ヘクタールに自然に近い展示場をもつ現在の動物園は1997年に植物園の敷地の一部に開園しました。トラやホッキョクグマから中央アジアの希少な動物まで、約600種・3000頭羽以上の動物と鳥がいます。園内には小さな列車が走り、爬虫類館や水族館もあります。数時間をみて、動物が活発な午前中に訪れましょう。" },
    tr: { name: "Taşkent Hayvanat Bahçesi", desc: "Hayvanat bahçesinin geçmişi 1924'e uzanır; 22 hektarlık doğal düzenlenmiş alanlarıyla bugünkü bahçe, 1997'de Botanik Bahçesi arazisinin bir bölümünde açıldı. Kaplanlardan kutup ayılarına, nadir Orta Asya hayvanlarına kadar yaklaşık 600 türden üç binden fazla hayvan ve kuş barındırır. Alanda küçük bir tren dolaşır; teraryum ve akvaryum da vardır. Birkaç saat ayırın ve hayvanların aktif olduğu sabah saatlerinde gelin." },
    ar: { name: "حديقة حيوان طشقند", desc: "يعود تاريخ حديقة الحيوان إلى عام 1924، أما الحديقة الحالية بحظائرها المنسّقة على مساحة 22 هكتارًا فافتُتحت عام 1997 على جزء من أرض الحديقة النباتية. تضم أكثر من ثلاثة آلاف حيوان وطائر من نحو 600 نوع – من النمور والدببة القطبية إلى الحيوانات النادرة في آسيا الوسطى. يجول قطار صغير في أرجائها، وفيها بيت للزواحف وحوض أسماك. خصّص بضع ساعات وتعال صباحًا حين تكون الحيوانات نشطة." },
  },
  "tk-botanical": {
    zh: { name: "塔什干植物园", desc: "中亚最大的植物园之一，建于20世纪中叶，以植物学家费奥多尔·鲁萨诺夫命名。来自不同大洲——东亚、北美、中亚——的植物收藏被布置成带溪流、池塘和林荫树丛的自然景观。春天木兰和丁香盛开，夏天这里是城里最凉爽的地方之一。它紧挨着动物园，一天之内两处都很容易游览。" },
    ko: { name: "타슈켄트 식물원", desc: "20세기 중반에 설립되어 식물학자 표도르 루사노프의 이름을 딴, 중앙아시아에서 가장 큰 식물원 중 하나입니다. 동아시아, 북아메리카, 중앙아시아 등 여러 대륙의 식물 컬렉션이 시냇물과 연못, 그늘진 숲이 있는 자연 경관으로 꾸며져 있습니다. 봄에는 목련과 라일락이 피고, 여름에는 도시에서 가장 시원한 곳 중 하나입니다. 동물원 바로 옆이라 하루에 두 곳을 함께 둘러보기 쉽습니다." },
    de: { name: "Botanischer Garten Taschkent", desc: "Einer der größten botanischen Gärten Zentralasiens, gegründet Mitte des 20. Jahrhunderts und nach dem Botaniker Fjodor Rusanow benannt. Pflanzensammlungen verschiedener Kontinente – Ostasien, Nordamerika, Zentralasien – sind als natürliche Landschaften mit Bächen, Teichen und schattigen Hainen angelegt. Im Frühling blühen Magnolien und Flieder, im Sommer ist der Garten einer der kühlsten Orte der Stadt. Er liegt neben dem Zoo, beides lässt sich gut an einem Tag besuchen." },
    fr: { name: "Jardin botanique de Tachkent", desc: "L'un des plus grands jardins botaniques d'Asie centrale, fondé au milieu du XXe siècle et nommé d'après le botaniste Fiodor Roussanov. Les collections de plantes de différents continents – Asie de l'Est, Amérique du Nord, Asie centrale – sont présentées en paysages naturels avec ruisseaux, étangs et bosquets ombragés. Au printemps fleurissent magnolias et lilas ; l'été, c'est l'un des endroits les plus frais de la ville. Il jouxte le zoo, on visite facilement les deux dans la journée." },
    ja: { name: "タシケント植物園", desc: "20世紀半ばに創設され、植物学者フョードル・ルサノフの名を冠した中央アジア最大級の植物園です。東アジア、北米、中央アジアなど各大陸の植物コレクションが、小川や池、木陰の林のある自然の景観として配置されています。春はモクレンやライラックが咲き、夏は町で最も涼しい場所の一つです。動物園の隣なので、1日で両方を回りやすいです。" },
    tr: { name: "Taşkent Botanik Bahçesi", desc: "20. yüzyılın ortasında kurulan ve botanikçi Fyodor Rusanov'un adını taşıyan Orta Asya'nın en büyük botanik bahçelerinden biri. Doğu Asya, Kuzey Amerika ve Orta Asya gibi farklı kıtaların bitki koleksiyonları dereler, göletler ve gölgeli korularla doğal manzaralar olarak düzenlenmiştir. İlkbaharda manolyalar ve leylaklar açar, yazın şehrin en serin yerlerinden biridir. Hayvanat bahçesinin yanındadır; ikisini bir günde gezmek kolaydır." },
    ar: { name: "حديقة طشقند النباتية", desc: "من أكبر الحدائق النباتية في آسيا الوسطى، أُسست في منتصف القرن العشرين وسُميت باسم عالم النبات فيودور روسانوف. تُعرض مجموعات النباتات من قارات مختلفة – شرق آسيا وأمريكا الشمالية وآسيا الوسطى – في مناظر طبيعية بجداول وبرك وبساتين ظليلة. في الربيع تزهر الماغنوليا والليلك، وفي الصيف هي من أبرد أماكن المدينة. تقع بجوار حديقة الحيوان، فيسهل زيارة الاثنتين في يوم واحد." },
  },
  "tk-ashgabatpark": {
    zh: { name: "阿什哈巴德公园", desc: "亚什诺博德区的一座城市公园，以土库曼斯坦首都命名，象征两国人民的友谊。散步道、喷泉、儿童游乐设施和咖啡馆，使它成为塔什干东部居民喜爱的休闲场所。入园免费，娱乐项目另行收费。" },
    ko: { name: "아시가바트 공원", desc: "야시노보드 지구의 시립 공원으로, 두 민족의 우정을 상징해 투르크메니스탄의 수도 이름을 땄습니다. 산책로, 분수, 어린이 놀이기구, 카페가 있어 타슈켄트 동부 주민들이 즐겨 찾는 휴식 장소입니다. 입장은 무료이고 놀이 시설은 별도 요금입니다." },
    de: { name: "Aschgabat-Park", desc: "Ein Stadtpark im Bezirk Yashnobod, benannt nach der Hauptstadt Turkmenistans als Symbol der Freundschaft beider Völker. Spazierwege, Springbrunnen, Kinderkarussells und Cafés machen ihn zu einem beliebten Erholungsort der Bewohner im Osten Taschkents. Eintritt frei; Vergnügungen kosten extra." },
    fr: { name: "Parc d'Achgabat", desc: "Un parc urbain du district de Iachnobod, nommé d'après la capitale du Turkménistan en symbole d'amitié entre les deux peuples. Allées de promenade, fontaines, manèges pour enfants et cafés en font un lieu de détente apprécié des habitants de l'est de Tachkent. Entrée libre ; loisirs payants." },
    ja: { name: "アシガバート公園", desc: "ヤシノボド地区にある市民公園で、両国民の友好の象徴としてトルクメニスタンの首都の名が付けられています。散歩道、噴水、子ども向けの乗り物、カフェがあり、タシケント東部の住民に人気の憩いの場です。入場無料、遊具は別料金です。" },
    tr: { name: "Aşkabat Parkı", desc: "Yaşnobod ilçesinde, iki halkın dostluğunun simgesi olarak Türkmenistan'ın başkentinin adını taşıyan bir şehir parkı. Yürüyüş yolları, fıskiyeler, çocuk oyuncakları ve kafeler, onu doğu Taşkent sakinlerinin sevdiği bir dinlenme yeri yapar. Giriş ücretsiz, eğlenceler ayrıca ücretlidir." },
    ar: { name: "حديقة عشق آباد", desc: "حديقة عامة في حي ياشنوبود، سُميت باسم عاصمة تركمانستان رمزًا للصداقة بين الشعبين. ممرات للمشي ونوافير وألعاب للأطفال ومقاهٍ تجعلها مكان استجمام مفضلًا لسكان شرق طشقند. الدخول مجاني والترفيه برسوم منفصلة." },
  },
  "tk-humo": {
    zh: { name: "胡莫体育馆", desc: "中亚最大的冰上运动场馆，可容纳12500人，于2019年启用；其轮廓形似象征幸福的神鸟胡莫的翅膀。首都的冰球俱乐部在此比赛，这里还举办拳击、武术、花样滑冰比赛和大型音乐会。只能凭活动门票入场——请提前查看日程。" },
    ko: { name: "후모 아레나", desc: "1만 2,500석을 갖춘 중앙아시아 최대의 아이스 아레나로 2019년 문을 열었으며, 실루엣은 행복의 상징인 전설의 새 후모의 날개를 닮았습니다. 수도의 하키 클럽이 경기를 치르고, 복싱·무술·피겨스케이팅 대회와 대형 콘서트도 열립니다. 행사 티켓으로만 입장할 수 있으니 일정을 미리 확인하세요." },
    de: { name: "Humo Arena", desc: "Die größte Eisarena Zentralasiens mit 12.500 Plätzen, eröffnet 2019; ihre Silhouette erinnert an die Flügel des mythischen Vogels Humo, eines Glückssymbols. Hier spielen die Eishockeyklubs der Hauptstadt, und es finden Box-, Kampfsport- und Eiskunstlaufveranstaltungen sowie große Konzerte statt. Eintritt nur mit Veranstaltungsticket – Programm vorher prüfen." },
    fr: { name: "Humo Arena", desc: "La plus grande patinoire couverte d'Asie centrale, 12 500 places, inaugurée en 2019 ; sa silhouette évoque les ailes de l'oiseau mythique Humo, symbole du bonheur. Les clubs de hockey de la capitale y jouent, et elle accueille boxe, arts martiaux, patinage artistique et grands concerts. Accès uniquement avec un billet d'événement – consultez le programme à l'avance." },
    ja: { name: "フモ・アリーナ", desc: "1万2500席を備えた中央アジア最大のアイスアリーナで、2019年に開業しました。その姿は幸福の象徴である伝説の鳥フモの翼を思わせます。首都のホッケークラブの本拠地で、ボクシング、格闘技、フィギュアスケートの大会や大型コンサートも開かれます。入場はイベントのチケットのみなので、日程を事前に確認してください。" },
    tr: { name: "Humo Arena", desc: "12.500 kişilik, 2019'da açılan Orta Asya'nın en büyük buz arenası; silueti mutluluk simgesi efsanevi Hüma kuşunun kanatlarına benzer. Başkentin hokey kulüpleri burada oynar; boks, dövüş sanatları, artistik patinaj etkinlikleri ve büyük konserler düzenlenir. Giriş yalnızca etkinlik biletiyle – programı önceden kontrol edin." },
    ar: { name: "هومو أرينا", desc: "أكبر صالة جليد في آسيا الوسطى، تتسع لـ12,500 متفرج، افتُتحت عام 2019، ويشبه شكلها جناحي طائر «هُما» الأسطوري رمز السعادة. تلعب فيها أندية الهوكي في العاصمة، وتستضيف الملاكمة والفنون القتالية والتزلج الفني والحفلات الكبرى. الدخول بتذكرة الفعالية فقط – تحقّق من البرنامج مسبقًا." },
  },
  "tk-circus": {
    zh: { name: "塔什干国家马戏团", desc: "一座位于20世纪70年代建筑中的马戏团，拥有巨大的穹顶，是乔尔苏附近塔什干现代主义的标志性地标之一。乌兹别克走钢丝艺人“多尔沃兹”、马术演员、驯兽师和巡演剧团在此演出。入口前是一个有喷泉的广场。票在售票处和网上出售；演出多在周末。" },
    ko: { name: "타슈켄트 국립 서커스", desc: "초르수 근처에 있는 거대한 돔의 1970년대 건물로, 타슈켄트 모더니즘을 대표하는 명소 중 하나입니다. 우즈베크 줄타기 곡예사 ‘도르보즈’, 기마 곡예사, 조련사, 순회 공연단이 무대에 섭니다. 입구 앞에는 분수가 있는 광장이 있습니다. 표는 매표소와 온라인에서 팔며, 공연은 주로 주말에 열립니다." },
    de: { name: "Staatszirkus Taschkent", desc: "Ein Zirkus in einem Bau der 1970er-Jahre mit riesiger Kuppel – eines der markanten Wahrzeichen der Taschkenter Moderne nahe Chorsu. Hier treten usbekische Dorwos-Seiltänzer, Reiter, Dompteure und Gastensembles auf. Vor dem Eingang liegt ein Platz mit Springbrunnen. Karten gibt es an der Kasse und online; Vorstellungen meist am Wochenende." },
    fr: { name: "Cirque d'État de Tachkent", desc: "Un cirque dans un bâtiment des années 1970 à l'immense coupole – l'un des repères du modernisme de Tachkent près de Tchorsou. Funambules ouzbeks dorvoz, écuyers, dresseurs et troupes en tournée s'y produisent. Devant l'entrée, une place avec des fontaines. Billets en caisse et en ligne ; spectacles surtout le week-end." },
    ja: { name: "タシケント国立サーカス", desc: "巨大なドームをもつ1970年代の建物に入るサーカスで、チョルスー近くにあるタシケント・モダニズムの象徴的な建物の一つです。ウズベクの綱渡り芸人「ドルヴォズ」、曲馬師、猛獣使い、巡業団が出演します。入口の前には噴水のある広場があります。チケットは窓口とオンラインで販売、公演は主に週末です。" },
    tr: { name: "Taşkent Devlet Sirki", desc: "Dev kubbeli 1970'ler yapısında bir sirk – Çorsu yakınında Taşkent modernizminin tanınan simgelerinden biri. Burada Özbek dorvoz ip cambazları, atlı akrobatlar, hayvan terbiyecileri ve turne toplulukları sahne alır. Girişin önünde fıskiyeli bir meydan vardır. Biletler gişede ve internetten satılır; gösteriler çoğunlukla hafta sonlarıdır." },
    ar: { name: "سيرك طشقند الحكومي", desc: "سيرك في مبنى من سبعينيات القرن الماضي بقبة ضخمة – أحد المعالم المميزة لحداثة طشقند المعمارية قرب تشورسو. يقدّم فيه عروضَهم لاعبو الحبال الأوزبك «دورفوز» والفرسان ومدربو الحيوانات والفرق الزائرة. وأمام المدخل ساحة بنوافير. تُباع التذاكر في الشباك وعبر الإنترنت، والعروض غالبًا في عطلة نهاية الأسبوع." },
  },
  "tk-metro": {
    zh: { name: "塔什干地铁", desc: "中亚第一条地铁，于1977年11月6日开通——一座真正的地下博物馆。每座车站都有自己的主题：“宇航员站”有纪念宇航员的圆形浮雕，“阿利舍尔·纳沃伊站”的穹顶和陶瓷装饰取材于他的诗歌，“独立广场站”挂着水晶吊灯。如今共有四条线路、50座车站，允许拍照。可用银行卡或二维码付费；买一张日票最方便参观多个车站。" },
    ko: { name: "타슈켄트 지하철", desc: "1977년 11월 6일 개통한 중앙아시아 최초의 지하철로, 그야말로 지하 박물관입니다. 역마다 주제가 있어, 코스모나브틀라르역에는 우주비행사를 기리는 메달리온이, 알리셰르 나보이역에는 그의 시에서 영감을 받은 돔과 도자기 장식이, 무스타킬리크 마이도니역에는 크리스털 샹들리에가 있습니다. 현재 4개 노선 50개 역이 있고 사진 촬영이 가능합니다. 카드나 QR 코드로 결제하며, 여러 역을 보려면 1일권이 편리합니다." },
    de: { name: "Metro Taschkent", desc: "Die erste Metro Zentralasiens, eröffnet am 6. November 1977 – ein echtes unterirdisches Museum. Jede Station hat ihr Thema: Kosmonavtlar mit Medaillons zu Ehren der Kosmonauten, Alisher Navoi mit Kuppeln und Keramik nach seinen Gedichten, Mustaqillik Maydoni mit Kristalllüstern. Heute gibt es vier Linien und 50 Stationen, Fotografieren ist erlaubt. Bezahlt wird per Karte oder QR-Code; ein Tagesticket ist der einfachste Weg, mehrere Stationen zu sehen." },
    fr: { name: "Métro de Tachkent", desc: "Le premier métro d'Asie centrale, inauguré le 6 novembre 1977 – un véritable musée souterrain. Chaque station a son thème : Kosmonavtlar avec des médaillons en l'honneur des cosmonautes, Alicher Navoï avec coupoles et céramiques inspirées de ses poèmes, Moustaqillik Maïdoni avec ses lustres de cristal. Il compte aujourd'hui quatre lignes et 50 stations, et la photo est autorisée. Paiement par carte ou QR code ; un pass journée est le plus simple pour voir plusieurs stations." },
    ja: { name: "タシケント地下鉄", desc: "1977年11月6日に開業した中央アジア初の地下鉄で、まさに地下の博物館です。駅ごとにテーマがあり、コスモナフトラル駅には宇宙飛行士をたたえるメダリオン、アリシェル・ナヴォイ駅には彼の詩に着想を得たドームと陶器の装飾、ムスタキリク広場駅にはクリスタルのシャンデリアがあります。現在は4路線・50駅で、写真撮影も可能です。支払いはカードかQRコードで、いくつもの駅を見るなら1日券が便利です。" },
    tr: { name: "Taşkent Metrosu", desc: "6 Kasım 1977'de açılan Orta Asya'nın ilk metrosu – gerçek bir yeraltı müzesi. Her istasyonun kendi teması vardır: Kosmonavtlar'da kozmonotlar onuruna madalyonlar, Alişer Nevai'de onun şiirlerinden esinlenen kubbeler ve seramikler, Mustakillik Meydanı'nda kristal avizeler. Bugün dört hat ve 50 istasyon vardır; fotoğraf çekmek serbesttir. Ödeme kart veya QR kodla yapılır; birkaç istasyonu görmek için günlük bilet en kolayıdır." },
    ar: { name: "مترو طشقند", desc: "أول مترو في آسيا الوسطى، افتُتح في 6 نوفمبر 1977 – متحف حقيقي تحت الأرض. لكل محطة موضوعها: «كوسموناوتلار» بميداليات تكريمًا لرواد الفضاء، و«عليشير نوائي» بقباب وخزف مستوحى من أشعاره، و«ميدان الاستقلال» بثريات الكريستال. يضم اليوم أربعة خطوط و50 محطة، والتصوير مسموح. الدفع بالبطاقة أو رمز QR، والتذكرة اليومية أسهل طريقة لرؤية عدة محطات." },
  },
  "tk-alay": {
    zh: { name: "阿莱巴扎", desc: "塔什干“新”城即欧式城区中最古老的巴扎，离市中心步行不远。水果、甜瓜、干果、坚果、香料和甜食总是摆放得非常漂亮，花卉区也是城里最好的之一。价格比乔尔苏略高，但离地铁和酒店都很近。买之前先尝，再讲讲价——这是这里的习惯。" },
    ko: { name: "알라이 바자르", desc: "타슈켄트 ‘신시가지’, 즉 유럽식 구역에서 가장 오래된 시장으로 시내 중심에서 걸어갈 만한 거리에 있습니다. 과일, 멜론, 말린 과일, 견과류, 향신료, 과자가 늘 보기 좋게 진열되어 있고, 꽃 시장은 도시에서 손꼽힙니다. 초르수보다 조금 비싸지만 지하철역과 호텔이 가깝습니다. 맛보고 사고, 흥정하세요. 그것이 이곳의 관습입니다." },
    de: { name: "Alay-Basar", desc: "Der älteste Basar des „neuen“, europäischen Teils Taschkents, nur wenige Gehminuten vom Zentrum. Obst, Melonen, Trockenfrüchte, Nüsse, Gewürze und Süßigkeiten sind stets schön aufgebaut, und die Blumenreihen gehören zu den besten der Stadt. Die Preise sind etwas höher als auf dem Chorsu, dafür liegt alles nah an Metro und Hotels. Vor dem Kauf probieren und handeln – das ist hier üblich." },
    fr: { name: "Bazar Alaï", desc: "Le plus ancien bazar de la partie « nouvelle », européenne de Tachkent, à quelques pas du centre. Fruits, melons, fruits secs, noix, épices et confiseries sont toujours joliment présentés, et les allées de fleurs comptent parmi les plus belles de la ville. Les prix sont un peu plus élevés qu'à Tchorsou, mais tout est près du métro et des hôtels. Goûtez avant d'acheter et marchandez – c'est l'usage." },
    ja: { name: "アライ・バザール", desc: "タシケントの「新市街」、つまりヨーロッパ風地区で最も古いバザールで、中心部から歩いてすぐです。果物、メロン、ドライフルーツ、ナッツ、香辛料、お菓子がいつも美しく並べられ、花の売り場は町でも指折りです。値段はチョルスーより少し高めですが、地下鉄やホテルに近いのが便利。買う前に味見し、値段交渉を。それがここの習わしです。" },
    tr: { name: "Alay Pazarı", desc: "Taşkent'in “yeni”, Avrupai kesiminin en eski pazarı; merkezden kısa bir yürüyüş mesafesinde. Meyveler, kavunlar, kuru meyve, kuruyemiş, baharat ve tatlılar her zaman güzelce dizilir; çiçek tezgâhları şehrin en iyilerindendir. Fiyatlar Çorsu'dan biraz yüksektir ama her şey metroya ve otellere yakındır. Almadan önce tadın ve pazarlık edin – burada âdet budur." },
    ar: { name: "بازار آلاي", desc: "أقدم بازار في الجزء «الجديد» الأوروبي من طشقند، على مسافة قصيرة سيرًا من المركز. الفواكه والبطيخ والفواكه المجففة والمكسرات والتوابل والحلويات معروضة دائمًا بجمال، وصفوف الزهور من الأفضل في المدينة. الأسعار أعلى قليلًا من تشورسو، لكن كل شيء قريب من المترو والفنادق. تذوّق قبل الشراء وساوِم – هكذا جرت العادة." },
  },
  "tk-mirobod": {
    zh: { name: "米罗博德巴扎", desc: "塔什干市中心火车站附近的一个街区巴扎，当地人至今仍称它为“医院”巴扎。人们来这里买新鲜蔬菜、肉类、奶制品和热馕——游客比乔尔苏少，充满真实的日常气息。是尝萨姆萨、为路上囤些水果的好地方。" },
    ko: { name: "미로보드 바자르", desc: "타슈켄트 중심부 기차역 근처의 동네 시장으로, 현지인들은 지금도 ‘병원’ 바자르라고 부릅니다. 신선한 채소, 고기, 유제품, 갓 구운 빵을 사러 오는 곳으로, 초르수보다 관광객이 적고 진짜 일상의 분위기가 있습니다. 삼사를 맛보고 여행길 과일을 사 두기 좋습니다." },
    de: { name: "Mirobod-Basar", desc: "Ein Viertelsbasar im Zentrum Taschkents nahe dem Bahnhof, den die Einheimischen noch immer „Krankenhaus-Basar“ nennen. Man kommt für frisches Gemüse, Fleisch, Milchprodukte und warmes Fladenbrot – weniger Touristen als auf dem Chorsu und eine echte Alltagsatmosphäre. Ein guter Ort, um Samsa zu probieren und Obst für die Reise zu kaufen." },
    fr: { name: "Bazar Mirobod", desc: "Un bazar de quartier du centre de Tachkent, près de la gare, que les habitants appellent encore le bazar de « l'Hôpital ». On y vient pour les légumes frais, la viande, les produits laitiers et le pain chaud – moins de touristes qu'à Tchorsou et une vraie ambiance du quotidien. Un bon endroit pour goûter une samsa et faire le plein de fruits pour la route." },
    ja: { name: "ミロボド・バザール", desc: "タシケント中心部の駅近くにある地域のバザールで、地元の人々は今でも「病院」バザールと呼びます。新鮮な野菜、肉、乳製品、焼きたてのナンを買いに来る場所で、チョルスーより観光客が少なく、本物の日常の雰囲気があります。サムサを味わい、道中用の果物を買い込むのにぴったりです。" },
    tr: { name: "Mirobod Pazarı", desc: "Taşkent merkezinde, tren garı yakınında, yerlilerin hâlâ “Hastane” pazarı dediği bir mahalle pazarı. Taze sebze, et, süt ürünleri ve sıcak ekmek için gelinir – Çorsu'dan daha az turist ve gerçek bir gündelik hayat havası. Samsa tatmak ve yol için meyve almak için iyi bir yer." },
    ar: { name: "بازار ميروبود", desc: "بازار حيّ في وسط طشقند قرب محطة القطار، لا يزال السكان يسمونه بازار «المستشفى». يأتيه الناس لشراء الخضار الطازجة واللحوم والألبان والخبز الساخن – سياح أقل من تشورسو وأجواء يومية حقيقية. مكان جيد لتذوق السمبوسة والتزود بالفاكهة للطريق." },
  },
  "tk-islamciv": {
    zh: { name: "伊斯兰文明中心", desc: "全国最大的新建文化科研综合体，位于哈兹拉提·伊玛目建筑群对面：一座带穹顶和门楼的宏大建筑，内有博物馆、研究院、图书馆和手工作坊。展览讲述乌兹别克斯坦这片土地从古代到今天的历史，以及花剌子密、比鲁尼、伊本·西那、兀鲁伯等本地学者对世界科学的贡献。最珍贵的藏品是被称为奥斯曼《古兰经》的古老库法体《古兰经》。请提前确认开放时间和门票。" },
    ko: { name: "이슬람 문명 센터", desc: "하즈라티 이맘 단지 맞은편에 있는 나라 최대의 새 문화·연구 단지로, 돔과 정문을 갖춘 거대한 건물에 박물관, 연구소, 도서관, 공방이 들어서 있습니다. 전시는 고대부터 오늘날까지 우즈베키스탄 땅의 역사와 알콰리즈미, 비루니, 이븐 시나, 울루그베크 등 이 지역 학자들이 세계 과학에 남긴 업적을 소개합니다. 가장 귀한 보물은 우스만 쿠란으로 알려진 고대 쿠픽체 쿠란입니다. 개방 시간과 입장권은 미리 확인하세요." },
    de: { name: "Zentrum für Islamische Zivilisation", desc: "Der größte neue Kultur- und Forschungskomplex des Landes gegenüber dem Hazrati-Imam-Ensemble: ein riesiges Gebäude mit Kuppeln und Portalen, das ein Museum, ein Forschungsinstitut, Bibliotheken und Handwerkswerkstätten beherbergt. Die Ausstellung erzählt die Geschichte der usbekischen Lande von der Antike bis heute und den Beitrag hiesiger Gelehrter – al-Chwarizmi, Biruni, Ibn Sina, Ulugh Beg – zur Weltwissenschaft. Der größte Schatz ist ein alter kufischer Koran, bekannt als Osman-Koran. Öffnungszeiten und Tickets vorher prüfen." },
    fr: { name: "Centre de la civilisation islamique", desc: "Le plus grand nouveau complexe culturel et scientifique du pays, face à l'ensemble Hazrati Imam : un immense bâtiment à coupoles et portails abritant un musée, un institut de recherche, des bibliothèques et des ateliers d'artisans. L'exposition retrace l'histoire des terres ouzbèkes de l'Antiquité à nos jours et l'apport des savants locaux – al-Khwarizmi, Biruni, Ibn Sina, Ouloug Beg – à la science mondiale. Son plus grand trésor est un ancien Coran coufique dit Coran d'Othman. Vérifiez horaires et billets à l'avance." },
    ja: { name: "イスラム文明センター", desc: "ハズラティ・イマーム建築群の向かいにある国内最大の新しい文化・研究施設で、ドームと門をもつ巨大な建物に博物館、研究所、図書館、工房が入っています。展示は古代から現代までのウズベキスタンの地の歴史と、フワーリズミー、ビールーニー、イブン・シーナー、ウルグベクなど地元の学者が世界の科学に果たした貢献を紹介します。最大の宝はウスマーン写本として知られる古いクーフィー体のコーランです。開館時間とチケットは事前に確認を。" },
    tr: { name: "İslam Medeniyeti Merkezi", desc: "Hazreti İmam Külliyesi'nin karşısında ülkenin en büyük yeni kültür ve araştırma kompleksi: kubbeli ve taç kapılı dev bir binada müze, araştırma enstitüsü, kütüphaneler ve zanaat atölyeleri yer alır. Sergi, Özbekistan topraklarının antik çağdan bugüne tarihini ve Harezmi, Biruni, İbn Sina, Uluğ Bey gibi yerli âlimlerin dünya bilimine katkısını anlatır. En büyük hazinesi Hz. Osman Mushafı olarak bilinen eski bir Kufi Kur'an'dır. Saatleri ve biletleri önceden kontrol edin." },
    ar: { name: "مركز الحضارة الإسلامية", desc: "أكبر مجمع ثقافي وبحثي جديد في البلاد، قبالة مجمع حضرتي إمام: مبنى ضخم بقباب وبوابات يضم متحفًا ومعهدًا للأبحاث ومكتبات وورشًا للحرف. يروي المعرض تاريخ أرض أوزبكستان من العصور القديمة حتى اليوم، وإسهام علمائها – الخوارزمي والبيروني وابن سينا وأولوغ بيك – في العلم العالمي. أثمن كنوزه مصحف كوفي قديم يُعرف بمصحف عثمان. تحقّق من مواعيد الفتح والتذاكر مسبقًا." },
  },
  "tk-historymuseum": {
    zh: { name: "乌兹别克斯坦国家历史博物馆", desc: "中亚最古老的博物馆，建于1876年，原名突厥斯坦人民博物馆。它位于一座1970年的现代主义建筑中，2026年与塔什干其他现代主义建筑一起被列入联合国教科文组织世界遗产名录；经过两年整修，博物馆于2026年夏重新开放。镇馆之宝是来自铁尔梅兹附近法亚兹特佩的佛教浮雕，此外还有古城遗物、手稿、钱币以及从石器时代到今天的民族志藏品。" },
    ko: { name: "우즈베키스탄 국립역사박물관", desc: "1876년 투르키스탄 인민박물관으로 설립된 중앙아시아에서 가장 오래된 박물관입니다. 1970년에 지어진 모더니즘 건물에 있으며, 이 건물은 2026년 타슈켄트 모더니즘의 다른 건축물들과 함께 유네스코 세계유산에 등재되었고 박물관은 2년간의 보수를 마치고 2026년 여름 다시 문을 열었습니다. 대표 소장품은 테르메즈 근처 파야즈 테파에서 나온 불교 부조이며, 고대 도시 유물, 필사본, 주화, 석기 시대부터 현재까지의 민속 자료가 있습니다." },
    de: { name: "Staatliches Museum für Geschichte Usbekistans", desc: "Das älteste Museum Zentralasiens, 1876 als Volksmuseum Turkestans gegründet. Es befindet sich in einem modernistischen Bau von 1970, der 2026 mit anderen Denkmälern der Taschkenter Moderne in die UNESCO-Welterbeliste aufgenommen wurde; das Museum öffnete im Sommer 2026 nach zweijähriger Renovierung wieder. Juwel der Sammlung ist das buddhistische Relief aus Fayaz Tepe bei Termes, dazu Funde aus antiken Städten, Handschriften, Münzen und Ethnografie von der Steinzeit bis heute." },
    fr: { name: "Musée d'État d'histoire de l'Ouzbékistan", desc: "Le plus ancien musée d'Asie centrale, fondé en 1876 comme Musée populaire du Turkestan. Il occupe un bâtiment moderniste de 1970, inscrit en 2026 au patrimoine mondial de l'UNESCO avec d'autres monuments du modernisme de Tachkent ; le musée a rouvert à l'été 2026 après deux ans de rénovation. Le joyau de la collection est le relief bouddhique de Fayaz Tepe près de Termez, à côté d'objets de cités antiques, de manuscrits, de monnaies et d'ethnographie de l'âge de pierre à nos jours." },
    ja: { name: "ウズベキスタン国立歴史博物館", desc: "1876年にトルキスタン民衆博物館として創設された中央アジア最古の博物館です。1970年のモダニズム建築に入っており、この建物は2026年にタシケント・モダニズムの他の建築とともにユネスコ世界遺産に登録され、博物館は2年間の改修を経て2026年夏に再開しました。目玉はテルメズ近郊ファヤズ・テパの仏教レリーフで、古代都市の出土品、写本、硬貨、石器時代から現代までの民族資料も展示されています。" },
    tr: { name: "Özbekistan Devlet Tarih Müzesi", desc: "1876'da Türkistan Halk Müzesi olarak kurulan Orta Asya'nın en eski müzesi. 1970 tarihli modernist bir binada yer alır; bina 2026'da Taşkent modernizminin diğer anıtlarıyla birlikte UNESCO Dünya Mirası Listesi'ne alındı ve müze iki yıllık tadilattan sonra 2026 yazında yeniden açıldı. Koleksiyonun incisi Tirmiz yakınındaki Fayaz Tepe'den gelen Budist kabartmadır; yanında antik kentlerden buluntular, el yazmaları, sikkeler ve Taş Devri'nden bugüne etnografya bulunur." },
    ar: { name: "متحف الدولة لتاريخ أوزبكستان", desc: "أقدم متحف في آسيا الوسطى، أُسس عام 1876 باسم المتحف الشعبي لتركستان. يشغل مبنى حداثيًا من عام 1970 أُدرج عام 2026 مع معالم أخرى من حداثة طشقند في قائمة التراث العالمي لليونسكو، وأُعيد افتتاح المتحف صيف 2026 بعد عامين من التجديد. جوهرة المجموعة النقش البوذي من فياز تبه قرب ترمذ، إلى جانب لقى من المدن القديمة ومخطوطات وعملات ومقتنيات إثنوغرافية من العصر الحجري حتى اليوم." },
  },
  "tk-timurmuseum": {
    zh: { name: "阿米尔·帖木儿博物馆", desc: "阿米尔·帖木儿广场旁一座带棱纹蓝色穹顶的博物馆，1996年为纪念帖木儿诞辰660周年而开放。五千多件展品讲述阿米尔·帖木儿及其后裔的故事：武器、钱币、手稿、陶器、细密画复制品以及撒马尔罕和沙赫里萨布兹宏伟建筑的模型。主厅本身就是一景，有彩绘镀金穹顶和巨大的水晶吊灯。去撒马尔罕之前来这里是很好的开始。" },
    ko: { name: "아미르 티무르 박물관", desc: "아미르 티무르 광장 옆, 골이 진 파란 돔 아래 있는 박물관으로 티무르 탄생 660주년을 맞아 1996년 문을 열었습니다. 5천 점이 넘는 전시품이 아미르 티무르와 그 후손의 이야기를 들려줍니다. 무기, 주화, 필사본, 도자기, 세밀화 복제품, 사마르칸트와 샤흐리사브즈의 위대한 건축물 모형 등이 있습니다. 채색 금박 돔과 거대한 크리스털 샹들리에가 있는 중앙 홀 자체가 볼거리입니다. 사마르칸트 여행 전 들르기 좋습니다." },
    de: { name: "Amir-Timur-Museum", desc: "Ein Museum unter einer gerippten blauen Kuppel am Amir-Temur-Platz, 1996 zum 660. Geburtstag Temurs eröffnet. Mehr als fünftausend Exponate erzählen von Amir Temur und seinen Nachfahren: Waffen, Münzen, Handschriften, Keramik, Kopien von Miniaturen und Modelle der großen Bauten Samarkands und Schahrisabs'. Der Hauptsaal mit bemalter, vergoldeter Kuppel und riesigem Kristalllüster ist selbst eine Sehenswürdigkeit. Ein idealer Auftakt vor einer Reise nach Samarkand." },
    fr: { name: "Musée Amir Timour", desc: "Un musée sous une coupole bleue côtelée près de la place Amir Timour, ouvert en 1996 pour le 660e anniversaire de Timour. Plus de cinq mille objets racontent l'histoire d'Amir Timour et de ses descendants : armes, monnaies, manuscrits, céramiques, copies de miniatures et maquettes des grands édifices de Samarcande et de Chakhrisabz. La salle principale, avec sa coupole peinte et dorée et son immense lustre de cristal, vaut à elle seule la visite. Un excellent préambule à un voyage à Samarcande." },
    ja: { name: "アミール・ティムール博物館", desc: "アミール・ティムール広場のそばに建つ、筋の入った青いドームの博物館で、ティムール生誕660年を記念して1996年に開館しました。5000点を超える展示品が、武器、硬貨、写本、陶器、細密画の複製、サマルカンドとシャフリサブズの壮大な建築の模型などでアミール・ティムールとその子孫の物語を伝えます。彩色・金箔のドームと巨大なクリスタルのシャンデリアがある中央ホール自体が見ものです。サマルカンド旅行の前に訪れるのに最適です。" },
    tr: { name: "Emir Timur Müzesi", desc: "Emir Timur Meydanı'nın yanında, dilimli mavi bir kubbenin altında, Timur'un doğumunun 660. yıldönümü için 1996'da açılan müze. Beş binden fazla eser Emir Timur'u ve torunlarını anlatır: silahlar, sikkeler, el yazmaları, seramikler, minyatür kopyaları ve Semerkant ile Şehrisebz'in büyük yapılarının maketleri. Boyalı ve yaldızlı kubbesi ve dev kristal avizesiyle ana salon başlı başına görülmeye değer. Semerkant gezisinden önce harika bir başlangıç." },
    ar: { name: "متحف أمير تيمور", desc: "متحف تحت قبة زرقاء مضلّعة بجوار ساحة أمير تيمور، افتُتح عام 1996 بمناسبة الذكرى الـ660 لميلاد تيمور. أكثر من خمسة آلاف قطعة تروي قصة أمير تيمور وأحفاده: أسلحة وعملات ومخطوطات وخزف ونسخ من المنمنمات ونماذج للمباني العظيمة في سمرقند وشهرسبز. القاعة الرئيسية بقبتها المرسومة المذهّبة وثريتها الكريستالية الضخمة معلم بحد ذاتها. بداية رائعة قبل رحلة إلى سمرقند." },
  },
  "tk-appliedarts": {
    zh: { name: "国家实用艺术博物馆", desc: "博物馆位于19世纪末俄国外交官亚历山大·波洛夫采夫的宅邸中，这座宅邸本身就是一件杰作：塔什干、布哈拉和费尔干纳最好的工匠制作的雕花石膏、彩绘天花板和木柱。馆藏数千件民间艺术品——苏扎尼刺绣和艾德莱斯绸、花帽、首饰、陶器、乐器和木雕。博物馆商店出售当代工匠的作品。" },
    ko: { name: "국립 응용미술 박물관", desc: "19세기 말 러시아 외교관 알렉산드르 폴로프체프의 저택에 자리한 박물관으로, 건물 자체가 걸작입니다. 타슈켄트, 부하라, 페르가나 최고의 장인들이 만든 간치 조각, 채색 천장, 나무 기둥이 있습니다. 수자니와 아틀라스 비단, 전통 모자, 장신구, 도자기, 악기, 목공예 등 수천 점의 민속 공예품을 소장하고 있으며, 박물관 상점에서는 현대 장인들의 작품을 판매합니다." },
    de: { name: "Staatliches Museum für Angewandte Kunst", desc: "Ein Museum in der Villa des russischen Diplomaten Alexander Polowzew aus dem späten 19. Jahrhundert, die selbst ein Meisterwerk ist: geschnitzter Gantsch, bemalte Decken und Holzsäulen der besten Handwerker aus Taschkent, Buchara und Fergana. Die Sammlung umfasst Tausende Volkskunstobjekte – Susani und Atlas-Seide, Käppchen, Schmuck, Keramik, Musikinstrumente und Holzschnitzerei. Der Museumsladen verkauft Arbeiten heutiger Kunsthandwerker." },
    fr: { name: "Musée d'État des Arts appliqués", desc: "Un musée dans la demeure de la fin du XIXe siècle du diplomate russe Alexandre Polovtsev, chef-d'œuvre en soi : ganch sculpté, plafonds peints et colonnes de bois réalisés par les meilleurs artisans de Tachkent, Boukhara et Ferghana. La collection compte des milliers d'objets d'art populaire – suzanis et soie atlas, calottes, bijoux, céramiques, instruments de musique et bois sculpté. La boutique du musée vend des œuvres d'artisans contemporains." },
    ja: { name: "国立応用美術博物館", desc: "19世紀末のロシア人外交官アレクサンドル・ポロフツェフの邸宅に入る博物館で、建物自体が傑作です。タシケント、ブハラ、フェルガナの最高の職人によるガンチ彫刻、彩色天井、木の柱が見られます。スザニやアトラス絹、帽子、宝飾品、陶器、楽器、木彫など数千点の民芸品を所蔵し、ミュージアムショップでは現代の職人の作品を販売しています。" },
    tr: { name: "Devlet Uygulamalı Sanatlar Müzesi", desc: "Rus diplomat Aleksandr Polovtsev'in 19. yüzyıl sonuna ait konağında bir müze; bina başlı başına bir şaheserdir: Taşkent, Buhara ve Fergana'nın en iyi ustalarının yaptığı oymalı alçı, boyalı tavanlar ve ahşap sütunlar. Koleksiyonda binlerce halk sanatı eseri vardır – suzaniler ve atlas ipeği, takkeler, takılar, seramikler, müzik aletleri ve ahşap oymacılığı. Müze dükkânında çağdaş zanaatkârların eserleri satılır." },
    ar: { name: "متحف الدولة للفنون التطبيقية", desc: "متحف في قصر الدبلوماسي الروسي ألكسندر بولوفتسيف من أواخر القرن التاسع عشر، وهو تحفة بحد ذاته: جص منحوت وأسقف مرسومة وأعمدة خشبية صنعها أمهر حرفيي طشقند وبخارى وفرغانة. تضم المجموعة آلاف القطع من الفن الشعبي – السوزاني وحرير الأطلس والقلانس والحلي والخزف والآلات الموسيقية والحفر على الخشب. ويبيع متجر المتحف أعمال حرفيين معاصرين." },
  },
  "tk-artmuseum": {
    zh: { name: "乌兹别克斯坦国家美术馆", desc: "全国最大的美术馆，1918年以曾居住在塔什干的尼古拉·康斯坦丁诺维奇大公的收藏为基础建立。如今它位于一座1974年的现代主义建筑中，收藏俄罗斯和西欧绘画、东方艺术、佛教壁画、刺绣以及20世纪乌兹别克艺术家的作品。出发前请确认开放时间：部分展厅可能因整修关闭。" },
    ko: { name: "우즈베키스탄 국립미술관", desc: "타슈켄트에 살았던 니콜라이 콘스탄티노비치 대공의 소장품을 바탕으로 1918년 설립된 나라 최대의 미술관입니다. 현재 1974년의 모더니즘 건물에 있으며, 러시아와 서유럽 회화, 동양 미술, 불교 벽화, 자수, 20세기 우즈베크 화가들의 작품을 소장하고 있습니다. 일부 전시실이 보수로 닫혀 있을 수 있으니 가기 전에 개방 시간을 확인하세요." },
    de: { name: "Staatliches Kunstmuseum Usbekistans", desc: "Das größte Kunstmuseum des Landes, 1918 aus der Sammlung des in Taschkent lebenden Großfürsten Nikolai Konstantinowitsch Romanow gegründet. Heute befindet es sich in einem modernistischen Bau von 1974 und zeigt russische und westeuropäische Malerei, orientalische Kunst, buddhistische Fresken, Stickereien und Werke usbekischer Künstler des 20. Jahrhunderts. Prüfen Sie vorher die Öffnungszeiten: Einige Säle können wegen Renovierung geschlossen sein." },
    fr: { name: "Musée d'État des Beaux-Arts d'Ouzbékistan", desc: "Le plus grand musée d'art du pays, fondé en 1918 à partir de la collection du grand-duc Nicolas Konstantinovitch Romanov, qui vivait à Tachkent. Il occupe aujourd'hui un bâtiment moderniste de 1974 et présente peinture russe et d'Europe occidentale, art oriental, fresques bouddhiques, broderies et œuvres d'artistes ouzbeks du XXe siècle. Vérifiez les horaires avant d'y aller : certaines salles peuvent être fermées pour travaux." },
    ja: { name: "ウズベキスタン国立美術館", desc: "タシケントに住んだニコライ・コンスタンチノヴィチ大公のコレクションをもとに1918年に創設された国内最大の美術館です。現在は1974年のモダニズム建築に入り、ロシアと西欧の絵画、東洋美術、仏教壁画、刺繍、20世紀ウズベクの画家の作品を所蔵しています。改修で一部の展示室が閉まっていることがあるので、開館時間を確認してから行きましょう。" },
    tr: { name: "Özbekistan Devlet Sanat Müzesi", desc: "Taşkent'te yaşamış Büyük Dük Nikolay Konstantinoviç Romanov'un koleksiyonundan 1918'de kurulan ülkenin en büyük sanat müzesi. Bugün 1974 tarihli modernist bir binada yer alır; Rus ve Batı Avrupa resmi, Doğu sanatı, Budist freskler, işlemeler ve 20. yüzyıl Özbek sanatçılarının eserlerini barındırır. Gitmeden önce saatleri kontrol edin: bazı salonlar tadilat nedeniyle kapalı olabilir." },
    ar: { name: "متحف الدولة للفنون في أوزبكستان", desc: "أكبر متحف فني في البلاد، أُسس عام 1918 من مجموعة الدوق الأكبر نيكولاي كونستانتينوفيتش رومانوف الذي عاش في طشقند. يشغل اليوم مبنى حداثيًا من عام 1974 ويضم لوحات روسية وأوروبية غربية وفنونًا شرقية وجداريات بوذية وتطريزات وأعمالًا لفنانين أوزبك من القرن العشرين. تحقّق من مواعيد الفتح قبل الذهاب، فقد تكون بعض القاعات مغلقة للترميم." },
  },
  "tk-repression": {
    zh: { name: "镇压受害者纪念博物馆", desc: "位于电视塔附近“烈士纪念”纪念建筑群中的博物馆，所在地是20世纪30年代集体处决的地点。圆亭的蓝色穹顶下陈列着19至20世纪从殖民时期到斯大林恐怖时期遭受镇压者的文件、照片和遗物。周围是一座安静的公园，博兹苏运河上方有一条纪念小道。这是悼念之地——请保持肃穆。" },
    ko: { name: "탄압 희생자 박물관", desc: "TV 타워 근처 ‘샤히들라르 호티라시(순교자 추모)’ 기념 단지 안에 있는 박물관으로, 1930년대 대량 처형이 벌어진 곳에 세워졌습니다. 원형 건물의 파란 돔 아래에는 식민지 시기부터 스탈린 대숙청까지 19~20세기에 탄압받은 사람들의 문서, 사진, 유품이 전시되어 있습니다. 주변에는 보즈수 운하 위로 추모의 길이 있는 조용한 공원이 있습니다. 애도의 장소이니 예의를 지켜 주세요." },
    de: { name: "Museum der Opfer der Repressionen", desc: "Ein Museum im Gedenkkomplex Shahidlar Xotirasi („Andenken an die Märtyrer“) nahe dem Fernsehturm, am Ort von Massenerschießungen der 1930er-Jahre. Unter der blauen Kuppel der Rotunde sind Dokumente, Fotos und persönliche Gegenstände von Menschen zu sehen, die im 19. und 20. Jahrhundert Repressionen erlitten – von der Kolonialzeit bis zu Stalins Terror. Ringsum liegt ein stiller Park mit einer Gedenkallee über dem Bozsu-Kanal. Ein Ort der Trauer – bitte respektvoll verhalten." },
    fr: { name: "Musée des victimes de la répression", desc: "Un musée dans le complexe mémorial Chahidlar Khotirasi (Mémoire des martyrs) près de la tour de télévision, sur le lieu d'exécutions de masse des années 1930. Sous la coupole bleue de la rotonde : documents, photos et effets personnels de victimes de la répression aux XIXe et XXe siècles, de la période coloniale à la terreur stalinienne. Autour, un parc paisible avec une allée commémorative au-dessus du canal Bozsou. Un lieu de deuil – merci de rester respectueux." },
    ja: { name: "弾圧犠牲者記念博物館", desc: "テレビ塔近くの「シャヒドラル・ホティラシ（殉難者の記憶）」記念公園内にある博物館で、1930年代に大量処刑が行われた場所に建っています。円形の建物の青いドームの下には、植民地時代からスターリンの大粛清まで、19～20世紀に弾圧を受けた人々の文書、写真、遺品が展示されています。周りにはボズス運河を見下ろす追悼の小道のある静かな公園があります。追悼の場所なので、敬意を払ってください。" },
    tr: { name: "Baskı Kurbanları Müzesi", desc: "Televizyon kulesi yakınındaki Şehitler Hatırası anıt kompleksinde, 1930'lardaki toplu infazların yapıldığı yerde bir müze. Rotondanın mavi kubbesi altında, sömürge döneminden Stalin terörüne kadar 19.–20. yüzyıllarda baskıya uğrayanların belgeleri, fotoğrafları ve kişisel eşyaları sergilenir. Çevresinde Bozsu kanalının üzerinde bir anma yolu bulunan sakin bir park vardır. Bir yas yeri – lütfen saygılı olun." },
    ar: { name: "متحف ضحايا القمع", desc: "متحف في مجمع «شهيدلار خوطيراسي» (ذكرى الشهداء) التذكاري قرب برج التلفزيون، في موقع إعدامات جماعية جرت في ثلاثينيات القرن الماضي. تحت القبة الزرقاء للمبنى الدائري وثائق وصور ومقتنيات شخصية لمن عانوا القمع في القرنين التاسع عشر والعشرين، من الحقبة الاستعمارية حتى إرهاب ستالين. وحوله حديقة هادئة فيها ممر تذكاري يطل على قناة بوزسو. إنه مكان حداد – يُرجى الالتزام بالاحترام." },
  },
  "tk-naturemuseum": {
    zh: { name: "乌兹别克斯坦国家自然博物馆", desc: "中亚最古老的博物馆之一，历史可追溯到1876年。透景画和藏品展示了全国各地的自然——从克孜勒库姆沙漠和咸海荒漠到天山和吉萨尔的冰川：雪豹、鹅喉羚和鸟类，矿物、化石和植物标本。博物馆位于老城哈兹拉提·伊玛目建筑群附近，两处很容易一起游览。孩子们也很喜欢。" },
    ko: { name: "우즈베키스탄 국립자연박물관", desc: "1876년으로 거슬러 올라가는 역사를 지닌 중앙아시아에서 가장 오래된 박물관 중 하나입니다. 디오라마와 소장품이 키질쿰과 아랄 사막에서 톈산과 기사르의 빙하까지 나라 곳곳의 자연을 보여 줍니다. 눈표범, 가젤과 새, 광물, 화석, 식물 표본이 있습니다. 구시가지 하즈라티 이맘 단지 근처에 있어 함께 둘러보기 쉽고, 아이들도 좋아합니다." },
    de: { name: "Staatliches Naturkundemuseum Usbekistans", desc: "Eines der ältesten Museen Zentralasiens, dessen Geschichte bis 1876 zurückreicht. Dioramen und Sammlungen zeigen die Natur jedes Winkels des Landes – von den Wüsten Kysylkum und Aral bis zu den Gletschern des Tianshan und Hissar: Schneeleoparden, Kropfgazellen und Vögel, Mineralien, Fossilien und Herbarien. Das Museum liegt in der Altstadt nahe dem Hazrati-Imam-Ensemble, beides lässt sich gut verbinden. Auch Kinder sind begeistert." },
    fr: { name: "Musée d'État de la Nature d'Ouzbékistan", desc: "L'un des plus anciens musées d'Asie centrale, dont l'histoire remonte à 1876. Dioramas et collections présentent la nature de tous les recoins du pays – des déserts du Kyzylkoum et de l'Aral aux glaciers du Tian Shan et du Hissar : léopards des neiges, gazelles à goitre et oiseaux, minéraux, fossiles et herbiers. Le musée est dans la vieille ville, près de l'ensemble Hazrati Imam, facile à combiner. Les enfants adorent aussi." },
    ja: { name: "ウズベキスタン国立自然博物館", desc: "1876年にさかのぼる歴史をもつ中央アジア最古級の博物館です。ジオラマと収蔵品が、キジルクム砂漠やアラル海の砂漠から天山やヒッサールの氷河まで、国の隅々の自然を紹介します。ユキヒョウ、コウジョウセンガゼルや鳥、鉱物、化石、植物標本などがあります。旧市街のハズラティ・イマーム建築群の近くにあるので一緒に回りやすく、子どもたちにも人気です。" },
    tr: { name: "Özbekistan Devlet Doğa Müzesi", desc: "Geçmişi 1876'ya uzanan Orta Asya'nın en eski müzelerinden biri. Dioramalar ve koleksiyonlar ülkenin her köşesinin doğasını gösterir – Kızılkum ve Aral çöllerinden Tanrı Dağları ve Hisar buzullarına: kar leoparları, ceylanlar ve kuşlar, mineraller, fosiller ve herbaryumlar. Müze eski şehirde Hazreti İmam Külliyesi'nin yakınındadır; ikisini birlikte gezmek kolaydır. Çocuklar da çok sever." },
    ar: { name: "متحف الدولة للطبيعة في أوزبكستان", desc: "من أقدم متاحف آسيا الوسطى، ويعود تاريخه إلى عام 1876. تعرض المجسمات والمجموعات طبيعة كل ركن من البلاد – من صحراوي قيزيل قوم وآرال إلى أنهار تيان شان وحصار الجليدية: النمور الثلجية والغزلان والطيور والمعادن والأحافير والمعشبات. يقع المتحف في المدينة القديمة قرب مجمع حضرتي إمام، فيسهل الجمع بينهما. ويحبه الأطفال أيضًا." },
  },
  "tk-railwaymuseum": {
    zh: { name: "塔什干铁路博物馆", desc: "塔什干火车站旁的露天博物馆，1989年开放。轨道上停放着各个时代的蒸汽机车、内燃机车、电力机车和车厢——从十月革命前的蒸汽机车到修建中亚铁路的苏联机车。许多驾驶室都可以爬进去。一个小展厅里陈列着模型、制服和铁路文献。带孩子来是不错的选择。" },
    ko: { name: "타슈켄트 철도 박물관", desc: "타슈켄트 기차역 옆에 1989년 문을 연 야외 박물관입니다. 혁명 이전의 증기기관차부터 중앙아시아 철도를 건설한 소련 기관차까지, 여러 시대의 증기·디젤·전기 기관차와 객차가 선로 위에 서 있습니다. 많은 기관실에 직접 올라가 볼 수 있고, 작은 전시관에는 모형, 제복, 철도 문서가 있습니다. 아이와 함께 가기 좋습니다." },
    de: { name: "Eisenbahnmuseum Taschkent", desc: "Ein Freilichtmuseum neben dem Taschkenter Bahnhof, eröffnet 1989. Auf den Gleisen stehen Dampf-, Diesel- und Elektrolokomotiven sowie Waggons verschiedener Epochen – von vorrevolutionären Dampfloks bis zu den sowjetischen Loks, die Zentralasiens Bahnen bauten. In viele Führerstände kann man hineinklettern. Ein kleiner Pavillon zeigt Modelle, Uniformen und Eisenbahndokumente. Eine gute Wahl mit Kindern." },
    fr: { name: "Musée du chemin de fer de Tachkent", desc: "Un musée en plein air à côté de la gare de Tachkent, ouvert en 1989. Locomotives à vapeur, diesel et électriques et voitures de différentes époques stationnent sur les voies – des machines à vapeur d'avant la révolution aux locomotives soviétiques qui ont construit les chemins de fer d'Asie centrale. On peut monter dans de nombreuses cabines. Un petit pavillon conserve maquettes, uniformes et documents ferroviaires. Un bon choix avec des enfants." },
    ja: { name: "タシケント鉄道博物館", desc: "タシケント駅の隣に1989年に開館した野外博物館です。革命前の蒸気機関車から中央アジアの鉄道を築いたソ連の機関車まで、さまざまな時代の蒸気・ディーゼル・電気機関車や客車が線路に並びます。多くの運転室に乗り込むことができ、小さな展示館には模型、制服、鉄道の資料があります。子ども連れにおすすめです。" },
    tr: { name: "Taşkent Demiryolu Müzesi", desc: "Taşkent tren garının yanında, 1989'da açılan bir açık hava müzesi. Raylarda farklı dönemlerden buharlı, dizel ve elektrikli lokomotifler ile vagonlar durur – devrim öncesi buharlı lokomotiflerden Orta Asya demiryollarını kuran Sovyet lokomotiflerine kadar. Birçok makinist kabinine tırmanabilirsiniz. Küçük bir pavyonda maketler, üniformalar ve demiryolu belgeleri bulunur. Çocuklarla iyi bir seçim." },
    ar: { name: "متحف طشقند للسكك الحديدية", desc: "متحف مفتوح بجوار محطة قطار طشقند، افتُتح عام 1989. تقف على السكك قاطرات بخارية وديزل وكهربائية وعربات من عصور مختلفة – من القاطرات البخارية قبل الثورة إلى القاطرات السوفيتية التي بنت سكك آسيا الوسطى. ويمكن الصعود إلى كثير من مقصورات القيادة. وفي جناح صغير نماذج وأزياء ووثائق السكك. خيار جيد مع الأطفال." },
  },
  "tk-polytech": {
    zh: { name: "塔什干理工博物馆", desc: "距阿米尔·帖木儿广场五分钟的科技博物馆，2015年11月开放。主要部分是汽车史：胜利牌、伏尔加、吉姆、政府用的海鸥轿车、战时缴获的汽车以及乌兹别克斯坦最早的拖拉机。还有物理和工程互动区以及儿童角。规模不大但非常生动——大人孩子都喜欢。" },
    ko: { name: "타슈켄트 폴리테크닉 박물관", desc: "아미르 티무르 광장에서 5분 거리에 있는 기술 박물관으로 2015년 11월 문을 열었습니다. 중심은 자동차의 역사로, 포베다, 볼가, ZIM, 정부용 차이카, 전시 노획 차량, 우즈베키스탄 최초의 트랙터 등이 있습니다. 물리·공학 체험 공간과 어린이 코너도 있습니다. 작지만 생동감 있어 어른도 아이도 즐깁니다." },
    de: { name: "Polytechnisches Museum Taschkent", desc: "Ein Technikmuseum fünf Minuten vom Amir-Temur-Platz, eröffnet im November 2015. Hauptteil ist die Geschichte des Autos: Pobeda, Wolga, ZIM, Regierungs-Tschaikas, Beutewagen aus dem Krieg und die ersten Traktoren Usbekistans. Es gibt interaktive Physik- und Technikbereiche und eine Kinderecke. Klein, aber sehr lebendig – Erwachsene und Kinder haben Spaß." },
    fr: { name: "Musée polytechnique de Tachkent", desc: "Un musée des techniques à cinq minutes de la place Amir Timour, ouvert en novembre 2015. Sa partie principale retrace l'histoire de l'automobile : Pobeda, Volga, ZIM, Tchaïka gouvernementales, voitures prises pendant la guerre et premiers tracteurs d'Ouzbékistan. Espaces interactifs de physique et d'ingénierie et coin pour enfants. Petit mais très vivant – adultes et enfants s'y plaisent." },
    ja: { name: "タシケント工業技術博物館", desc: "アミール・ティムール広場から5分の技術博物館で、2015年11月に開館しました。中心は自動車の歴史で、ポベーダ、ヴォルガ、ZIM、政府用チャイカ、戦時中の鹵獲車、ウズベキスタン初期のトラクターなどが並びます。物理や工学の体験コーナー、子ども向けのスペースもあります。小さいながら活気があり、大人も子どもも楽しめます。" },
    tr: { name: "Taşkent Politeknik Müzesi", desc: "Emir Timur Meydanı'na beş dakika mesafede, Kasım 2015'te açılan bir teknoloji müzesi. Ana bölümü otomobil tarihidir: Pobeda, Volga, ZIM, devlet Çaykaları, savaşta ele geçirilen arabalar ve Özbekistan'ın ilk traktörleri. Etkileşimli fizik ve mühendislik alanları ile bir çocuk köşesi vardır. Küçük ama çok canlı – yetişkinler de çocuklar da keyif alır." },
    ar: { name: "متحف طشقند التقني", desc: "متحف للتقنية على بعد خمس دقائق من ساحة أمير تيمور، افتُتح في نوفمبر 2015. قسمه الرئيسي تاريخ السيارات: «بوبيدا» و«فولغا» و«زيم» وسيارات «تشايكا» الحكومية وسيارات غنمت في الحرب وأول جرارات أوزبكستان. وفيه مناطق تفاعلية للفيزياء والهندسة وركن للأطفال. صغير لكنه نابض بالحياة – يستمتع به الكبار والصغار." },
  },
  "tk-oqsaroy": {
    zh: { name: "伊斯兰·卡里莫夫纪念馆（白宫）", desc: "乌兹别克斯坦首任总统伊斯兰·卡里莫夫的纪念馆，位于“白宫”大楼内——这里曾是国家元首在安霍尔运河边的官邸。展览介绍卡里莫夫的生平与工作以及国家独立后的最初几十年。参观安排和导览请提前确认。" },
    ko: { name: "이슬람 카리모프 기념관(오크사로이)", desc: "우즈베키스탄 초대 대통령 이슬람 카리모프의 기념관으로, 안호르 운하 옆의 옛 국가원수 관저였던 오크사로이(‘하얀 궁전’) 건물에 있습니다. 전시는 카리모프의 생애와 업적, 독립 이후 첫 수십 년을 다룹니다. 관람 방법과 투어는 미리 확인하세요." },
    de: { name: "Islam-Karimow-Gedenkmuseum (Oqsaroy)", desc: "Ein Gedenkmuseum für Islam Karimow, den ersten Präsidenten Usbekistans, im Gebäude Oqsaroy („Weißer Palast“) – der früheren Residenz des Staatsoberhaupts am Ankhor-Kanal. Die Ausstellung zeigt Karimows Leben und Wirken sowie die ersten Jahrzehnte der Unabhängigkeit. Besuchsmöglichkeiten und Führungen vorher erfragen." },
    fr: { name: "Musée mémorial Islam Karimov (Oqsaroy)", desc: "Un musée mémorial consacré à Islam Karimov, premier président de l'Ouzbékistan, dans le bâtiment Oqsaroy (« Palais blanc ») – ancienne résidence du chef de l'État au bord du canal Ankhor. L'exposition retrace la vie et l'action de Karimov et les premières décennies de l'indépendance. Modalités de visite et visites guidées à vérifier à l'avance." },
    ja: { name: "イスラム・カリモフ記念博物館（オクサロイ）", desc: "ウズベキスタン初代大統領イスラム・カリモフの記念博物館で、アンホル運河沿いにあるかつての国家元首の公邸オクサロイ（「白い宮殿」）に入っています。展示はカリモフの生涯と業績、独立後最初の数十年を紹介します。見学方法やツアーは事前に確認してください。" },
    tr: { name: "İslam Kerimov Anı Müzesi (Oqsaroy)", desc: "Özbekistan'ın ilk cumhurbaşkanı İslam Kerimov'un anı müzesi; Ankhor kanalı kıyısındaki eski devlet başkanı konutu Oqsaroy (“Beyaz Saray”) binasında. Sergi Kerimov'un hayatını ve çalışmalarını, bağımsızlığın ilk on yıllarını anlatır. Ziyaret koşulları ve turlar önceden öğrenilmelidir." },
    ar: { name: "متحف إسلام كريموف التذكاري (أوقصروي)", desc: "متحف تذكاري لإسلام كريموف، أول رئيس لأوزبكستان، في مبنى «أوقصروي» (القصر الأبيض) – المقر السابق لرئيس الدولة على قناة أنخور. يعرض حياة كريموف وأعماله والعقود الأولى من استقلال البلاد. تحقّق مسبقًا من ترتيبات الزيارة والجولات." },
  },
  "tk-photohouse": {
    zh: { name: "塔什干摄影之家", desc: "乌兹别克斯坦艺术研究院下属的展览中心，位于塔什干钟楼旁的一座历史建筑中。这里举办乌兹别克和外国摄影师的轮换展览——从老塔什干的档案照片到当代纪实和艺术摄影。展览内容经常更换，去之前请查看当前展出。" },
    ko: { name: "타슈켄트 사진의 집", desc: "타슈켄트 시계탑 옆 역사적 건물에 있는 우즈베키스탄 예술원의 전시 센터입니다. 옛 타슈켄트의 기록 사진부터 현대 다큐멘터리·예술 사진까지, 우즈베크와 외국 사진가들의 전시가 바뀌어 가며 열립니다. 프로그램이 자주 바뀌니 가기 전에 현재 전시를 확인하세요." },
    de: { name: "Haus der Fotografie Taschkent", desc: "Ein Ausstellungszentrum der Akademie der Künste Usbekistans in einem historischen Gebäude neben dem Taschkenter Glockenspiel. Hier laufen wechselnde Ausstellungen usbekischer und ausländischer Fotografen – von Archivbildern des alten Taschkent bis zu zeitgenössischer Dokumentar- und Kunstfotografie. Das Programm wechselt, also vorher nachsehen, was gezeigt wird." },
    fr: { name: "Maison de la photographie de Tachkent", desc: "Un centre d'exposition de l'Académie des arts d'Ouzbékistan dans un bâtiment historique à côté du carillon de Tachkent. Il accueille des expositions temporaires de photographes ouzbeks et étrangers – des images d'archives du vieux Tachkent à la photographie documentaire et artistique contemporaine. La programmation change, renseignez-vous avant de venir." },
    ja: { name: "タシケント写真の家", desc: "タシケントの時計塔の隣にある歴史的建物に入るウズベキスタン芸術アカデミーの展示センターです。旧タシケントの記録写真から現代のドキュメンタリー写真やアート写真まで、ウズベクと外国の写真家の企画展が入れ替わりで開かれます。展示内容は変わるので、訪れる前に確認を。" },
    tr: { name: "Taşkent Fotoğraf Evi", desc: "Taşkent Saat Kulesi'nin yanındaki tarihi bir binada Özbekistan Sanat Akademisi'nin sergi merkezi. Eski Taşkent'in arşiv fotoğraflarından çağdaş belgesel ve sanat fotoğrafçılığına kadar Özbek ve yabancı fotoğrafçıların değişen sergilerine ev sahipliği yapar. Program değiştiği için gitmeden önce neler olduğuna bakın." },
    ar: { name: "دار طشقند للتصوير الفوتوغرافي", desc: "مركز معارض تابع لأكاديمية الفنون في أوزبكستان في مبنى تاريخي بجوار ساعة طشقند الدقّاقة. يستضيف معارض متجددة لمصورين أوزبك وأجانب – من الصور الأرشيفية لطشقند القديمة إلى التصوير الوثائقي والفني المعاصر. يتغير البرنامج، فتحقّق مما يُعرض قبل الذهاب." },
  },
  "tk-charvak": {
    zh: { name: "恰尔瓦克水库", desc: "塔什干州的高山“海”，距首都80公里：海拔860米处，乌加姆、普斯凯姆和恰特卡尔山脉的支脉之间是一片绿松石色的湖水。1964年起修建了恰尔瓦克水电站168米高的堆石坝，水库随之形成，汇集了普斯凯姆河、科克苏河和恰特卡尔河。夏天有海滩、度假村和水上运动；春秋两季可以欣赏雪峰美景。夏末水位会明显下降。" },
    ko: { name: "차르바크 저수지", desc: "수도에서 80km 떨어진 타슈켄트주의 산속 ‘바다’로, 해발 860m에서 우감, 프스켐, 차트칼 산맥의 지맥 사이에 청록빛 물이 펼쳐집니다. 1964년부터 건설된 차르바크 수력발전소의 높이 168m 석괴댐이 들어서며 생겨났고, 프스켐강, 콕수강, 차트칼강이 흘러듭니다. 여름에는 해변과 리조트, 수상 스포츠를, 봄과 가을에는 눈 덮인 봉우리 풍경을 즐길 수 있습니다. 늦여름에는 수위가 눈에 띄게 낮아집니다." },
    de: { name: "Tscharwak-Stausee", desc: "Das Gebirgs-„Meer“ der Region Taschkent, 80 km von der Hauptstadt: türkisfarbenes Wasser zwischen Ausläufern der Ugam-, Pskem- und Tschatkal-Ketten auf 860 Metern. Der Stausee entstand nach dem Bau des 168 Meter hohen Steinschüttdamms des Tscharwak-Wasserkraftwerks ab 1964 und nahm die Flüsse Pskem, Koksu und Tschatkal auf. Im Sommer gibt es Strände, Resorts und Wassersport, im Frühling und Herbst Blicke auf schneebedeckte Gipfel. Bis Ende Sommer sinkt der Wasserstand deutlich." },
    fr: { name: "Réservoir de Tcharvak", desc: "La « mer » de montagne de la région de Tachkent, à 80 km de la capitale : une eau turquoise entre les contreforts des chaînes d'Ougam, du Pskem et du Tchatkal, à 860 mètres. Le réservoir est né après la construction, à partir de 1964, du barrage en enrochement de 168 mètres de la centrale de Tcharvak, qui a recueilli le Pskem, le Koksou et le Tchatkal. L'été : plages, complexes et sports nautiques ; au printemps et en automne, vue sur les sommets enneigés. Le niveau baisse nettement en fin d'été." },
    ja: { name: "チャルヴァク貯水湖", desc: "首都から80km、タシケント州の山の「海」です。標高860m、ウガム、プスケム、チャトカルの山脈の支脈の間にターコイズ色の水が広がります。1964年から建設されたチャルヴァク水力発電所の高さ168mのロックフィルダムによって生まれ、プスケム川、コクス川、チャトカル川が流れ込みます。夏はビーチやリゾート、水上スポーツ、春と秋は雪をいただく峰々の眺めが楽しめます。夏の終わりには水位がかなり下がります。" },
    tr: { name: "Çarvak Barajı Gölü", desc: "Başkente 80 km uzaklıkta Taşkent bölgesinin dağ “denizi”: 860 metrede Ugam, Pskem ve Çatkal sıradağlarının uzantıları arasında turkuaz bir su. Göl, 1964'ten itibaren inşa edilen Çarvak hidroelektrik santralinin 168 metrelik kaya dolgu barajıyla oluştu ve Pskem, Koksu ve Çatkal nehirlerini topladı. Yazın plajlar, tatil köyleri ve su sporları; ilkbahar ve sonbaharda karlı zirvelerin manzarası. Yaz sonuna doğru su seviyesi belirgin şekilde düşer." },
    ar: { name: "خزان تشارفاك", desc: "«بحر» جبلي في ولاية طشقند على بعد 80 كم من العاصمة: مياه فيروزية بين امتدادات سلاسل أوغام وبسكيم وتشاتكال على ارتفاع 860 مترًا. تكوّن الخزان بعد بناء سد تشارفاك الصخري بارتفاع 168 مترًا لمحطة الطاقة الكهرومائية منذ عام 1964، فتجمعت فيه أنهار بسكيم وكوكسو وتشاتكال. في الصيف شواطئ ومنتجعات ورياضات مائية، وفي الربيع والخريف مناظر القمم المكسوة بالثلوج. ينخفض منسوب المياه بشكل ملحوظ في أواخر الصيف." },
  },
  "tk-chimgan": {
    zh: { name: "奇姆甘", desc: "乌兹别克斯坦最古老的山地度假区，位于距塔什干85公里的恰特卡尔山脉支脉，早在19世纪80年代就已成为气候疗养地。村子上方耸立着星形的大奇姆甘峰（3309米），有热门的徒步路线可以登顶。12月至3月缆车和雪道开放；春、夏、秋三季则有步道、骑马、瀑布和峡谷野餐。山本身免费，缆车和服务收费。" },
    ko: { name: "침간", desc: "타슈켄트에서 85km 떨어진 차트칼 산맥 지맥에 있는 우즈베키스탄에서 가장 오래된 산악 휴양지로, 1880년대에 이미 기후 요양지가 되었습니다. 마을 위로 별 모양의 대침간산(3,309m)이 솟아 있으며 인기 있는 등산로로 오를 수 있습니다. 12월부터 3월까지는 리프트와 슬로프가 운영되고, 봄·여름·가을에는 트레킹, 승마, 폭포, 계곡 피크닉을 즐깁니다. 산 자체는 무료이고 리프트와 서비스는 유료입니다." },
    de: { name: "Tschimgan", desc: "Usbekistans ältester Bergkurort in den Ausläufern der Tschatkal-Kette, 85 km von Taschkent; schon in den 1880er-Jahren wurde er zum Luftkurort. Über dem Dorf erhebt sich der sternförmige Große Tschimgan (3.309 m), auf den beliebte Wanderrouten führen. Von Dezember bis März laufen Lifte und Pisten; Frühling, Sommer und Herbst bringen Wanderwege, Ausritte, Wasserfälle und Picknicks in den Schluchten. Die Berge sind kostenlos, Lifte und Dienstleistungen kosten." },
    fr: { name: "Tchimgan", desc: "La plus ancienne station de montagne d'Ouzbékistan, dans les contreforts du Tchatkal à 85 km de Tachkent ; elle est devenue station climatique dès les années 1880. Au-dessus du village s'élève le Grand Tchimgan (3 309 m), sommet en étoile accessible par des randonnées prisées. De décembre à mars, remontées et pistes sont ouvertes ; au printemps, en été et en automne : sentiers, balades à cheval, cascades et pique-niques dans les gorges. La montagne est gratuite ; remontées et services payants." },
    ja: { name: "チムガン", desc: "タシケントから85km、チャトカル山脈の支脈にあるウズベキスタン最古の山岳リゾートで、1880年代にはすでに保養地になっていました。村の上には星形の大チムガン山（3309m）がそびえ、人気の登山ルートで山頂を目指せます。12月から3月はリフトとゲレンデが営業し、春・夏・秋はトレイル、乗馬、滝、渓谷でのピクニックが楽しめます。山自体は無料で、リフトやサービスは有料です。" },
    tr: { name: "Çimgan", desc: "Taşkent'e 85 km uzaklıkta, Çatkal sıradağlarının uzantılarında Özbekistan'ın en eski dağ tatil yeri; daha 1880'lerde iklim tedavi merkezi olmuştu. Köyün üzerinde yıldız biçimli Büyük Çimgan (3.309 m) yükselir; zirveye popüler yürüyüş rotaları çıkar. Aralık'tan Mart'a teleferikler ve pistler açıktır; ilkbahar, yaz ve sonbaharda patikalar, at gezileri, şelaleler ve vadilerde piknikler vardır. Dağlar ücretsiz, teleferik ve hizmetler ücretlidir." },
    ar: { name: "تشيمغان", desc: "أقدم منتجع جبلي في أوزبكستان، في امتدادات سلسلة تشاتكال على بعد 85 كم من طشقند، وقد صار منتجعًا مناخيًا منذ ثمانينيات القرن التاسع عشر. فوق القرية ترتفع قمة تشيمغان الكبرى (3309 م) ذات الشكل النجمي، وتصعد إليها مسارات مشي شهيرة. من ديسمبر إلى مارس تعمل المصاعد والمنحدرات، وفي الربيع والصيف والخريف مسارات وركوب خيل وشلالات ونزهات في الوديان. الجبال مجانية، والمصاعد والخدمات برسوم." },
  },
  "tk-amirsoy": {
    zh: { name: "阿米尔索伊山地度假村", desc: "乌兹别克斯坦最大、最现代化的滑雪度假村，位于西天山，2019年开业。吊厢和吊椅缆车把你送到海拔两千多米处各种难度的雪道，夏天则通往观景台、徒步路线和山地自行车道。山脚下有木屋、餐厅和装备租赁。从塔什干开车约一个半小时；旺季最好提前购买缆车票。" },
    ko: { name: "아미르소이 산악 리조트", desc: "서부 톈산에 있는 우즈베키스탄 최대이자 가장 현대적인 스키 리조트로 2019년 문을 열었습니다. 곤돌라와 체어리프트가 해발 2천 m 위 모든 수준의 슬로프로 데려다 주며, 여름에는 전망대, 하이킹 코스, 산악자전거 길로 이어집니다. 아래에는 샬레, 레스토랑, 장비 대여소가 있습니다. 타슈켄트에서 차로 약 1시간 반이며, 성수기에는 리프트권을 미리 사는 것이 좋습니다." },
    de: { name: "Bergresort Amirsoy", desc: "Usbekistans größtes und modernstes Skigebiet im westlichen Tianshan, eröffnet 2019. Gondeln und Sessellifte bringen Sie über zweitausend Meter zu Pisten aller Schwierigkeitsgrade, im Sommer zu Aussichtspunkten, Wanderwegen und Mountainbike-Routen. An der Talstation gibt es Chalets, Restaurants und Ausrüstungsverleih. Von Taschkent sind es etwa anderthalb Stunden Fahrt; in der Saison Liftpässe am besten vorab kaufen." },
    fr: { name: "Station de montagne Amirsoy", desc: "La plus grande et la plus moderne station de ski d'Ouzbékistan, dans le Tian Shan occidental, ouverte en 2019. Télécabines et télésièges mènent au-delà de deux mille mètres vers des pistes de tous niveaux, et l'été vers des belvédères, sentiers et itinéraires de VTT. En bas : chalets, restaurants et location de matériel. Environ une heure et demie de route depuis Tachkent ; en saison, achetez les forfaits à l'avance." },
    ja: { name: "アミルソイ山岳リゾート", desc: "西天山にあるウズベキスタン最大で最新のスキーリゾートで、2019年に開業しました。ゴンドラとチェアリフトで標高2000m以上のあらゆるレベルのゲレンデへ、夏は展望台、ハイキングコース、マウンテンバイクのルートへ上がれます。麓にはシャレー、レストラン、レンタルショップがあります。タシケントから車で約1時間半。シーズン中はリフト券を事前に買うのがおすすめです。" },
    tr: { name: "Amirsoy Dağ Tatil Köyü", desc: "Batı Tanrı Dağları'nda, 2019'da açılan Özbekistan'ın en büyük ve en modern kayak merkezi. Gondollar ve telesiyejler sizi iki bin metrenin üzerinde her seviyeden pistlere, yazın ise seyir noktalarına, yürüyüş parkurlarına ve dağ bisikleti rotalarına çıkarır. Aşağıda dağ evleri, restoranlar ve ekipman kiralama vardır. Taşkent'ten yaklaşık bir buçuk saatlik yol; sezonda skipasları önceden almak en iyisidir." },
    ar: { name: "منتجع أميرسوي الجبلي", desc: "أكبر وأحدث منتجع تزلج في أوزبكستان، في غرب تيان شان، افتُتح عام 2019. تنقلك العربات المعلقة والكراسي إلى ما فوق ألفي متر نحو منحدرات لكل المستويات، وفي الصيف إلى نقاط المشاهدة ومسارات المشي ودروب الدراجات الجبلية. وفي الأسفل شاليهات ومطاعم وتأجير معدات. الطريق من طشقند نحو ساعة ونصف، ويُفضل في الموسم شراء تذاكر المصاعد مسبقًا." },
  },
  "tk-beldersay": {
    zh: { name: "别尔杰尔赛", desc: "大奇姆甘山脚下的苏联时代滑雪场，以别尔杰尔赛山溪命名。一条长长的吊椅缆车把你送上库姆别尔山，这里是观赏恰尔瓦克水库和周围山脉的最佳地点之一。冬天人们在这里滑雪，夏天则乘缆车上山看风景、在高山草甸散步。请确认你出行当天缆车是否运营。" },
    ko: { name: "벨데르사이", desc: "대침간산 기슭에 있는 소련 시대의 스키장으로, 벨데르사이 산골짜기 개울에서 이름을 따왔습니다. 긴 체어리프트를 타고 쿰벨산에 오르면 차르바크 저수지와 주변 산맥이 가장 잘 보이는 전망 중 하나가 펼쳐집니다. 겨울에는 스키를 타고, 여름에는 풍경과 고산 초원 산책을 위해 올라갑니다. 여행 날짜에 리프트가 운행하는지 확인하세요." },
    de: { name: "Beldersai", desc: "Ein Skigebiet aus Sowjetzeiten am Fuß des Großen Tschimgan, benannt nach dem Bergbach Beldersai. Ein langer Sessellift bringt Sie auf den Kumbel mit einem der schönsten Blicke auf den Tscharwak-Stausee und die umliegenden Ketten. Im Winter fährt man hier Ski, im Sommer fährt man hinauf für das Panorama und Spaziergänge auf Almwiesen. Prüfen Sie, ob die Lifte an Ihrem Reisetag fahren." },
    fr: { name: "Beldersaï", desc: "Un domaine skiable de l'époque soviétique au pied du Grand Tchimgan, nommé d'après le torrent Beldersaï. Un long télésiège monte au mont Koumbel, d'où l'on a l'une des plus belles vues sur le réservoir de Tcharvak et les chaînes alentour. L'hiver on y skie ; l'été on y monte pour les panoramas et les promenades dans les alpages. Vérifiez que les remontées fonctionnent le jour de votre visite." },
    ja: { name: "ベルデルサイ", desc: "大チムガン山の麓にあるソ連時代のスキー場で、山の渓流ベルデルサイにちなんで名付けられました。長いチェアリフトでクムベル山に上がると、チャルヴァク貯水湖と周囲の山並みを望む絶景の一つが広がります。冬はスキー、夏は景色と高山草原の散策を楽しみに上がります。旅行日にリフトが運行しているか確認を。" },
    tr: { name: "Beldersay", desc: "Büyük Çimgan'ın eteğinde, Beldersay dağ deresinin adını taşıyan Sovyet döneminden bir kayak merkezi. Uzun bir telesiyej sizi Kumbel Dağı'na çıkarır; buradan Çarvak Gölü ve çevredeki sıradağların en güzel manzaralarından biri görünür. Kışın kayak yapılır, yazın manzara ve alpin çayırlarında yürüyüş için çıkılır. Gideceğiniz gün teleferiklerin çalışıp çalışmadığını kontrol edin." },
    ar: { name: "بيلديرساي", desc: "منطقة تزلج من العهد السوفيتي عند سفح تشيمغان الكبرى، سُميت باسم جدول بيلديرساي الجبلي. يصعد بك مصعد كراسي طويل إلى جبل كومبيل، حيث تُطل إحدى أجمل الإطلالات على خزان تشارفاك والسلاسل المحيطة. يتزلج الناس هنا شتاءً، ويصعدون صيفًا من أجل المناظر والتنزه في المروج الألبية. تأكد من عمل المصاعد في يوم رحلتك." },
  },
  "tk-paltau": {
    zh: { name: "帕尔陶瀑布", desc: "恰尔瓦克水库附近帕尔陶河峡谷中的瀑布，是塔什干出发最受欢迎的一日徒步之一。沿着山溪的小路通往瀑布，四季皆美：春天水量充沛，夏天清凉，冬天挂满冰柱。同一山谷中还有旧石器时代的奥比拉赫马特岩洞。务必穿合适的鞋；雨后小路湿滑。" },
    ko: { name: "팔타우 폭포", desc: "차르바크 저수지 근처 팔타우강 협곡에 있는 폭포로, 타슈켄트에서 가장 인기 있는 당일 하이킹 코스 중 하나입니다. 산골짜기 개울을 따라 오솔길이 이어지며, 봄에는 물이 풍부하고 여름에는 시원하고 겨울에는 고드름이 매달려 사계절 내내 아름답습니다. 같은 계곡에 구석기 시대 오비라흐마트 동굴이 있습니다. 알맞은 신발은 필수이며, 비 온 뒤에는 길이 미끄럽습니다." },
    de: { name: "Paltau-Wasserfall", desc: "Ein Wasserfall in der Schlucht des Paltau-Flusses nahe dem Tscharwak-Stausee, eine der beliebtesten Tageswanderungen ab Taschkent. Ein Pfad am Gebirgsbach entlang führt hin, und der Fall ist zu jeder Jahreszeit schön: im Frühling wasserreich, im Sommer kühl, im Winter voller Eiszapfen. Im selben Tal liegt die paläolithische Grotte Obi-Rachmat. Gutes Schuhwerk ist Pflicht, nach Regen ist der Weg rutschig." },
    fr: { name: "Cascade de Paltaou", desc: "Une cascade dans la gorge de la rivière Paltaou près du réservoir de Tcharvak, l'une des randonnées d'une journée les plus prisées depuis Tachkent. Un sentier longe le torrent jusqu'à elle, belle en toute saison : abondante au printemps, fraîche en été, ornée de stalactites de glace en hiver. La grotte paléolithique d'Obi-Rakhmat se trouve dans la même vallée. De bonnes chaussures sont indispensables ; le sentier est glissant après la pluie." },
    ja: { name: "パルタウの滝", desc: "チャルヴァク貯水湖近くのパルタウ川の峡谷にある滝で、タシケントからの日帰りハイキングで最も人気のコースの一つです。渓流沿いの小道をたどると滝に着き、春は水量豊か、夏は涼しく、冬はつららに覆われと、四季を通じて美しい眺めです。同じ谷に旧石器時代のオビ・ラフマト洞窟があります。しっかりした靴は必須で、雨の後は道が滑りやすくなります。" },
    tr: { name: "Paltau Şelalesi", desc: "Çarvak Gölü yakınında Paltau nehri vadisinde bir şelale; Taşkent'ten en popüler günübirlik yürüyüşlerden biri. Dağ deresi boyunca bir patika şelaleye götürür; şelale her mevsim güzeldir: ilkbaharda gür, yazın serin, kışın buz saçaklarıyla kaplı. Aynı vadide Paleolitik Obi-Rahmat mağarası bulunur. Uygun ayakkabı şarttır; yağmurdan sonra patika kaygandır." },
    ar: { name: "شلال بالتاو", desc: "شلال في وادي نهر بالتاو قرب خزان تشارفاك، وهو من أشهر رحلات المشي ليوم واحد من طشقند. يقود إليه درب على امتداد الجدول الجبلي، والشلال جميل في كل الفصول: غزير في الربيع، منعش في الصيف، تتدلى منه الدلايات الجليدية في الشتاء. وفي الوادي نفسه كهف «أوبي رحمت» من العصر الحجري القديم. الحذاء المناسب ضروري، والدرب زلق بعد المطر." },
  },
  "tk-obirakhmat": {
    zh: { name: "奥比拉赫马特岩洞", desc: "帕尔陶河谷中海拔约1250米处的旧石器时代遗址，1962年在恰尔瓦克水库修建之前被发现。宽阔的岩洞（入口宽约20米、高近12米）中有22层堆积，出土了数千件石器和一名儿童的类尼安德特人牙齿——距今至少5万年。这是中亚最早历史的关键遗址之一；现场没有博物馆，只有岩洞和峡谷风光。" },
    ko: { name: "오비라흐마트 동굴", desc: "팔타우강 계곡 해발 약 1,250m에 있는 구석기 유적으로, 차르바크 저수지 건설 전인 1962년에 발견되었습니다. 입구 폭 약 20m, 높이 약 12m의 넓은 동굴에는 22개의 퇴적층이 있으며, 수천 점의 석기와 네안데르탈인과 비슷한 어린이의 이빨이 발견되었습니다. 최소 5만 년 전의 것입니다. 중앙아시아 초기 역사의 핵심 유적 중 하나이며, 현장에는 박물관 없이 동굴과 협곡 풍경만 있습니다." },
    de: { name: "Grotte Obi-Rachmat", desc: "Eine paläolithische Fundstätte im Tal des Paltau auf etwa 1.250 Metern, 1962 vor dem Bau des Tscharwak-Stausees entdeckt. Die weite Grotte (am Eingang etwa 20 m breit und fast 12 m hoch) birgt 22 Ablagerungsschichten, in denen Tausende Steinwerkzeuge und neandertalerähnliche Zähne eines Kindes gefunden wurden – mindestens 50.000 Jahre alt. Eine der Schlüsselstätten der frühesten Geschichte Zentralasiens; vor Ort gibt es kein Museum, nur die Grotte und den Blick in die Schlucht." },
    fr: { name: "Grotte d'Obi-Rakhmat", desc: "Un site paléolithique de la vallée du Paltaou, vers 1 250 mètres, découvert en 1962 avant la construction du réservoir de Tcharvak. La vaste grotte (environ 20 m de large à l'entrée et près de 12 m de haut) renferme 22 couches de dépôts où l'on a trouvé des milliers d'outils de pierre et des dents d'enfant de type néandertalien – vieilles d'au moins 50 000 ans. L'un des sites clés de la plus ancienne histoire de l'Asie centrale ; pas de musée sur place, seulement la grotte et la vue sur la gorge." },
    ja: { name: "オビ・ラフマト洞窟", desc: "パルタウ川の谷、標高約1250mにある旧石器時代の遺跡で、チャルヴァク貯水湖の建設前の1962年に発見されました。入口の幅約20m、高さ12m近い広い洞窟には22の堆積層があり、数千点の石器とネアンデルタール人に似た子どもの歯が見つかりました。少なくとも5万年前のものです。中央アジア最古の歴史を知る重要な遺跡の一つで、現地に博物館はなく、洞窟と渓谷の眺めがあるだけです。" },
    tr: { name: "Obi-Rahmat Mağarası", desc: "Paltau vadisinde yaklaşık 1.250 metrede, Çarvak Gölü yapılmadan önce 1962'de keşfedilen Paleolitik bir yerleşim. Geniş mağarada (girişte yaklaşık 20 m genişliğinde ve 12 m'ye yakın yüksekliğinde) 22 tortu katmanı vardır; bunlarda binlerce taş alet ve bir çocuğa ait Neandertal benzeri dişler bulundu – en az 50.000 yıllık. Orta Asya'nın en erken tarihinin kilit alanlarından biri; yerinde müze yoktur, yalnızca mağara ve vadi manzarası." },
    ar: { name: "كهف أوبي رحمت", desc: "موقع من العصر الحجري القديم في وادي نهر بالتاو على ارتفاع نحو 1250 مترًا، اكتُشف عام 1962 قبل بناء خزان تشارفاك. يضم الكهف الواسع (نحو 20 مترًا عرضًا عند المدخل وقرابة 12 مترًا ارتفاعًا) 22 طبقة من الرواسب عُثر فيها على آلاف الأدوات الحجرية وأسنان طفل شبيهة بأسنان إنسان نياندرتال – عمرها 50 ألف سنة على الأقل. من المواقع الرئيسية لأقدم تاريخ آسيا الوسطى، ولا متحف في المكان، بل الكهف ومنظر الوادي فقط." },
  },
  "tk-nanay": {
    zh: { name: "纳奈村", desc: "恰尔瓦克水库上游普斯凯姆河谷中的山村，四周是果园、核桃林和陡峭的山坡。从这里出发可以徒步去小瀑布，或沿湍急的普斯凯姆河散步，当地人出租房间并烹制家常饭菜。山谷再往上是边境区——开车上行之前请确认是否需要通行证。" },
    ko: { name: "나나이 마을", desc: "차르바크 저수지 위 프스켐 계곡에 있는 산골 마을로, 과수원과 호두나무 숲, 가파른 산비탈에 둘러싸여 있습니다. 이곳에서 작은 폭포나 세차게 흐르는 프스켐강을 따라 걷는 산책이 시작되며, 주민들이 방을 빌려 주고 집밥을 차려 줍니다. 계곡 위쪽은 국경 지대이니 더 올라가기 전에 허가가 필요한지 확인하세요." },
    de: { name: "Dorf Nanai", desc: "Ein Bergdorf im Pskem-Tal oberhalb des Tscharwak-Stausees, umgeben von Obstgärten, Walnusshainen und steilen Hängen. Von hier starten Wanderungen zu kleinen Wasserfällen und am rauschenden Pskem entlang, Einheimische vermieten Zimmer und kochen Hausmannskost. Weiter oben im Tal beginnt das Grenzgebiet – prüfen Sie, ob Sie eine Genehmigung brauchen, bevor Sie höher fahren." },
    fr: { name: "Village de Nanaï", desc: "Un village de montagne de la vallée du Pskem, au-dessus du réservoir de Tcharvak, entouré de vergers, de noyeraies et de pentes abruptes. Les promenades partent d'ici vers de petites cascades et le long du Pskem impétueux ; les habitants louent des chambres et cuisinent des plats maison. Plus haut dans la vallée commence une zone frontalière – vérifiez s'il faut un permis avant de monter." },
    ja: { name: "ナナイ村", desc: "チャルヴァク貯水湖の上流、プスケム渓谷にある山村で、果樹園やクルミの林、急な斜面に囲まれています。ここから小さな滝へのハイキングや激流のプスケム川沿いの散策が始まり、地元の人が部屋を貸して家庭料理をふるまいます。谷のさらに奥は国境地帯なので、上まで車で行く前に許可が必要か確認してください。" },
    tr: { name: "Nanay Köyü", desc: "Çarvak Gölü'nün yukarısında Pskem vadisinde, meyve bahçeleri, ceviz korulukları ve dik yamaçlarla çevrili bir dağ köyü. Küçük şelalelere ve coşkun Pskem boyunca yürüyüşler buradan başlar; yerliler oda kiralar ve ev yemekleri pişirir. Vadinin daha yukarısı sınır bölgesidir – daha yukarı çıkmadan önce izin gerekip gerekmediğini kontrol edin." },
    ar: { name: "قرية ناناي", desc: "قرية جبلية في وادي بسكيم فوق خزان تشارفاك، تحيط بها البساتين وأحراش الجوز والمنحدرات الشديدة. من هنا تبدأ نزهات المشي إلى شلالات صغيرة وعلى امتداد نهر بسكيم الهادر، ويؤجّر السكان غرفًا ويطبخون طعامًا منزليًا. أعلى الوادي منطقة حدودية – تحقّق مما إذا كنت تحتاج تصريحًا قبل الصعود بالسيارة." },
  },
  "tk-kumushkan": {
    zh: { name: "库穆什坎", desc: "帕尔肯特区西天山山麓的村庄，毗邻乌加姆—恰特卡尔国家公园。村名意为“银矿”：这里自古就开采白银，1950年起老矿附近建起了一座疗养院。如今这里是一处安静的休憩地，有泉水、山溪和林间小道；住宿和服务价格由当地度假村决定。" },
    ko: { name: "쿠무시칸", desc: "파르켄트 지구 서부 톈산 산기슭에 있는 마을로, 우감-차트칼 국립공원과 맞닿아 있습니다. 이름은 ‘은광’이라는 뜻으로, 예로부터 은을 캤으며 1950년부터 옛 광산 근처에 휴양소가 자리 잡았습니다. 지금은 샘과 산골 개울, 숲길이 있는 조용한 휴식처이며, 숙박과 서비스 가격은 현지 리조트마다 다릅니다." },
    de: { name: "Kumuschkan", desc: "Ein Dorf in den Vorbergen des westlichen Tianshan im Bezirk Parkent, neben dem Nationalpark Ugam-Tschatkal. Der Name bedeutet „Silbermine“: Hier wurde seit alters Silber abgebaut, und seit 1950 steht nahe der alten Mine ein Erholungsheim. Heute ist es ein ruhiger Rückzugsort mit Quellen, einem Gebirgsbach und Waldwegen; Unterkunft und Leistungen kosten je nach örtlichem Resort." },
    fr: { name: "Koumouchkan", desc: "Un village des contreforts du Tian Shan occidental, dans le district de Parkent, à côté du parc national d'Ougam-Tchatkal. Son nom signifie « mine d'argent » : on y extrayait l'argent depuis l'Antiquité, et depuis 1950 une maison de repos se dresse près de l'ancienne mine. C'est aujourd'hui une retraite paisible avec sources, torrent et sentiers forestiers ; hébergement et services selon les tarifs des établissements locaux." },
    ja: { name: "クムシュカン", desc: "パルケント地区、西天山の山麓にある村で、ウガム・チャトカル国立公園に隣接しています。村名は「銀の鉱山」を意味し、古くから銀が採掘され、1950年からは古い鉱山の近くに保養所が建っています。今は泉や渓流、森の小道のある静かな避暑地で、宿泊やサービスの料金は地元のリゾートごとに異なります。" },
    tr: { name: "Kumuşkan", desc: "Parkent ilçesinde, Batı Tanrı Dağları'nın eteklerinde, Ugam-Çatkal Milli Parkı'nın yanında bir köy. Adı “gümüş madeni” demektir: burada eski çağlardan beri gümüş çıkarıldı ve 1950'den beri eski madenin yakınında bir dinlenme tesisi bulunuyor. Bugün kaynakları, dağ deresi ve orman patikalarıyla sakin bir sığınaktır; konaklama ve hizmet fiyatlarını yerel tesisler belirler." },
    ar: { name: "كوموشكان", desc: "قرية في سفوح غرب تيان شان بمنطقة باركنت، بجوار حديقة أوغام-تشاتكال الوطنية. يعني اسمها «منجم الفضة»: فقد استُخرجت الفضة هنا منذ القدم، ومنذ عام 1950 تقوم دار استراحة قرب المنجم القديم. وهي اليوم ملاذ هادئ بينابيع وجدول جبلي ودروب في الغابة، وتحدد المنتجعات المحلية أسعار الإقامة والخدمات." },
  },
  "tk-sukok": {
    zh: { name: "苏科克", desc: "帕尔肯特区的一座山村，距塔什干一小时车程，有森林、泉水和苏科克赛溪。人们来这里享受凉爽的空气和美食：苏科克以烤肉串和用野山葱做的春季绿色萨姆萨“马多尔”闻名，只在4至5月烤制。周末这里挤满了从首都来的游客；工作日则很安静。" },
    ko: { name: "수코크", desc: "타슈켄트에서 차로 한 시간 거리인 파르켄트 지구의 산골 마을로, 숲과 샘, 수코크사이 개울이 있습니다. 사람들은 시원한 공기와 음식을 즐기러 옵니다. 수코크는 샤슬릭과 야생 산파로 만든 봄철 초록 삼사 ‘마도르’로 유명한데, 4~5월에만 굽습니다. 주말에는 수도에서 온 사람들로 붐비고, 평일에는 조용합니다." },
    de: { name: "Sukok", desc: "Ein Bergdorf im Bezirk Parkent, eine Autostunde von Taschkent, mit Wald, Quellen und dem Bach Sukoksai. Man kommt wegen der kühlen Luft und des Essens: Sukok ist berühmt für Schaschlik und die grüne Frühlings-Samsa „Mador“ mit wildem Bergzwiebellauch, die nur im April und Mai gebacken wird. Am Wochenende ist es voller Ausflügler aus der Hauptstadt, unter der Woche ruhig." },
    fr: { name: "Soukok", desc: "Un village de montagne du district de Parkent, à une heure de route de Tachkent, avec forêt, sources et le torrent Soukoksaï. On y vient pour l'air frais et la cuisine : Soukok est réputé pour ses chachliks et sa samsa verte de printemps « mador » à l'oignon sauvage des montagnes, cuite seulement en avril-mai. Le week-end, il se remplit de visiteurs de la capitale ; en semaine, c'est calme." },
    ja: { name: "スコク", desc: "タシケントから車で1時間のパルケント地区にある山村で、森や泉、スコクサイの小川があります。人々は涼しい空気と料理を楽しみに訪れます。スコクはシャシリクと、野生の山ネギを使った春の緑のサムサ「マドル」で有名で、4～5月にしか焼かれません。週末は首都からの客でにぎわい、平日は静かです。" },
    tr: { name: "Sukok", desc: "Taşkent'e bir saatlik yolda, Parkent ilçesinde ormanı, kaynakları ve Sukoksay deresi olan bir dağ köyü. Buraya serin hava ve yemekler için gelinir: Sukok, şişliği ve yalnızca Nisan–Mayıs'ta pişirilen yabani dağ soğanlı yeşil bahar samsası “mador” ile ünlüdür. Hafta sonları başkentten gelenlerle dolar; hafta içi sakindir." },
    ar: { name: "سوكوك", desc: "قرية جبلية في منطقة باركنت على بعد ساعة بالسيارة من طشقند، فيها غابة وينابيع وجدول سوكوكساي. يأتيها الناس من أجل الهواء المنعش والطعام: تشتهر سوكوك بالشاشليك وبسمبوسة الربيع الخضراء «مادور» المحشوة بالبصل الجبلي البري، ولا تُخبز إلا في أبريل ومايو. تمتلئ في عطلة نهاية الأسبوع بزوار العاصمة، وتكون هادئة في أيام العمل." },
  },
  "tk-ugamchatkal": {
    zh: { name: "乌加姆—恰特卡尔国家公园", desc: "塔什干东北方西天山中的大片保护区：乌加姆、普斯凯姆和恰特卡尔山脉，冰川、高山草甸、刺柏林和湍急的河流。这里生活着雪豹、熊、北山羊和旱獭，山坡上生长着野苹果、核桃和郁金香。恰尔瓦克、奇姆甘以及普斯凯姆和乌加姆河谷都在公园范围内。如要深入徒步，请询问允许的路线和许可证。" },
    ko: { name: "우감-차트칼 국립공원", desc: "타슈켄트 북동쪽 서부 톈산의 광대한 보호구역으로, 우감·프스켐·차트칼 산맥과 빙하, 고산 초원, 향나무 숲, 거센 강이 있습니다. 눈표범, 곰, 아이벡스, 마멋이 살고, 산비탈에는 야생 사과, 호두, 튤립이 자랍니다. 차르바크, 침간, 프스켐과 우감 계곡이 모두 공원 안에 있습니다. 깊이 들어가는 트레킹은 허용된 경로와 허가를 문의하세요." },
    de: { name: "Nationalpark Ugam-Tschatkal", desc: "Ein riesiges Schutzgebiet im westlichen Tianshan nordöstlich von Taschkent: die Ketten Ugam, Pskem und Tschatkal, Gletscher, Almwiesen, Wacholderwälder und reißende Flüsse. Hier leben Schneeleoparden, Bären, Steinböcke und Murmeltiere, an den Hängen wachsen Wildäpfel, Walnüsse und Tulpen. Tscharwak, Tschimgan sowie die Täler von Pskem und Ugam liegen alle im Park. Für Touren tief hinein nach erlaubten Routen und Genehmigungen fragen." },
    fr: { name: "Parc national d'Ougam-Tchatkal", desc: "Une vaste aire protégée du Tian Shan occidental au nord-est de Tachkent : chaînes d'Ougam, du Pskem et du Tchatkal, glaciers, alpages, forêts de genévriers et rivières tumultueuses. Léopards des neiges, ours, bouquetins et marmottes y vivent, et pommiers sauvages, noyers et tulipes poussent sur les pentes. Tcharvak, Tchimgan et les vallées du Pskem et de l'Ougam se trouvent toutes dans le parc. Pour les randonnées au cœur du parc, renseignez-vous sur les itinéraires autorisés et les permis." },
    ja: { name: "ウガム・チャトカル国立公園", desc: "タシケントの北東、西天山に広がる広大な保護区で、ウガム、プスケム、チャトカルの山脈、氷河、高山草原、ビャクシンの森、急流の川があります。ユキヒョウ、クマ、アイベックス、マーモットが暮らし、斜面には野生のリンゴ、クルミ、チューリップが育ちます。チャルヴァク、チムガン、プスケムとウガムの谷はすべて公園内にあります。奥地へのハイキングは許可ルートと許可証について確認を。" },
    tr: { name: "Ugam-Çatkal Milli Parkı", desc: "Taşkent'in kuzeydoğusunda Batı Tanrı Dağları'nda geniş bir koruma alanı: Ugam, Pskem ve Çatkal sıradağları, buzullar, alpin çayırları, ardıç ormanları ve coşkun nehirler. Kar leoparları, ayılar, dağ keçileri ve dağ sıçanları yaşar; yamaçlarda yabani elma, ceviz ve laleler yetişir. Çarvak, Çimgan, Pskem ve Ugam vadileri parkın içindedir. Derinlere yürüyüş için izin verilen rotaları ve izinleri sorun." },
    ar: { name: "حديقة أوغام-تشاتكال الوطنية", desc: "محمية شاسعة في غرب تيان شان شمال شرق طشقند: سلاسل أوغام وبسكيم وتشاتكال، والأنهار الجليدية، والمروج الألبية، وغابات العرعر، والأنهار المتدفقة. تعيش فيها النمور الثلجية والدببة والوعول والمرموط، وتنمو على المنحدرات التفاحيات البرية والجوز والتوليب. وتقع تشارفاك وتشيمغان ووديا بسكيم وأوغام كلها داخل الحديقة. للتوغل في الرحلات اسأل عن المسارات المسموح بها والتصاريح." },
  },
  "tk-pskem": {
    zh: { name: "普斯凯姆河谷", desc: "普斯凯姆山河的河谷，这条河发源于塔拉斯阿拉套的冰川，流入恰尔瓦克水库。河流在乌加姆山和普斯凯姆山之间宽阔的河谷中奔流40多公里：两岸是苹果、梨、杏和核桃林，山中生活着熊、豪猪和旱獭。河谷上方的艾纳塔什岩是热门观景点。河谷上游是边境区，需要通行证。" },
    ko: { name: "프스켐 계곡", desc: "탈라스 알라타우 빙하에서 발원해 차르바크 저수지로 흘러드는 프스켐 산골 강의 계곡입니다. 강은 우감과 프스켐 산맥 사이 넓은 계곡을 40km 넘게 흐르며, 강가에는 사과·배·살구·호두 숲이 있고 산에는 곰, 호저, 마멋이 삽니다. 계곡 위 아이나타시 바위는 인기 전망 지점입니다. 상류는 국경 지대로 허가가 필요합니다." },
    de: { name: "Pskem-Tal", desc: "Das Tal des Gebirgsflusses Pskem, der in den Gletschern des Talas-Alatau entspringt und in den Tscharwak-Stausee mündet. Über mehr als 40 Kilometer fließt er durch ein weites Tal zwischen Ugam- und Pskem-Kette: An seinen Ufern wachsen Apfel-, Birnen-, Aprikosen- und Walnusshaine, in den Bergen leben Bären, Stachelschweine und Murmeltiere. Der Aynatasch-Felsen über dem Tal ist ein beliebter Aussichtspunkt. Das obere Tal ist Grenzgebiet und erfordert eine Genehmigung." },
    fr: { name: "Vallée du Pskem", desc: "La vallée de la rivière de montagne Pskem, qui naît dans les glaciers de l'Alataou de Talas et se jette dans le réservoir de Tcharvak. Sur plus de 40 kilomètres, elle coule dans une large vallée entre les chaînes de l'Ougam et du Pskem : pommiers, poiriers, abricotiers et noyers bordent ses rives, et ours, porcs-épics et marmottes peuplent les montagnes. Le rocher d'Aïnatach au-dessus de la vallée est un belvédère prisé. La haute vallée est une zone frontalière soumise à permis." },
    ja: { name: "プスケム渓谷", desc: "タラス・アラタウの氷河に発し、チャルヴァク貯水湖に注ぐ山の川プスケムの谷です。川はウガム山脈とプスケム山脈の間の広い谷を40km以上流れ、岸辺にはリンゴ、ナシ、アンズ、クルミの林が続き、山にはクマ、ヤマアラシ、マーモットが暮らします。谷を見下ろすアイナタシュ岩は人気の展望地です。上流は国境地帯で許可が必要です。" },
    tr: { name: "Pskem Vadisi", desc: "Talas Alatau buzullarından doğup Çarvak Gölü'ne dökülen Pskem dağ nehrinin vadisi. Nehir 40 kilometreden fazla Ugam ve Pskem sıradağları arasındaki geniş bir vadide akar: kıyılarında elma, armut, kayısı ve ceviz korulukları vardır, dağlarda ayılar, kirpiler ve dağ sıçanları yaşar. Vadinin üzerindeki Aynataş kayası popüler bir seyir noktasıdır. Yukarı vadi sınır bölgesidir ve izin gerektirir." },
    ar: { name: "وادي بسكيم", desc: "وادي نهر بسكيم الجبلي الذي ينبع من أنهار تالاس ألاتاو الجليدية ويصب في خزان تشارفاك. يجري النهر أكثر من 40 كيلومترًا في وادٍ فسيح بين سلسلتي أوغام وبسكيم: تحف ضفافه بساتين التفاح والإجاص والمشمش والجوز، وتعيش في الجبال الدببة والنيص والمرموط. وصخرة «أيناتاش» فوق الوادي نقطة مشاهدة شهيرة. أعلى الوادي منطقة حدودية تتطلب تصريحًا." },
  },
  "tk-ugam": {
    zh: { name: "乌加姆河", desc: "一条近70公里长的湍急山河，是奇尔奇克河最大的右支流，从哈萨克斯坦流向恰尔瓦克。乌加姆河谷有森林、草地和小桥，是徒步和野餐的好去处，沿河的小路通往林场站及更远处。春季和初夏河水猛涨——游泳很危险，不建议涉水。" },
    ko: { name: "우감강", desc: "길이 약 70km의 빠른 산골 강으로, 치르치크강의 가장 큰 오른쪽 지류이며 카자흐스탄에서 차르바크 방향으로 흐릅니다. 숲과 초원, 작은 다리가 있는 우감 계곡은 하이킹과 피크닉 명소로, 강을 따라 산림 관리소와 그 너머까지 오솔길이 이어집니다. 봄과 초여름에는 물이 불어나 수영은 위험하고 걸어서 건너는 것은 권하지 않습니다." },
    de: { name: "Fluss Ugam", desc: "Ein reißender Gebirgsfluss von fast 70 km Länge, der größte rechte Nebenfluss des Tschirtschik, der aus Kasachstan Richtung Tscharwak fließt. Das Ugam-Tal mit Wäldern, Wiesen und Stegen ist beliebt für Wanderungen und Picknicks; Wege führen am Fluss entlang bis zur Forststation und darüber hinaus. Im Frühling und Frühsommer führt der Fluss Hochwasser – Baden ist gefährlich, Durchwaten wird nicht empfohlen." },
    fr: { name: "Rivière Ougam", desc: "Une rivière de montagne rapide de près de 70 km, principal affluent de rive droite du Tchirtchik, qui coule du Kazakhstan vers Tcharvak. La vallée de l'Ougam, avec forêts, prairies et passerelles, est appréciée pour les randonnées et pique-niques ; des sentiers longent la rivière jusqu'à la maison forestière et au-delà. Au printemps et au début de l'été, les eaux sont hautes – baignade dangereuse, passage à gué déconseillé." },
    ja: { name: "ウガム川", desc: "長さ約70kmの急流の山の川で、チルチク川最大の右支流としてカザフスタンからチャルヴァク方面へ流れます。森や草原、小さな橋のあるウガム渓谷はハイキングやピクニックに人気で、川沿いの小道が営林署やその先まで続きます。春から初夏は増水するので、泳ぐのは危険で、徒歩での渡渉はおすすめしません。" },
    tr: { name: "Ugam Nehri", desc: "Yaklaşık 70 km uzunluğunda hızlı bir dağ nehri; Çirçik'in en büyük sağ kolu olup Kazakistan'dan Çarvak'a doğru akar. Ormanları, çayırları ve küçük köprüleriyle Ugam vadisi yürüyüş ve piknik için sevilir; nehir boyunca orman işletmesine ve ötesine patikalar uzanır. İlkbahar ve yaz başında nehir yükselir – yüzmek tehlikelidir, yürüyerek geçmek önerilmez." },
    ar: { name: "نهر أوغام", desc: "نهر جبلي سريع يقارب طوله 70 كم، وهو أكبر روافد نهر تشيرتشيك من الضفة اليمنى، يجري من كازاخستان نحو تشارفاك. وادي أوغام بغاباته ومروجه وجسوره الصغيرة مقصد مفضل للمشي والنزهات، وتمتد الدروب على امتداد النهر حتى محطة الغابات وما بعدها. في الربيع وأوائل الصيف يرتفع منسوب النهر – السباحة خطرة ولا يُنصح بالعبور مشيًا." },
  },
  "tk-yangiabad": {
    zh: { name: "扬吉阿巴德", desc: "安格连上方的一座山城，建于20世纪50年代初，原是一个封闭的铀矿工人定居点。矿井早已关闭，如今扬吉阿巴德是塔什干居民安静的避暑地：清新的山间空气、溪流、长满松树的山坡，距镇几公里处还有一处矿泉。是在恰特卡尔山脉支脉徒步的好基地。" },
    ko: { name: "양기아바드", desc: "안그렌 위에 있는 산골 소도시로, 1950년대 초 폐쇄된 우라늄 광산 정착지로 건설되었습니다. 광산은 오래전에 문을 닫았고, 지금 양기아바드는 타슈켄트 사람들의 조용한 여름 휴양지입니다. 맑은 산 공기, 개울, 소나무가 덮인 비탈이 있고 몇 km 떨어진 곳에 광천이 있습니다. 차트칼 산맥 지맥 하이킹의 좋은 거점입니다." },
    de: { name: "Yangiabad", desc: "Eine Bergstadt oberhalb von Angren, Anfang der 1950er-Jahre als geschlossene Uranbergbausiedlung erbaut. Die Minen sind längst stillgelegt, und heute ist Yangiabad ein ruhiger Sommerort der Taschkenter: saubere Bergluft, Bäche, kieferbedeckte Hänge und eine Mineralquelle einige Kilometer von der Stadt. Ein guter Ausgangspunkt für Wanderungen in den Ausläufern der Tschatkal-Kette." },
    fr: { name: "Iangiabad", desc: "Une ville de montagne au-dessus d'Angren, bâtie au début des années 1950 comme cité fermée d'extraction d'uranium. Les mines sont fermées depuis longtemps, et Iangiabad est aujourd'hui un paisible lieu de villégiature estivale pour les habitants de Tachkent : air pur de montagne, ruisseaux, pentes couvertes de pins et source minérale à quelques kilomètres. Une bonne base pour randonner dans les contreforts du Tchatkal." },
    ja: { name: "ヤンギアバド", desc: "アングレンの上にある山の町で、1950年代初めに閉鎖されたウラン鉱山の集落として建設されました。鉱山はとうに閉鎖され、今ではタシケントの人々の静かな避暑地です。澄んだ山の空気、小川、松に覆われた斜面があり、町から数km離れたところに鉱泉があります。チャトカル山脈の支脈を歩く拠点に最適です。" },
    tr: { name: "Yangiabad", desc: "Angren'in yukarısında, 1950'lerin başında kapalı bir uranyum madenciliği yerleşimi olarak kurulan bir dağ kasabası. Madenler çoktan kapandı; bugün Yangiabad Taşkentlilerin sakin bir yazlık kaçış yeridir: temiz dağ havası, dereler, çamlarla kaplı yamaçlar ve kasabaya birkaç kilometre mesafede bir maden suyu kaynağı. Çatkal sıradağlarının uzantılarında yürüyüşler için iyi bir üs." },
    ar: { name: "يانغي آباد", desc: "بلدة جبلية فوق أنغرين، بُنيت مطلع خمسينيات القرن الماضي مستوطنةً مغلقة لتعدين اليورانيوم. أُغلقت المناجم منذ زمن، ويانغي آباد اليوم مصيف هادئ لسكان طشقند: هواء جبلي نقي، وجداول، ومنحدرات مكسوة بالصنوبر، ونبع معدني على بعد بضعة كيلومترات. قاعدة جيدة للمشي في امتدادات سلسلة تشاتكال." },
  },
  "tk-khumsan": {
    zh: { name: "胡姆桑", desc: "博斯坦雷克区的一个村庄，位于乌加姆山脚下，离恰尔瓦克水库不远。周围的果园和丘陵间有疗养院、夏令营和度假村，从这里有小路通往乌加姆河谷。适合安静地度过周末；住宿价格由各度假村决定。" },
    ko: { name: "훔산", desc: "보스탄리크 지구 우감 산맥 기슭, 차르바크 저수지에서 멀지 않은 마을입니다. 과수원과 구릉 사이에 요양원, 캠프, 리조트가 있고, 이곳에서 우감 계곡으로 오솔길이 이어집니다. 조용한 주말을 보내기 좋으며, 숙박 요금은 리조트마다 다릅니다." },
    de: { name: "Chumsan", desc: "Ein Dorf im Bezirk Bostanliq am Fuß der Ugam-Kette, unweit des Tscharwak-Stausees. Ringsum liegen Sanatorien, Ferienlager und Resorts zwischen Obstgärten und Vorbergen, und Wege führen von hier ins Ugam-Tal. Ein guter Ort für ein ruhiges Wochenende; die Unterkunftspreise legen die einzelnen Resorts fest." },
    fr: { name: "Khoumsan", desc: "Un village du district de Bostanlyk au pied de la chaîne de l'Ougam, non loin du réservoir de Tcharvak. Autour, sanatoriums, colonies de vacances et complexes parmi vergers et collines ; des sentiers partent d'ici vers la vallée de l'Ougam. Idéal pour un week-end tranquille ; tarifs d'hébergement fixés par chaque établissement." },
    ja: { name: "フムサン", desc: "ボスタンリク地区、ウガム山脈の麓にある村で、チャルヴァク貯水湖からそう遠くありません。周囲の果樹園や丘陵には療養所、キャンプ場、リゾートがあり、ここからウガム渓谷へ小道が続きます。静かな週末を過ごすのに良い場所で、宿泊料金はリゾートごとに異なります。" },
    tr: { name: "Humsan", desc: "Bostanlık ilçesinde Ugam sıradağlarının eteğinde, Çarvak Gölü'ne yakın bir köy. Çevresinde meyve bahçeleri ve tepeler arasında sanatoryumlar, tatil kampları ve tesisler vardır; buradan Ugam vadisine patikalar uzanır. Sakin bir hafta sonu için iyi bir yer; konaklama fiyatlarını tesisler belirler." },
    ar: { name: "خومسان", desc: "قرية في منطقة بوستانليق عند سفح سلسلة أوغام، غير بعيدة عن خزان تشارفاك. حولها مصحات ومخيمات صيفية ومنتجعات بين البساتين والتلال، ومنها تنطلق دروب إلى وادي أوغام. مكان مناسب لعطلة نهاية أسبوع هادئة، وتحدد كل منتجعات أسعار الإقامة." },
  },
  "tk-solarfurnace": {
    zh: { name: "乌兹别克斯坦太阳炉（帕尔肯特）", desc: "世界上最大的太阳炉之一，1981至1987年建于距塔什干45公里的帕尔肯特附近山丘上。山坡上62面镜面定日镜捕捉阳光，把它反射到一个54×47米的巨大凹面聚光镜上，聚光镜把光线聚焦到一点，温度可达3000°C。选址于此是因为这里每年有250至270个晴天和清澈的山间空气。2026年该综合体与塔什干现代主义建筑一起被列入联合国教科文组织世界遗产名录；导览按时间表进行。" },
    ko: { name: "우즈베키스탄 태양로(파르켄트)", desc: "1981~1987년 타슈켄트에서 45km 떨어진 파르켄트 근처 언덕에 세워진 세계 최대급 태양로입니다. 비탈에 늘어선 62개의 거울 헬리오스탯이 햇빛을 받아 54×47m의 거대한 오목 집광기로 보내고, 집광기는 빛을 한 점에 모아 3,000°C까지 끌어올립니다. 연간 250~270일의 맑은 날과 깨끗한 산 공기 덕분에 이곳이 선택되었습니다. 2026년 타슈켄트 모더니즘 건축물과 함께 유네스코 세계유산에 등재되었으며, 가이드 투어는 일정에 따라 운영됩니다." },
    de: { name: "Sonnenofen Usbekistans (Parkent)", desc: "Einer der größten Sonnenöfen der Welt, 1981–1987 in den Hügeln bei Parkent, 45 km von Taschkent, gebaut. Zweiundsechzig verspiegelte Heliostaten am Hang fangen das Sonnenlicht ein und lenken es auf einen riesigen Hohlspiegel von 54 × 47 m, der die Strahlen auf einen Punkt mit bis zu 3.000 °C bündelt. Der Ort wurde wegen 250–270 Sonnentagen im Jahr und klarer Bergluft gewählt. 2026 wurde die Anlage mit Denkmälern der Taschkenter Moderne in die UNESCO-Welterbeliste aufgenommen; Führungen nach Plan." },
    fr: { name: "Four solaire d'Ouzbékistan (Parkent)", desc: "L'un des plus grands fours solaires du monde, construit en 1981–1987 dans les collines près de Parkent, à 45 km de Tachkent. Soixante-deux héliostats à miroirs sur la pente captent le soleil et le renvoient vers un gigantesque concentrateur concave de 54 × 47 m, qui focalise les rayons en un point atteignant 3 000 °C. Le site a été choisi pour ses 250 à 270 jours de soleil par an et son air de montagne limpide. En 2026, le complexe a été inscrit au patrimoine mondial de l'UNESCO avec les monuments du modernisme de Tachkent ; visites guidées selon un horaire." },
    ja: { name: "ウズベキスタン太陽炉（パルケント）", desc: "1981～1987年、タシケントから45kmのパルケント近郊の丘に建設された世界最大級の太陽炉です。斜面に並ぶ62基の鏡のヘリオスタットが太陽光をとらえ、54×47mの巨大な凹面集光鏡へ送り、集光鏡は光を一点に集めて最高3000°Cに達します。年間250～270日の晴天と澄んだ山の空気からこの地が選ばれました。2026年、タシケント・モダニズムの建築とともにユネスコ世界遺産に登録されました。ガイドツアーは予定に沿って行われます。" },
    tr: { name: "Özbekistan Güneş Fırını (Parkent)", desc: "Dünyanın en büyük güneş fırınlarından biri; 1981–1987'de Taşkent'e 45 km uzaklıktaki Parkent yakınındaki tepelerde inşa edildi. Yamaçtaki altmış iki aynalı heliostat güneşi yakalayıp 54 × 47 m'lik dev içbükey yoğunlaştırıcıya yönlendirir; yoğunlaştırıcı ışınları 3.000 °C'ye ulaşan bir noktada toplar. Yer, yılda 250–270 güneşli günü ve berrak dağ havası nedeniyle seçildi. 2026'da kompleks Taşkent modernizminin anıtlarıyla birlikte UNESCO Dünya Mirası Listesi'ne alındı; rehberli turlar programa göre yapılır." },
    ar: { name: "الفرن الشمسي في أوزبكستان (باركنت)", desc: "من أكبر الأفران الشمسية في العالم، بُني بين 1981 و1987 في التلال قرب باركنت على بعد 45 كم من طشقند. تلتقط اثنتان وستون مرآة متتبعة للشمس على المنحدر أشعتها وتوجهها إلى مركِّز مقعّر عملاق بأبعاد 54 × 47 مترًا، يجمع الأشعة في نقطة تصل حرارتها إلى 3000 درجة مئوية. اختير الموقع لأيامه المشمسة البالغة 250 إلى 270 يومًا في السنة وهوائه الجبلي الصافي. وفي عام 2026 أُدرج المجمع مع معالم حداثة طشقند في قائمة التراث العالمي لليونسكو، والجولات المصحوبة بمرشد وفق جدول." },
  },
  "tk-kurama": {
    zh: { name: "库拉明山脉与阿汉加兰河谷", desc: "天山的西南支脉，把塔什干州与费尔干纳盆地分开。塔什干—费尔干纳主干道经卡姆奇克山口翻越山脉，从那里可以眺望山坡，山下是阿汉加兰水库和山间河谷。库拉明山中保存着中世纪矿井的遗迹——几个世纪以来人们在这里开采白银和铜，供伊拉克的造币厂使用。适合开车玩一整天；春天山坡开满鲜花。" },
    ko: { name: "쿠라마 산맥과 아한가란 계곡", desc: "타슈켄트주와 페르가나 분지를 가르는 톈산의 남서쪽 지맥입니다. 타슈켄트-페르가나 간선 도로가 캄치크 고개로 산맥을 넘으며 산비탈 풍경이 펼쳐지고, 아래로는 아한가란 저수지와 산골 강 계곡이 놓여 있습니다. 쿠라마 산에는 수 세기 동안 일라크 조폐소를 위해 은과 구리를 캐던 중세 광산의 흔적이 남아 있습니다. 하루 드라이브 코스로 좋으며, 봄이면 산비탈이 꽃으로 뒤덮입니다." },
    de: { name: "Kurama-Kette und Achangaran-Tal", desc: "Ein südwestlicher Ausläufer des Tianshan, der die Region Taschkent vom Ferghanatal trennt. Die Hauptstraße Taschkent–Fergana überquert die Kette am Kamtschik-Pass mit Blick auf die Berghänge, unten liegen der Achangaran-Stausee und die Täler der Gebirgsflüsse. In den Kurama-Bergen sind Spuren mittelalterlicher Minen erhalten, in denen jahrhundertelang Silber und Kupfer für die Münzstätten von Ilak abgebaut wurden. Ein gutes Ziel für eine Tagesfahrt; im Frühling blühen die Hänge." },
    fr: { name: "Chaîne de Kourama et vallée de l'Akhangaran", desc: "Un contrefort sud-ouest du Tian Shan qui sépare la région de Tachkent de la vallée de Ferghana. La grande route Tachkent–Ferghana franchit la chaîne par le col de Kamtchik, avec vue sur les pentes, tandis que le réservoir d'Akhangaran et les vallées des torrents s'étendent en contrebas. Des traces de mines médiévales subsistent dans les monts Kourama, où l'on extrayait pendant des siècles l'argent et le cuivre pour les ateliers monétaires d'Ilak. Une belle destination pour une journée en voiture ; au printemps, les pentes se couvrent de fleurs." },
    ja: { name: "クラマ山脈とアハンガラン渓谷", desc: "タシケント州とフェルガナ盆地を隔てる天山山脈の南西の支脈です。タシケント～フェルガナ間の幹線道路がカムチク峠で山脈を越え、山の斜面の眺めが広がり、下にはアハンガラン貯水湖と山の川の谷が横たわります。クラマ山中には、何世紀にもわたってイラクの造幣所のために銀や銅を掘った中世の鉱山の跡が残っています。1日ドライブにぴったりで、春は斜面が花で覆われます。" },
    tr: { name: "Kurama Sıradağları ve Ahangaran Vadisi", desc: "Taşkent bölgesini Fergana Vadisi'nden ayıran Tanrı Dağları'nın güneybatı uzantısı. Taşkent–Fergana ana yolu sıradağı Kamçık geçidinden aşar; dağ yamaçlarının manzarası görünür, aşağıda Ahangaran Barajı ve dağ nehirlerinin vadileri uzanır. Kurama dağlarında, yüzyıllarca İlak darphaneleri için gümüş ve bakır çıkarılan Orta Çağ madenlerinin izleri korunmuştur. Bir günlük araba gezisi için iyi bir hedef; ilkbaharda yamaçlar çiçeklerle kaplanır." },
    ar: { name: "سلسلة قوراما ووادي أهنغران", desc: "امتداد جنوبي غربي لجبال تيان شان يفصل ولاية طشقند عن وادي فرغانة. يعبر الطريق الرئيسي طشقند–فرغانة السلسلة عبر ممر كامتشيك مع إطلالة على المنحدرات، وفي الأسفل خزان أهنغران ووديان الأنهار الجبلية. وفي جبال قوراما آثار مناجم من العصور الوسطى استُخرجت منها الفضة والنحاس قرونًا لدور سكّ النقود في إيلاق. وجهة جيدة لرحلة بالسيارة ليوم كامل، وفي الربيع تكتسي المنحدرات بالزهور." },
  },
};
